quests[25233] = { id = 25233, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Ende der Versorgungslinie", description = "Cho'galls Zwielichtordner schwören einen Bluteid, dass sie ihre Vorräte bis an die Front schaffen. Sie geloben sogar, für jedes nicht gelieferte Pfund Vorräte mit einem Pfund ihres eigenen Fleisches zu bezahlen. Sie würden lieber sterben als zu scheitern.\n\nSorgt dafür, dass sie beides tun.", sourceObjective = "Tötet 4 Zwielichtordner in der Wolfsschlucht auf dem Hyjal.", completion = "Gut gemacht! Das Chaos, das wir hier anrichten, wird sich durch die gesamte Befehlskette ziehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25234] = { id = 25234, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arme Deppen schleppen", description = "Gefangene des Schattenhammerklans werden dazu gezwungen, verschiedene für den Krieg benötigte Dinge wie Packtiere herumzuschleppen. Ich will diese Vorräte - und wenn wir dabei ein paar arme Seelen aus den Klauen des Schattenhammers befreien können, umso besser.\n\nTötet die Sklaventreiber entlang der Straße im Süden und die Sklaven in ihrer Nähe sollten in der Lage sein, zu entfliehen.\n\nDurchsucht die Rucksäcke, die sie hinterlassen, nach wertvollen Dingen und zerstört alles, was Ihr nicht tragen könnt.", sourceObjective = "Sammelt 36 Versorgungsgüter des Schattenhammers, die von befreiten Zwielichtsklaven zurückgelassen wurden.", progress = "Habt Ihr da unten ein wenig Zerstörung angerichtet, {name}?", completion = "<Jadi tritt eine der Kisten mit dem Fuß auf und zieht einen geschwungenen Dolch daraus hervor. Sofort fängt sie an zu wimmern.>\n\nAutsch! Verdammt! Dieses Metall ist verflucht. Es beißt!\n\n<Als der Dolch zu Boden fällt, zerspringt er in tausend Stücke, als wäre er aus dünnem Glas.>\n\nWas für eine geisteskranke Schmiedekunst ist das? {name}, ich bin noch nie zuvor auf solch einen Feind getroffen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25235] = { id = 25235, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vulgäres Vul'Gol", description = "Grüße, {class}. Wollt Ihr die Bewohner von Dunkelhain unterstützen?\n\nDirekt hinter dieser Hügelkuppe da drüben gibt es einen riesigen Ogerhort. Die Oger der Splitterfäuste bleiben normalerweise unter sich, aber sie haben die schlechte Angewohnheit, Reisende zu überfallen. Gerade neulich habe ich gesehen, wie einer das Pferd eines armen Mannes fortgeschleppt hat, um es zu fressen... Zum Glück hat er ihn nicht mitgenommen!\n\nDie Nachtwache möchte das Leben ihrer wenigen Mitglieder, darunter auch meines, jedoch nur für dringlichere Bedrohungen riskieren. Wenn Ihr ein paar dieser Oger für mich töten würdet, würde ich Euch für Eure Tat belohnen.", sourceObjective = "Tötet 15 Oger der Splitterfäuste.", progress = "Wenn Ihr lieber im Lager herumlungern und Euch ein, zwei Bierchen genehmigen wollt... nun, vorschreiben kann ich Euch nichts.", completion = "Ich habe von hier aus gesehen, wie Ihr ein paar von ihnen den Garaus gemacht habt. Gute Arbeit.\n\nHiermit überreiche ich Euch im Namen der Nachtwache Eure Belohnung.", sourceObjectiveStatus = "unverified-source-field" }
quests[25236] = { id = 25236, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Donner von unten", description = "Unsere Armee braucht Wasser, und das haben wir dank der Elemente nach dem Kataklysmus jetzt reichlich. Das Wasser, das die Schlucht südwestlich von hier gefüllt hat, sollte ausreichen.\n\nLeider sind die Leichname der Donnerechsen noch überall unten in der Schlucht, und die elektrischen Stöße, die sie von sich geben, sind ein bisschen gefährlich. Ich habe Grunzer, die sie aus dem Wasser ziehen können, aber ich brauche jemand, der geschickt genug ist, sie am anderen Ende des Seils zu befestigen. Seid Ihr <der Mann, den/die Frau> die; ich suche?", sourceObjective = "Befestigt die Magiestoffleine an 8 ertrunkenen Donnerechsen im Donnergrat.", completion = "Die Elektrizität der Echsen war nur eine Gefahr. Wenn die Kadaver zu lange im Wasser geblieben wären und weitergerottet hätten, wäre das Wasser bald nicht mehr trinkbar gewesen.\n\nIhr habt gute Arbeit geleistet.", sourceObjectiveStatus = "unverified-source-field" }
quests[25237] = { id = 25237, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tränen der Steine", description = "Ihr habt gehört, wie der Drache Ysondre uns erklärt hat, dass die Tränen des Landes das Portal schließen können, aus dem die Verderbnis strömt.\n\nVor einigen Wochen habe ich in dem Tal westlich von hier gesehen, dass es den Bergriesen schlecht ging. Sie waren wild vor Frustration, und als sie weinten, wurden ihre Tränen, die auf die Steine fielen, zu Kristallen.\n\nDie Riesen weinen zwar nicht mehr, aber diese Steintränen sind wohl das, was Ysondre gemeint hat - eine Quelle reiner Natur. Wir brauchen diese Tränen.", sourceObjective = "Sammelt 7 Steintränen.", progress = "Die Tränen sind auf den Steinen, aus denen die Riesen entstanden. In der Nähe der Monolithen am Fuß des Berges sollten lose Tränen zu finden sein.", completion = "Ich danke Euch erneut, {name}. Ich werde die Tränen für unsere letzte Aufgabe vorbereiten.", sourceObjectiveStatus = "unverified-source-field" }
quests[25239] = { id = 25239, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weg der Macht", progress = "Ihr wollt also tätsächlich weiter dem Weg der Macht folgen?", completion = "Ihr stellt Euren Wert wieder unter Beweis, {name}. Nehmt dies, nicht als Geschenk, sondern als Werkzeug im Kampf gegen die Geißel." }
quests[25240] = { id = 25240, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weg der Macht", progress = "Ihr wollt also tätsächlich weiter dem Weg der Macht folgen?", completion = "Ihr stellt Euren Wert wieder unter Beweis, {name}. Nehmt dies, nicht als Geschenk, sondern als Werkzeug im Kampf gegen die Geißel." }
quests[25241] = { id = 25241, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das verderbte Land", description = "Die Klippenriesen von Feralas sind Ausläufer der Erde selbst, {name}. Wenn es der Natur gut geht, so sind sie wohlwollende Beschützer und friedliche Wächter.\n\nDoch wenn der Wald leidet, so leiden auch sie.\n\nWenn sie von dieser Krankheit heimgesucht und verderbt wurden, so werden sie sich gewaltvoll gegen die Wildtiere und selbst gegen Ihresgleichen richten und so für großflächige Zerstörung sorgen.\n\nZerstört alle verderbten Riesen, die Ihr finden könnt.", sourceObjective = "Tötet 7 verderbte Klippenriesen.", completion = "Die Geister der Beschützer werden wieder zurückkehren, {name}. Ihr habt sie befreit und nun können sie im Kreislauf der Natur ihre Wege gehen.\n\nJetzt liegt es an uns, sicherzustellen, dass der Kreislauf frei von Verderbnis und grundlosem Schmerz ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[25242] = { id = 25242, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weg der Macht", progress = "Ihr wollt also tätsächlich weiter dem Weg der Macht folgen?", completion = "{name}. Niemand kann für sich beanspruchen, den Kampf mit mehr Hingabe zu unterstützen als Ihr.\n\nEs wird gemunkelt, dass die Lakaien der Geißel Euch mehr fürchten als den Lichkönig selber." }
quests[25243] = { id = 25243, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sie liebt mich, sie liebt mich NICHT!", description = "Oh, Süßer! Ihr werdet nie glauben, wer sich in den Sklavengruben im Norden aufhält.\n\n<Sassy schüttelt traurig den Kopf.>\n\nVani ist da unten und arbeitet für den Handelsprinzen. Diese kaltherzige Schlange hat Euch wie eine heiße Kartoffel fallenlassen und jetzt arbeitet sie auch noch für die anderen. Seit Ihr Euch um Chip \"gekümmert\" habt, trifft sie sich mit dem Handelsprinzen!\n\nIch weiß ja nicht, wie es Euch bei der Sache geht, aber wenn Sie meine Ex wäre, würde ich ihr das wankelmütige Herz aus der Brust reißen.", sourceObjective = "Reißt Vani LeHörnchen das wankelmütige Herz aus der Brust.", progress = "Wie habt Ihr Euch entschieden, Herzchen?", completion = "Ich bin mir sicher, dass sie es verdient hat, {name}. Sie hätte Euch einfach nicht betrügen dürfen.\n\nMir läuft es eiskalt den Rücken hinunter, wenn ich daran denke, dass sie dieses Monster, den Handelsprinzen, vielleicht sogar geküsst hat!", sourceObjectiveStatus = "unverified-source-field" }
quests[25244] = { id = 25244, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wer heißt denn schon Vani?", description = "Diese Vani LeHörnchen ist nicht zu fassen! Bis Ihr Euch um Chip \"gekümmert\" habt, war sie mit ihm zusammen. Und jetzt trifft sie sich mit dem Handelsprinzen!\n\nIch kann es immer noch nicht fassen, dass sie Euch einfach so Euren Ex ausgespannt hat. Vielleicht solltet Ihr zu den Sklavengruben gehen und diesem hinterhältigen Miststück ein für alle Mal die Leviten lesen!", sourceObjective = "Tötet Vani LeHörnchen.", completion = "Das geschieht ihr Recht! Schließlich hat sie Euch den Mann geklaut!", sourceObjectiveStatus = "unverified-source-field" }
quests[25246] = { id = 25246, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gesinnungswandel", progress = "Seid Ihr im Zweifel über den Weg, den Ihr eingeschlagen habt, {name}?", completion = "Möget Ihr finden, was Ihr suchet, Bruder." }
quests[25247] = { id = 25247, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gesinnungswandel" }
quests[25248] = { id = 25248, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gesinnungswandel", progress = "Seid Ihr im Zweifel über den Weg, den Ihr eingeschlagen habt, {name}?", completion = "Möget Ihr finden, was Ihr suchet, Bruder." }
quests[25249] = { id = 25249, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gesinnungswandel" }
quests[25250] = { id = 25250, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Traum versiegeln", description = "Wir sind bereit. Nehmt diese Träne, {name}. Sie ist voller natürlicher Essenz und vom Willen Ysondres geheiligt.\n\nÖstlich von hier, auf der anderen Seite des Baches, befindet sich Traumgeäst. Dort steht der Große Baum, der größte Baum Feralas', ein Schössling des Weltenbaums. In seinem Stamm ist ein Portal, das direkt zum Smaragdgrünen Traum führt. Dieses Portal müsst Ihr schließen.\n\nDas Portal wird bewacht sein; Ihr müsst mutig sein. Möge die Erdenmutter über Euch wachen.", sourceObjective = "Benutzt Ysondres Träne, um das Portal im Traumgeäst zu schließen.", completion = "Die Verderbnis wurde eingedämmt! Der Wald kann nun heilen.\n\nMöge der Segen der Erdenmutter auf all Euren Wegen bei Euch sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[25251] = { id = 25251, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Endkampf", description = "{name}, es ist soweit! Thrall ist unten an Gallywix' Docks und kämpft in diesem Augenblick gegen den Handelsprinzen!\n\nSpringt sofort in Euer ultimatives Fußbombentrikot und beteiligt Euch!", sourceObjective = "Legt das ultimative Fußbombentrikot an und kümmert Euch um Handelsprinz Gallywix.", progress = "{name}, Ihr müsst den Handelsprinzen vernichten, bevor es zu spät ist!", completion = "Ihr habt es geschafft! Ihr habt es geschafft!\n\nWir sind gerettet, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[25252] = { id = 25252, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Herrscher von Düsterbruch", description = "Nun, da wir in den Ruinen viel erreicht haben, ist es an der Zeit, dass wir uns der Oger in ihrer Heimat annehmen.\n\nDie Gordok bilden die \"Oberschicht\" des Stamms der Gordunni. Sie wurden ausgewählt, Düsterbruch zu verteidigen. Sie werden merken, dass wir es ernst meinen, wenn wir die Stärksten der Gordok vernichten.\n\nDiesmal nichts Ausgefallenes, {name}. Macht Euch einfach auf den Weg und zerschlagt ein paar Gordokschädel!", sourceObjective = "Tötet 6 Vollstrecker der Gordok und 6 Ogermagier der Gordok.", completion = "Ausgezeichnet! Selbst diese Narren werden bald wissen, dass es den Tod bedeutet, wenn man sich gegen die Horde stellt.", sourceObjectiveStatus = "unverified-source-field" }
quests[25255] = { id = 25255, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stört die Störer", description = "Der Schattenhammer hat sich als mehr als ein einfacher Kult entpuppt. Er ist eine gut geölte Kriegsmaschinerie, die sich wie ein Heuschreckenschwarm auf dem Berg niedergelassen hat und alles verschlingt, was ihr in den Weg kommt.\n\nDie Teile des Waldes, die sie nicht in Brand stecken, werden systematisch nach allem Lebenden durchkämmt, um die sterblichen Kultisten zu nähren.\n\nWir müssen die Jäger aufhalten, die die Wolfsschlucht ins Visier genommen haben. Nicht nur der übrigen Wildtiere zuliebe, sondern auch um den Kult zu zwingen, mit leerem Magen zu marschieren. Sucht südlich von hier und an der Straße im Osten.", sourceObjective = "Tötet 6 Zwielichtjäger in der Wolfsschlucht auf dem Hyjal.", completion = "Danke, {name}. Ich fürchte, dass unsere Anstrengungen vergeblich sein könnten. Aber die Natur erschafft sich immer wieder neu und versetzt uns stets in Erstaunen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25256] = { id = 25256, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hilfe benötigt", description = "Ihr da, {race}, nicht so schnell.\n\nMein Boss Spitzzahn hat mich geschickt, um nach Hilfe zu suchen - und nach Vorräten. Ihr scheint kein Händler zu sein, aber wahrscheinlich könnt Ihr ihm trotzdem helfen. Er ist südöstlich von hier, neben dem kaputten Wagen. Oh, und sagt ihm, ich habe Euch geschickt... Ich muss sicherstellen, dass er weiß, dass ich hier nicht nur meine Zeit vertrödel.", sourceObjective = "Meldet Euch bei Spitzzahn an Killrogs Küste in Durotar.", completion = "Vek'nag schickt Euch? Ohne Euch zu sagen, was ich brauche? Keine Rede von Wagenrädern, Nägeln und Vorräten? So ein Depp.", sourceObjectiveStatus = "unverified-source-field" }
quests[25257] = { id = 25257, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ghislania", description = "Ich habe ein paar Gladiatoren, die ich bei Wettkämpfen rund um Kalimdor antreten lasse. Die meisten von ihnen sind hier angekettet... wir hatten Glück, diese hier zu bekommen, als ihr Wagen kaputt ging.\n\nGhislania, die Naga dort drüben... hat ihre letzten drei Kämpfe verloren! Sie braucht wohl mehr Ausbildung, oder vielleicht auch nur genug Schläge. Fordert sie heraus - ich wette, selbst IHR seid stärker als sie.", sourceObjective = "Besiegt Ghislania im Kampf.", completion = "Ich habe Euren Kampf beobachtet. Wie lange seid Ihr schon als {class} unterrichtet worden?\n\nNicht schlecht, Kindchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25258] = { id = 25258, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Griswold Hanniston", description = "Griswold, der da drüben an der Klippe angekettet ist, ist mein neuster Gladiator. Wir haben ihn direkt südlich von hier gefunden. Hat zusammen mit Soldaten von Nordwacht hier herumgeschnüffelt. Meine Männer haben ihn geschnappt und jetzt arbeitet er für mich.\n\nEr sieht ziemlich stark aus, aber ich habe ihn noch nicht wirklich in der Schlacht getestet. Warum fangt Ihr nicht einen Kampf mit ihm an und schaut, ob es sich lohnt, ihn zu behalten?", sourceObjective = "Besiegt Griswold Hanniston im Kampf.", completion = "Jetzt weiß ich gar nicht mehr, was ich tun soll, {name}… Ihr habt ihn ganz leicht im Kampf besiegt, aber ich habe ihn ja auch umsonst bekommen. Und er ist auch günstig im Unterhalt. Vielleicht behalte ich ihn einfach noch eine Weile.", sourceObjectiveStatus = "unverified-source-field" }
quests[25259] = { id = 25259, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gaur Eishorn", description = "Normalerweise würde ich Taunka nicht als Gefangene halten, weil sie der Horde doch recht nahe stehen... dieser hier ist allerdings ein Verräter, und noch dazu ein Krimineller. Er wurde von seinem eigenen Stamm ausgestoßen und ist mit dem Kanu nach Azshara gekommen - und dann wurde er dabei erwischt, wie er Vorräte von Valormok geklaut hat. Er hätte sein Ende sofort mit einer Axt gefunden, wenn ich nicht in der Nähe gewesen wäre und für ihn bezahlt hätte.\n\nGaur ist mein bester Gladiator, {class}. Ich wette 10 Silber, dass Ihr ihn nicht besiegen könnt.", sourceObjective = "Besiegt Gaur Eishorn im Kampf.", completion = "Schon gut, hier habt Ihr das Geld... aber Ihr verschwindet besser bald, bevor ich es mir noch einmal überlege, ob ich nicht doch jemanden von der Horde als Sklaven halten möchte.", sourceObjectiveStatus = "unverified-source-field" }
quests[25260] = { id = 25260, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Missglückt", description = "Die Flut im Südwesten hat eines der Lager der Brennenden Klinge zerstört, die Durotar so hässlich machten. Dieses Lager wurde von Zischel Dunkelklaue angeführt - glaubt mir, ohne ihn sind wir besser dran.\n\nDunkelklaue hat allerdings eine Kugel besessen, an der die Horde sehr interessiert ist. Man weiß nicht, warum... meiner Meinung nach können sich die Hexenmeister darum kümmern. Ich weiß nur, dass ich die Kugel für sie besorgen muss.", sourceObjective = "Erhaltet Zischels Kugel von Zischel Dunkelklaue im Donnergrat.", progress = "Hattet Ihr irgendwelche Schwierigkeiten?", completion = "Ich bitte Euch, mir eine Kugel zu bringen, und Ihr bringt den halben Goblin mit, der noch dranklebt? Eine sehr schöne Arbeitsweise.\n\nNun, Ihr wart sicherlich eine helfende Hand. Ich möchte Euch nun auch einen Gefallen tun.", sourceObjectiveStatus = "unverified-source-field" }
quests[25261] = { id = 25261, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Margoz", description = "Margoz, einer unserer nützlichsten Schamanen, weiß mehr über die Verderbnis der Brennenden Klinge. Er sprach von einer Höhle namens Knochenhöhle in den Bergen - gleich vor den Toren Orgrimmars! - dort soll sich eine große Gruppe von Kultisten der Brennenden Klinge eingenistet haben.\n\nBevor Ihr jedoch zur Knochenhöhle geht, sprecht mit Margoz. Er ist weise und sein Rat wird geschätzt.\n\nEr lagert im Südosten zwischen der Küste und der Staubwindklamm.\n\nFolgt seinem Rat, aber was immer Margoz auch sagt, {name}, ich möchte, dass Ihr diese Kultisten vernichtet!", sourceObjective = "Sprecht mit Margoz.", completion = "Willkommen, {name}. Man hat mir Euer Kommen angekündigt und mir von Euren Unternehmungen in Durotar berichtet.\n\nIhr seid ein {class} mit stetig wachsenden Fertigkeiten und Ansehen.\n\nHaltet Euch auf dem reinen Pfad, dann wird Eure Zukunft wahrlich großartig sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[25262] = { id = 25262, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Knochenhöhle", description = "{name}. Die Brennende Klinge hat die Knochenhöhle östlich von Orgrimmar eingenommen. Sie halten in der Höhle widerliche Rituale ab und verbrennen ihr eigenes Fleisch mit Senghalsbändern.\n\nDurch das Tragen dieser Halsbänder stimmen sich die Kultisten meines Wissens nach auf dämonische Macht ein. Aber um dies zu bestätigen benötige ich ein paar der Halsbänder, um sie zu untersuchen.\n\nBegebt Euch zur Knochenhöhle und sammelt Senghalsbänder der Kultisten, die sich dort aufhalten. Bringt mir die Halsbänder, und ich werde ihr Geheimnis lüften.", sourceObjective = "Erhaltet 6 Senghalsbänder von den Kultisten in der Knochenhöhle.", progress = "Habt Ihr die Knochenhöhle bereits gefunden, {name}? Habt Ihr die Senghalsbänder?", completion = "Gut. In diesen Halsbändern verbirgt sich das Geheimnis der Brennenden Klinge. Und dieses Geheimnis werde ich nun lüften...", sourceObjectiveStatus = "unverified-source-field" }
quests[25263] = { id = 25263, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Neeru Feuerklinge", description = "Die Senghalsbänder, die Ihr mir brachtet, sind mächtige, dämonische Werkzeuge. Ihre Herkunft zu bestimmen liegt jedoch leider außerhalb meiner Künste als Schamane. Wir werden einen Hexenmeister bitten müssen, sie zu studieren.\n\nBringt ein Senghalsband zu Neeru Feuerklinge. Er ist zwar ein talentierter Hexenmeister, doch nutzt er seine Mächte nur, um Dämonen zu bekämpfen, und er behauptet, dass seine Forschungen auf dem Gebiet des Okkultismus gutartiger Natur sind. Ob es stimmt oder nicht, wir brauchen dennoch seine Hilfe gegen den Dämonenkult in Durotar.\n\nIhr findet Neeru in Orgrimmar in der Kluft der Schatten.", sourceObjective = "Bringt Neeru Feuerklinge in Orgrimmar ein Senghalsband-Muster.", progress = "Meine ergebensten Grüße, {class}. Womit kann ich Euch heute behilflich sein?", completion = "Ah, und wo habt Ihr das her? Der gute Margoz hat Euch zu mir geschickt, richtig?\n\nNun, dann lasst mich mal einen Blick darauf werfen...", sourceObjectiveStatus = "unverified-source-field" }
quests[25264] = { id = 25264, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ak'Zeloth", description = "Seit dem letzten großen Krieg, in dem die Brennende Legion besiegt wurde, suche ich nach den Quellen dämonischer Verderbnis innerhalb der orcischen Gesellschaft. Das Halsband, das Ihr mir brachtet, bestätigt meine Befürchtungen.\n\nEs gehört der Brennenden Klinge.\n\nIhr habt Eure Rolle in dieser Geschichte beinahe zu Ende gespielt, {name}. Geht zur Fernwacht an der Grenze zum Brachland im Westen und sprecht dort mit meinem Assistenten Ak'Zeloth. Gebt diese Informationen an ihn weiter.", sourceObjective = "Sprecht mit Ak'Zeloth in der Fernwacht im Nördlichen Brachland.", completion = "Das sind keine Neuigkeiten. Ich erkenne Eure Anstrengungen an, aber die Brennende Klinge muss warten. Wir müssen uns Wichtigerem widmen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25265] = { id = 25265, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sieg!", description = "Wir können Euch nicht genug für all das danken, was Ihr getan habt. Endlich kommen wir von dieser Insel herunter, bevor sie uns noch umbringt!\n\nThrall wird zuerst mit Euch sprechen wollen, {name}. Ich schicke Euch mit einer Rakete da rüber.\n\nWir sehen uns auf dem Schiff!", sourceObjective = "Sprecht mit Thrall an Gallywix' Docks auf den Verlorenen Inseln.", completion = "Lok'tar! Sieg, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[25266] = { id = 25266, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Gesandte des Kriegshäuptlings", description = "Die Goblins und die Orcs haben gemeinsam zu viel erreicht, um jetzt wieder getrennter Wege zu gehen, {class}. Ich wünsche mir, dass das Bilgewasserkartell sich der Horde anschließt.\n\nIch habe hier etwas für den neuen Kriegshäuptling. Gebt dieses Päckchen meinem Freund der Kor'kron am Dock der Messerbucht in Durotar. Er wird Euch helfen, sicher nach Orgrimmar zu gelangen.\n\nSprecht mit Sassy Hartzang auf dem Schiff, wenn Ihr bereit seid, in See zu stechen.\n\nAuf bald! Aka'Magosh! Möget Ihr und die Euren gesegnet sein, {name}!", sourceObjective = "Liefert das versiegelte Päckchen beim Loyalisten der Kor'kron an den Docks der Messerbucht in Durotar ab.", progress = "Was in aller Welt habt Ihr in Orgrimmar zu schaffen, {race}?", completion = "<Der Orc flüstert.>\n\nIch weiß, wer Euch schickt. Hat er Euch etwas für mich mitgegeben?", sourceObjectiveStatus = "unverified-source-field" }
quests[25267] = { id = 25267, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nachricht für Garrosh", description = "<Der Loyalist der Kor'kron öffnet das Paket und hält einen Gegenstand schützend in der Hand, während er den darin enthaltenen Brief liest. Nachdem er die Nachricht von Thrall gelesen hat, huscht ein kaum merkliches Lächeln über sein fängebewehrtes Gesicht.>\n\nBringt dies direkt zu Kriegshäuptling Höllschrei in Orgrimmar. Stellt sicher, dass Garrosh weiß, dass es von Thrall kommt.\n\nNehmt meinen Kampfworg. Schnell, kleiner Goblin. Diese Nachricht duldet keinen Aufschub!", sourceObjective = "Bringt das Emblem des SI:7 zu Garrosh Höllschrei in der Feste Grommash in Orgrimmar.", progress = "Was soll das, {race}? Euresgleichen ist in der Feste Grommash nicht erlaubt.\n\nVerschwindet, bevor ich Euch zeigen muss, wo Euer Platz ist.", completion = "Thrall hat Euch aufgetragen, mir das zu bringen?\n\n<Der Kriegshäuptling tritt einen Schritt zurück, sichtlich erschüttert.>\n\nIch verstehe nur zu gut, was das heißt, {race}.\n\n\n\nDieses stinkende Ding wurde unbeaufsichtigt in der Stadt aufgegriffen und scheint Euch zu erkennen. Ich habe schon andere von Eurem Schlag zur Arbeit nach Azshara geschickt. Nehmt es mit Euch, wenn Ihr geht.\n\nAb diesem Tag dient Ihr und Euer Bilgewasserkartell der Horde!", sourceObjectiveStatus = "unverified-source-field" }
quests[25268] = { id = 25268, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Stimme Goldrinns", description = "Südwestlich von hier liegt der Schrein von Goldrinn, ein Denkmal, das zu Ehren des alten Wolfsgeistes und seinem Beitrag beim Krieg der Ahnen errichtet wurde.\n\nUnsere neuen Verbündeten, die Worgen, waren von dieser Verehrung für den Wolfsgott natürlich vollkommen begeistert und haben begonnen, den Schrein aufzuräumen.\n\nIch habe schon seit Tagen nichts mehr von meiner Kontaktperson Ian Duran gehört. Könntet Ihr vielleicht dorthin fliegen und nach ihm sehen? Ich habe das ungute Gefühl, dass es am Schrein von Goldrinn Schwierigkeiten gibt.", sourceObjective = "Findet Ian Duran in der Nähe des Schreins von Goldrinn auf dem Hyjal.", completion = "Ihr seid hier, um mich zu retten, {class}? Danke!\n\nNein, nein, kümmert Euch nicht um den Käfig. Mein Leben ist unwichtig. Zuerst müssen wir den Schrein retten.", sourceObjectiveStatus = "unverified-source-field" }
quests[25269] = { id = 25269, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Stimme Lo'Goshs", description = "Habt Ihr von Lo'Gosh, dem Wolfsahnen, gehört? Die Mitglieder der Allianz nennen ihn \"Goldrinn\".\n\nIch muss Euch sicher nicht sagen, wie wichtig der Wolfsgott für die Horde ist. Seine Standhaftigkeit im Angesicht des Feindes war für alle Völker eine wahre Inspiration, egal, wie verschieden sie sein mögen.\n\nSüdwestlich von hier, unten im Tal, liegt ein Schrein für Goldrinn. Mein Freund Takrik Wutheuler war dabei, den Schrein wiederaufzubauen, aber ich habe schon seit Tagen nichts mehr von ihm gehört und befürchte das Schlimmste.\n\nBitte findet Takrik und überzeugt Euch davon, dass es ihm gut geht!", sourceObjective = "Findet Takrik Wutheuler in der Nähe des Schreins von Goldrinn auf dem Hyjal.", completion = "Lok'tar, {class}! Macht Euch keine Sorgen wegen des Käfigs, diese Tiere werden schon bald aus Furcht vor mir erzittern.\n\nMeine oberste Priorität besteht darin, diesen Abschaum von meinem geliebten Schrein zu verjagen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25270] = { id = 25270, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sie heulen wie die Schlosshunde", description = "Der Schrein wurde erobert, {name}. Jetzt brauchen wir die Standhaftigkeit von Lo'Gosh mehr denn je.\n\nDiese Schänder, die flohverseuchten Wolfmänner, die den Schrein verwüsten, beschmutzen die Ehre des Wolfsgottes. Sie sind zusammen mit dem Schattenhammerkult eingetroffen und heulen einmütig ihre falschen Götter an. Sie wollen den edlen Lo'Gosh verderben, sodass er in ihr eigenes, verqueres Götterpantheon passt.\n\nTötet sie! Tötet sie und bringt mir die Werkzeuge ihrer Verehrung, eine Art verunreinigter Weihrauch. Ich muss verstehen, was sie mit dem Schrein vorhaben...", sourceObjective = "Beschafft Euch 6 Einheiten verunreinigten Weihrauchs.", progress = "Diese Tiere waren einst Menschen, aber sie haben sich unter dem Einfluss des Schattenhammers in hirnlose Tiere verwandelt. Zögert nicht, sie alle zu töten.", completion = "<Takrik untersucht den Weihrauch.>\n\nAbscheulich. Er ist wie der Weihrauch, den wir verbrennen, um mit den Geistern zu sprechen… aber er ist… besudelt.", sourceObjectiveStatus = "unverified-source-field" }
quests[25271] = { id = 25271, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Goldrinns Wildheit", description = "Diese wilden Tiere, die Ihr hier seht, sind nicht länger meine Brüder aus Gilneas. Sie wurden von einer Art Wahnsinn befallen und haben den Schrein eingenommen.\n\nSie kamen, als der Schattenhammer auf dem Hyjal eingetroffen ist, und heulen den Namen eines gotteslästerlichen Abklatsches unseres geliebten Goldrinns. Kümmert Euch nicht um mich. Eure oberste Pflicht besteht darin, diese Vandalen daran zu hindern, den Schrein weiter zu entehren.\n\nVernichtet sie und haltet nach dem Weihrauch Ausschau, den sie bei sich tragen. Bringt mir ein paar Proben davon!", sourceObjective = "Beschafft Euch 6 Einheiten verunreinigten Weihrauchs.", progress = "Worgen wie ich werden von der Geschichte Goldrinns und seiner Stärke und Weisheit magisch angezogen. Aber diese Vandalen verehren eine ganz andere Art von Wolfsgott.", completion = "<Ian untersucht den Weihrauch.>\n\nWie ich es erwartet habe. Diese Reagenzien tragen das Zeichen des Schattenhammerkults. Und hier steht der Name \"Lycanthoth\". Ich glaube, dieser Weihrauch wird in Beschwörungsritualen verwendet…", sourceObjectiveStatus = "unverified-source-field" }
quests[25272] = { id = 25272, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lycanthoth der Verderber", description = "Die Handlungen dieser wilden Hunde ergeben so langsam Sinn. Der Schattenhammer fürchtet sich vor der Macht der Ahnen. Sie möchten nicht, dass Lo'Gosh zurückkehrt.\n\nAlso haben sie ihren eigenen Wolfsgott gerufen, oder eher das verzerrte Abbild dessen, was er einst war. \"Lycanthoth\", der Verderber.\n\n{name}, Lycanthoth hat nicht einmal annähernd so viel Macht wie Lo'Gosh, aber die Bestie muss vernichtet werden, damit der wahre Ahn zurückkehren kann. Nehmt dieses Rauchwerk und verbrennt es im Schlund von Lycanthoth östlich von hier. Tötet dieses abscheuliche Wesen und befreit Lo'Goshs Geist!", sourceObjective = "Benutzt Lycanthoths Rauchwerk im Schlund von Lycanthoth auf dem Hyjal, um Lycanthoth zu beschwören und zu töten.", progress = "Euer Mut ist ein leuchtendes Beispiel für andere, {class}. Sagt, wie heißt Ihr?", completion = "Es war sehr tapfer von Euch, Lycanthoth gegenüberzutreten, {name}. So wie ich war er eine ursprüngliche Naturgewalt... doch er stammte von einem dunkleren Ort.\n\nDiejenigen, die dieses Ungeheuer gebaren, drangen tief in die Finsternis ein und kanalisierten Kräfte, die niemals für diese Welt gedacht waren.\n\nKommt, {class}. Klettert auf meinen Rücken und wir werden diesen Ungeheuern das wahre Gesicht der Wildheit zeigen!", sourceObjectiveStatus = "unverified-source-field" }
quests[25273] = { id = 25273, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lycanthoth der Verderber", description = "Ich glaube, ich verstehe, was hier vor sich geht. Der Schattenhammer fürchtet, dass die Ahnen sich eines Tages gegen sie wenden könnten. Sie würden alles tun, um Goldrinns Rückkehr zu verhindern.\n\nDieser \"Lycanthoth\" ist eine entstellte Version unseres geliebten Wolfsgottes, den der Schattenhammer beschworen hat, um ihn zu ersetzen.\n\nPah! Lycanthoth hat nicht einmal annähernd so viel Macht wie Goldrinn. {name}, Ihr müsst die Bestie vernichten, damit der wahre Ahn zurückkehren kann. Nehmt dieses Rauchwerk und verbrennt es im Schlund von Lycanthoth östlich von hier. Tötet dieses abscheuliche Wesen und befreit Goldrinn!", sourceObjective = "Benutzt Lycanthoths Rauchwerk im Schlund von Lycanthoth auf dem Hyjal, um Lycanthoth zu beschwören und zu töten.", progress = "Euer Mut ist ein leuchtendes Beispiel für andere, {class}. Sagt, wie heißt Ihr?", completion = "Es war sehr tapfer von Euch, Lycanthoth gegenüberzutreten, {name}. So wie ich war er eine ursprüngliche Naturgewalt... doch er stammte von einem dunkleren Ort.\n\nDiejenigen, die dieses Ungeheuer gebaren, drangen tief in die Finsternis ein und kanalisierten Kräfte, die niemals für diese Welt gedacht waren.\n\nKommt, {class}. Klettert auf meinen Rücken und wir werden diesen Ungeheuern das wahre Gesicht der Wildheit zeigen!", sourceObjectiveStatus = "unverified-source-field" }
quests[25274] = { id = 25274, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gezeichnet mit Blut", description = "Endlich seid Ihr hier, {name}. Und genau zur richtigen Zeit.\n\nDie Nachricht über Ragnaros' Auftauchen hat eine große Welle von neuen Rekruten ausgelöst, die sich um eine Mitgliedschaft beim Schattenhammerkult bewerben.\n\nWenn Ihr den Kult unterwandern möchtet, dann ist jetzt der rechte Augenblick. Wir brauchen Rekrutierungsunterlagen, die mit dem Blut eines Mitglieds des Schattenhammers unterzeichnet wurden, das Euch empfiehlt. Lockt einen von den neuen Rekruten von der Gruppe weg und schlagt ihn mit diesem Totschläger.\n\nWenn Ihr Glück habt, könnt Ihr ihm seine Rekrutierungsunterlagen stehlen. Bringt sie zu mir. Ich werde mir alle Mühe geben, sie zu verändern.", sourceObjective = "Lockt einen Zwielichtrekruten von der Gruppe weg und stehlt seine Rekrutierungsunterlagen des Schattenhammers.", progress = "Habt Ihr die Papiere?", completion = "Ausgezeichnet. Ich werde mir alle Mühe geben, diese Dokumente zu verändern.", sourceObjectiveStatus = "unverified-source-field" }
quests[25275] = { id = 25275, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meldet Euch beim Arbeitsaufseher", description = "Euer Volk ist mit der landschaftlichen Umgestaltung Azsharas beschäftigt. Wir werden das Land im Geiste der Horde neu gestalten, auf dass alle wissen: Kalimdor ist unser!\n\nGeht nach Norden durch die Stadt. Jenseits des Tals der Ehre findet Ihr das Hintere Tor von Orgrimmar. Meldet Euch bei Arbeitsaufseher Grabbit außerhalb des Tors, Goblin.\n\nFür die Horde!", sourceObjective = "Meldet Euch bei Arbeitsaufseher Grabbit am Hinteren Tor von Orgrimmar in Azshara.", completion = "{name}? Der {name}?!\n\n\n\nEuer Ruf eilt Euch voraus. Ich weiß nicht, ob ich dankbar oder besorgt sein sollte, dass Ihr hier seid. Zumindest gibt es in Azshara keine Vulkane!\n\nIm Ernst, ich kann es kaum glauben, dass Ihr Euch hier blicken lasst... Handelsprinz Gallywix hat eine Werkstatt oben auf dem Berg errichtet!", sourceObjectiveStatus = "unverified-source-field" }
quests[25276] = { id = 25276, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eure neue Identität", description = "Da! Nicht meine beste Arbeit, aber auch nicht meine schlechteste. Ihr werdet bei den Kultisten den Namen \"{name}damus\" tragen.\n\nMit diesen Papieren werdet Ihr den anderen Rekruten vorgezogen und könnt direkt mit den Zwielichtinstrukteuren sprechen.\n\nGeht zu den Versuchsgründen und zeigt sie Condenna der Mitleidlosen. Sie trennt die Spreu vom Weizen.\n\nZeigt ihr, aus welchem Holz Ihr geschnitzt seid.", sourceObjective = "Sprecht mit Condenna der Mitleidlosen bei den Versuchsgründen auf dem Hyjal.", progress = "Ihr werdet mich mit dem gebührenden Respekt ansprechen, Rekrut!", completion = "Kunrebidamus? Hoffen wir mal, dass Eure Eltern Euch mehr auf diese Welt mitgegeben haben als einen dämlichen Namen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25277] = { id = 25277, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aufräumarbeiten", description = "Wir machen gute Fortschritte darin, den früheren Glanz des Schreins wiederherzustellen, {name}. Aber ein paar Aufräumarbeiten müssen wir noch erledigen. Auf der anderen Seite dieser Wiese errichten gerade ein paar Ogerlandstreicher ihr Lager. Ihr Anführer ist ein dickköpfiger Klotz purer Hässlichkeit namens Gar'gol.\n\nTötet Gar'gols Diener und schaut, ob wir ihn dadurch zum Aufbruch bewegen können.", sourceObjective = "Tötet eine beliebige Kombination aus 8 Schlägern oder Schattenwirkern des Unterschlupfs in Gar'gols Unterschlupf auf dem Hyjal.", completion = "Ha! Also habt Ihr wirklich ein paar Köpfe zum Rollen gebracht!\n\nDie Legenden sagen, dass Lo'Gosh während des Krieges der Ahnen zehn Tage ununterbrochen gegen Dämonen gekämpft haben soll. Hoffentlich habt Ihr nicht so lange kämpfen müssen…", sourceObjectiveStatus = "unverified-source-field" }
quests[25278] = { id = 25278, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aufräumarbeiten", description = "Dank Eurer Bemühungen sind wir vielleicht schon bald in der Lage, den früheren Glanz des Schreins wiederherzustellen. Aber zunächst müssen wir dieses Tal sichern. Südlich von hier hat eine Gruppe von Ogern unter Leitung von Gar'gol ein Lager in einem stinkenden Unterschlupf errichtet.\n\nIch würde Gar'gol nicht als 'Bedrohung' bezeichnen, sondern vielmehr als enorm massiges Hindernis auf unserem Weg, das uns von der echten Gefahr ablenkt. Dennoch müssen er und seine Gorillas gehen.\n\nTötet Gar'gols Diener in Goldrinns Namen!", sourceObjective = "Tötet eine beliebige Kombination aus 8 Schlägern oder Schattenwirkern des Unterschlupfs in Gar'gols Unterschlupf auf dem Hyjal.", completion = "Ihr habt diesen Ort richtig aufgeräumt, oder? Gut gemacht!\n\nDie Nachtelfen haben mir einst eine Geschichte erzählt, wie Goldrinn sich einem Schreckenslord gestellt und ihn getötet hat, während drei andere an seinen Flanken hingen und sein Fleisch versengten. Ich frage mich, ob Ihr oder ich je eine derartige Stärke beweisen werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[25279] = { id = 25279, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der zurückeroberte Schrein", description = "Ja, {name}. Ich bin Goldrinn, den man in Eurer Sprache \"Lo'Gosh\" nennt. Eure Standhaftigkeit im Angesicht der Angst hat mich aus den Fesseln des Zwielichts befreit.\n\nMein Schrein wurde geläutert, und meine Anhänger sind an ihren rechtmäßigen Platz an meiner rechten Pfote zurückgekehrt.\n\nGeht zu Takrik und setzt Eure Arbeit hier auf dem Hyjal fort. Ich werde Euch schon bald erneut brauchen.", sourceObjective = "Kehrt zu Takrik Wutheuler am zurückeroberten Schrein von Goldrinn auf dem Hyjal zurück.", completion = "{name}, es war unglaublich! Für einen flüchtigen Moment sah ich Lo'Gosh durch die Bäume hindurch, ein Wesen aus Zorn und Licht zugleich. Mein Käfig ist zusammengebrochen und die Vandalen schmolzen unter dem Kuss seiner Klauen dahin wie Wachs. Ihr Schreien und Heulen erfüllte das ganze Tal... War das Euer Werk?", sourceObjectiveStatus = "unverified-source-field" }
quests[25280] = { id = 25280, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der zurückeroberte Schrein", description = "Ja, {name}. Ich bin Goldrinn. Eure Standhaftigkeit im Angesicht der Angst hat mich aus den Fesseln des Zwielichts befreit.\n\nMein Schrein wurde geläutert, und meine Anhänger sind an ihren rechtmäßigen Platz an meiner rechten Pfote zurückgekehrt.\n\nGeht zu Ian und setzt Eure Arbeit hier auf dem Hyjal fort. Ich werde Euch schon bald erneut brauchen.", sourceObjective = "Kehrt zu Ian Duran am zurückeroberten Schrein von Goldrinn auf dem Hyjal zurück.", completion = "{name}, es war atemberaubend! Goldrinn selbst, sein weißes Fell so weiß wie der Sommermond. Mein Käfig ist zerfallen und die Vandalen schmolzen unter dem Kuss seiner Klauen dahin wie Wachs. Er war wunderschön, {name}. Wunderschön!", sourceObjectiveStatus = "unverified-source-field" }
quests[25281] = { id = 25281, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wie ich Euch, so Ihr ihnen", description = "Jetzt seid Ihr in der Lage, Euch in diesem Reich freier und ohne Angst vor Ertrinken zu bewegen.\n\nUnd jetzt beginnt unsere Arbeit.\n\nZunächst gibt es viele Verbündete von Euch in der Nähe, die in diesem Augenblick im Wasser um ihr Leben ringen. Ich habe Euch gerettet und nun müsst Ihr sie retten.\n\nIch habe die Muschel verzaubert, die Ihr mir gebracht habt. Benutzt sie, um Eure Freunde zu retten.\n\nSchnell!", sourceObjective = "Benutzt das verzauberte Tritonshorn, um 6 ertrinkende Soldaten zu retten.", completion = "Während Ihr fort wart, konnte ich einige der gefallenen Soldaten wieder zum Leben erwecken.\n\nWenn wir hier überleben wollen, brauchen wir jede helfende Hand.", sourceObjectiveStatus = "unverified-source-field" }
quests[25283] = { id = 25283, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Rede vorbereiten", description = "Hochtüftler Mekkadrill hat mich gebeten, eine Rede zu schreiben, die er vor Beginn der Schlacht halten kann. Aber ich kann mich nicht mehr daran erinnern, welche Rede gut ist und welche total daneben.\n\nKönntet Ihr ein paar davon an den örtlichen gnomischen Anwohnern ausprobieren? Dieses Gerät erschafft ein Bild von Mekkadrill, das einige Zeilen aus jeder meiner Reden spricht.\n\nLasst mich wissen, welche funktioniert, ja?", sourceObjective = "Benutzt das Gnomische Abspielgerät vor Ozzie Wechselvolt nördlich von Kharanos, Milli Federpfiff bei Stahlrosts Depot und Tog Rostspross vor der Gaststätte in Kharanos. Kehrt zu Toby Zeigrad zurück, wenn alle Reden gehalten wurden.", completion = "Wow. Ihre Reaktionen waren also so unterschiedlich.\n\nNicht ganz, was ich erwartet habe, aber ich glaube, ich habe eine passende Rede.\n\nLasst mich nur kurz herausfinden, wo ich sie hingelegt habe …", sourceObjectiveStatus = "unverified-source-field" }
quests[25284] = { id = 25284, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Angst nähren", description = "Unsere Mittel sind begrenzt, {class}, aber das heißt nicht, dass wir da unten nicht für ein wenig Ärger sorgen können. Benutzt die Seile hier, um die Steilwand hinunterzuschleichen und tötet dann die menschlichen Gefängniswärter.\n\nEin paar dürre Wächter zu töten wird das Blatt zwar nicht wenden, aber stellt Euch die Angst und das Chaos vor, die wir dadurch verbreiten werden, wenn die Menschen die verstümmelten Leichen entdecken...\n\n<Holgom grinst und zeigt dabei seine gelben Zähne - seine Augen glitzern.>", sourceObjective = "Tötet 5 Turmwächter. Benutzt die Seile neben Holgom, um schnell nach Ehrenwacht hinein und hinaus zu gelangen.", completion = "Gut, gut! Sie werden viele schlaflose Nächte benötigen, um herauszufinden, wo wir herkamen und wohin wir verschwunden sind, nachdem wir sie umgebracht hatten...", sourceObjectiveStatus = "unverified-source-field" }
quests[25285] = { id = 25285, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rein und Raus", description = "Diese neuen Mechanopanzer müssen für den Angriff fertiggemacht werden. Bereit, eine dieser Höllenmaschinen zu testen?! Klar seid Ihr das!\n\nAls erstes müssen wir sicherstellen, dass Ihr wieder rauskommt, wenn Ihr erstmal drin seid. Wenn Ihr in der Schlacht glaubt, dass Euer Panzer gleich explodieren wird, dann raus! Ich hab schon viele Gnome gesehen, die bis zum bitteren Ende dringeblieben sind ... der Panzer explodiert, und sie gleich mit.\n\nAlso, ich habe diesen Panzer mit einem Schleudersitz ausgestattet. Probiert ihn für mich aus, ja?", sourceObjective = "Testet den Schleudersitz des Mechanopanzers mit Schleudersitzsystem.", completion = "Na sieh mal einer an, Ihr seid nicht in winzigkleine Stücke zersprengt worden!", sourceObjectiveStatus = "unverified-source-field" }
quests[25286] = { id = 25286, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wortübermittlung", description = "Das ist es. Das ist die Rede, {name}! Sie hat alles, was einen guten Auftakt zur Schlacht ausmacht... sie inspiriert, ist eloquent und spricht den einfachen Gnom direkt an. Noch nie wurde eine bessere Rede geschrieben!\n\nGebt das hier bei Hauptmann Tret Funkdüse ab und besorgt euch einen Transport zu Hochtüftler Mekkadrill!", sourceObjective = "Bringt die Rede zu Hauptmann Tret Funkdüse bei Stahlrosts Depot.\n\nBereitgestellter Gegenstand:", completion = "Toby ist mit der Rede fertig? Lasst mal sehen...\n\n<Er liest die Rede> Bei allen Kolben, was für eine fantastische Rede! Ich wusste ja, dass Toby ein guter Redenschreiber ist, aber das hier ist vielleicht das Beste, was er je geschrieben hat.\n\nIch glaube, es ist Zeit, Euch in die Schlacht zu schicken.", sourceObjectiveStatus = "unverified-source-field" }
quests[25287] = { id = 25287, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wortübermittlung", description = "In Ordnung, Soldat. Zeit, Euch zu beweisen!\n\nNehmt diese Rede und geht an Bord der Flugmaschine \"Donnerschlag\". Sie ist der schnellste Weg zu Hochtüftler Mekkadrill, und er wartet nur noch auf diese Rede, bevor er Operation: Gnomeregan beginnt.\n\nGeht! Jetzt!", sourceObjective = "Benutzt die Flugmaschine \"Donnerschlag\" bei Stahlrosts Depot, um zu Hochtüftler Mekkadrill zu fliegen, und stellt ihm Tobys Rede zu.", progress = "Wart Ihr nicht da, um Toby Zeigrads Rede zu bringen?", completion = "Das ist also die endgültige Fassung der Rede von Toby? Lasst mal sehen...", sourceObjectiveStatus = "unverified-source-field" }
quests[25289] = { id = 25289, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Schritt nach vorn...", description = "Jetzt, da das Schleudersitzsystem funktioniert, sind wir bereit, Bewegungen zu testen. Dieser Panzer hat eine Besonderheit: Automatische Ausweichmanöver!\n\nIch möchte, dass Ihr die Servomotoren am linken Bein und am rechten Bein sowie das Automatische Ausweichmanöversystem ausprobiert.\n\nEs ist ganz einfach, also sollte es nicht lange dauern.", sourceObjective = "Testet die Manövrierbarkeit des krabbelnden Mechanopanzers.", completion = "Hm… der Servomotor für das linke Bein hat das rechte aktiviert? Aber ich habe doch gesehen, wie sich das linke Bein bewegt hat… ach, Details. Ich kümmere mich später darum. Aber zwei von drei Teilen haben funktioniert, das ist gar nicht mal so schlecht!\n\nDanke, dass Ihr das für mich überprüft habt, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[25291] = { id = 25291, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zwielichttraining", description = "Ihr habt bewiesen, dass Ihr wert seid, zumindest an unserem grundlegendsten Training teilzunehmen.\n\nIhr findet eine unserer Siedlungen östlich von hier. Sprecht dort mit Instrukteurin Mylva.", sourceObjective = "Sprecht mit Instrukteurin Mylva auf dem Hyjal.", completion = "Also glaubt Ihr, dass Ihr bereit seid, den nächsten Schritt zu tun, Kunrebidamus?\n\nMal sehen, was Ihr leisten könnt.", sourceObjectiveStatus = "unverified-source-field" }
quests[25292] = { id = 25292, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die nächsten Verwandten", description = "<Nato zieht Euch beiseite und flüstert.>\n\n{name}, ich habe die Kugel aus Ganns Brust entfernt, aber die Blasen in seinem Blut sagen mir alles, was ich wissen muss. Seine Lunge ist durchstoßen und die Wunde entzündet sich. Er wird nicht mehr lange durchhalten.\n\nNehmt dies. Es ist die Kugel, die ihn getötet hat. Seine Familie wird sicher wissen wollen, was ihrem jüngsten Krieger zugestoßen ist.\n\nSucht Alto Steinkeil auf. Er ist in den Düstermarschen postiert. Geht nach Nordosten und folgt dem Weg nach Brackenwall.", sourceObjective = "Bringt die zwergische Gewehrkugel zu Alto Steinkeil in Brackenwall in den Düstermarschen.", progress = "Hallo, {class}. Ihr seid ja voller Staub statt voller Schlamm. Also kommt Ihr wohl vom Brachland hierher.", completion = "<Alto ballt die Faust um die Kugel, als Ihr ihm erzählt, was passiert ist.>\n\nGann? Tot? Ich… ich hätte es wissen sollen. Sein Temperament… seine Waghalsigkeit. Ich wusste, dass sie ihm eines Tages zum Verhängnis werden würden.\n\nAber es scheint, als hättet Ihr ihm bereits das Geschenk der Rache gemacht. Vielen Dank, {name}!\n\nUnd jetzt richtet Eure Aufmerksamkeit auf die Düstermarschen. Wenn die Allianz den Bau ihrer verfluchten Straße durch das Gebiet abschließt, sind all Eure Siege im Brachland vielleicht nichtig.", sourceObjectiveStatus = "unverified-source-field" }
quests[25294] = { id = 25294, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hundefütterung", description = "Hmmmpf… In letzter Zeit lassen die hier wohl einfach jeden rein.\n\nNa gut. Ihr habt in den Versuchsgründen sicher schon Loderos kennengelernt.\n\nNun, ich wurde mit der Aufgabe betraut, mich um einen seiner Welpen zu kümmern. Er ist jetzt schon ein echter Satansbraten. Wenn er später seinem Vater auch nur ein bisschen ähnlich wird, wird er unserer Sache gut dienen.\n\nSammelt Fleisch von den Basilisken in der Gegend und füttert ihn damit.", sourceObjective = "Sammelt 5 Stück verkohltes Basiliskenfleisch und füttert die Brut von Loderos damit.", completion = "Ausgezeichnet. Dieser kleine Welpe wird bestimmt einmal so groß und erbarmungslos wie sein Vater.", sourceObjectiveStatus = "unverified-source-field" }
quests[25295] = { id = 25295, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feuer drücken", description = "Sicherheitssysteme bereit! Motorfunktion funktioniert! Jetzt müssen wir nur noch sicherstellen, dass die Geschütze feuern.\n\nDas sollte nicht schwer sein, {name}. Der Mechanopanzer auf dem Hügel hinter uns ist mit harmlosen Geschossen geladen worden. Feuert einfach ein paar Schüsse auf die Ziele in der Nähe und erstattet mir dann Bericht.", sourceObjective = "Testet die Waffensysteme des schießenden Mechanopanzers an den Zielen in der Nähe.", progress = "Was ist los, habt Ihr vergessen, wie man schießt?", completion = "Hm. Die Geschosse hatten also eine ziemlich breite Streuung?\n\nDas wäre für so manchen sicher ein Problem. Für mich ist das ein versteckter Vorteil!\n\nUnsere Feinde werden überall herumrennen. Mit ein wenig Streuung müssen die Panzerfahrer den Vorhalt nicht so genau einschätzen!", sourceObjectiveStatus = "unverified-source-field" }
quests[25296] = { id = 25296, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sammelt Informationen", description = "Ich bin es, {name}, Ortell!\n\nSchaut nicht direkt auf das Plumpsklo… sonst verratet Ihr noch meinen Standort.\n\nAlso läuft alles nach Plan? Ausgezeichnet!\n\nIhr müsst für mich ein paar Informationen sammeln, während Ihr hier seid. Eine Karte oder ein Brief scheinen zwar nichts Weltbewegendes zu sein, aber den nächsten Schritt unseres Feindes vorauszusehen kann Hunderte von Leben auf unserer Seite retten.", sourceObjective = "Besorgt das Kommuniqué des Schattenhammers und die Hyjalschlachtpläne.", progress = "Habt Ihr die Dokumente, {name}?", completion = "Ausgezeichnete Arbeit, {name}. Oder sollte ich sagen \"Kunrebidamus\"?\n\nGebt meinen Männern eine Minute, um sich das hier durchzulesen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25297] = { id = 25297, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In den Schlund des Wahnsinns", description = "Ich kenne ein Gebräu, das diese stumpfsinnigen ehemaligen Sklaven wieder in die Wirklichkeit zurückholen sollte. Sammelt ein paar Steinblüten von den Felsen rund um Gar'gols Unterschlupf, ein paar Bitterblüten am Ufer des Sees in der Nähe und Schwarzfeuerglut aus einer der Kohlenpfannen am Eingang des Unterschlupfs. Das Gebräu hält nicht lange vor, also gebt alle Zutaten in einen Kessel des Schattenhammers am Eingang des Unterschlupfs.\n\nEin Schluck dieses Gebräus wird diesen hirnlosen Sklaven wieder Verstand einhauchen!", sourceObjective = "Sammelt Steinblüten, Bitterblüten und Schwarzfeuerglut.", progress = "<Im Kessel blubbert eine widerliche Flüssigkeit.>", completion = "<Ihr leert den derzeitigen Inhalt des Kessels aus. Die umstehenden Pflanzen verwelken sofort.>\n\n<Euer Gebräu ähnelt eher einem dicken Eintopf und stinkt nach verfaultem Kohl. Ihr dreht Euren Kopf zur Seite und füllt es in Flaschen.>", sourceObjectiveStatus = "unverified-source-field" }
quests[25298] = { id = 25298, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Freiheit ist das Einzige, was zählt", description = "<Rio sagte, dass die Wirkung des Gebräus nicht lange anhalten wird.>\n\n<Ihr solltet schnell zum Unterschlupf eilen und es so vielen Zwielichtdienern wie möglich verabreichen.>", sourceObjective = "Sprecht mit 8 Zwielichtdienern, um ihnen das Gebräu zu verabreichen und sie zu retten.", progress = "Hat das Gebräu gewirkt?", completion = "Sehr gut! Wollen wir nur hoffen, dass der Schaden nicht dauerhaft ist.\n\nDem Zustand dieser armen Opfer hier im Lager nach zu urteilen haben die Schattenhammerkultisten ihren Geist ganz schön verwirrt.", sourceObjectiveStatus = "unverified-source-field" }
quests[25299] = { id = 25299, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mentales Training: Wahrheit als Weg zur Macht", description = "Ihr glaubt vielleicht, dass Ihr bereit seid, das Wissen zu empfangen, das wir Euch vermitteln werden. Aber das seid Ihr nicht.\n\nStellt Euch Euren Geist als Kiste vor, die sich wiederum in vielen weiteren Kisten befindet.\n\nMit jedem Schritt unseres Trainings öffnet Ihr eine weitere Kiste, bis Ihr bereit seid, Euch direkt mit den Elementen zu verbinden.\n\nNehmt die Kugel des Aufstiegs und beantwortet alle Fragen, die sie Euch stellt. Wahrheitsgemäß! Jede falsche Antwort könnte... fatale Folgen haben.", sourceObjective = "Benutzt die Kugel des Aufstiegs und beantwortet 10 Fragen richtig.", progress = "Ihr seid zurückgekehrt.", completion = "Ihr hattet Erfolg, Kunrebidamus. Ihr seid bereit für den nächsten Schritt.", sourceObjectiveStatus = "unverified-source-field" }
quests[25300] = { id = 25300, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Auge des Zwielichts", description = "Der Ogerklan jenseits des Sees wird von Gar'gol geleitet. Nun ja, \"geleitet\" ist relativ. Gar'gol hat die Intelligenz eines rohen Stücks Fleisch.\n\nSoweit ich es beurteilen kann, nimmt Gar'gol Befehle von einem magischen Artefakt entgegen, dem \"Auge des Zwielichts\". Er folgt seinen Anweisungen, ohne Fragen zu stellen.\n\nWenn wir das Auge sabotieren könnten, würden wir unglaublichen Schaden anrichten.\n\nGeht zu Gar'gols Unterschlupf und sucht das Auge des Zwielichts in der Nähe des Eingangs. Untersucht es. Findet einen Weg, es Eurem Willen zu unterwerfen. Ah, welch wundervolles Chaos...", sourceObjective = "Sucht das Auge des Zwielichts in der Nähe des Eingangs zu Gar'gols Unterschlupf auf dem Hyjal.", completion = "<Ihr nähert Euch dem Auge des Zwielichts. Als Eure Fingerspitzen die leuchtende Oberfläche berühren, bemerkt Ihr eine bösartige Präsenz, die Euch anstarrt und Eure Seele durchforstet.\n\n<Instinktiv zieht Ihr Eure Hand zurück.>", sourceObjectiveStatus = "unverified-source-field" }
quests[25301] = { id = 25301, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Worte der Herrschaft", description = "<Während der kurzen Kommunikation mit dem Auge konntet Ihr spüren, dass die Quelle seiner Macht tief in dem Unterschlupf verborgen liegt. Ihr konntet das Gewicht eines mächtigen Folianten spüren, der die vier Elemente aneinander fesselt.>\n\n<Wenn Ihr das Auge beherrschen wollt, müsst Ihr den Unterschlupf nach diesem Folianten durchsuchen.>", sourceObjective = "Findet die Zwielichtapokryphen in Gar'gols Unterschlupf auf dem Hyjal.", completion = "<Ein schwerer, in Haut gebundener Foliant liegt offen auf dem Tisch.>\n\n<Die bildartige Schrift in rostfarbener Tinte ist nicht entzifferbar und wirkt auf Euch wie Gekritzel. Zwischen einigen der Seiten liegen jedoch Notizen mit der Übersetzung. Das muss das Buch sein, nach dem Ihr sucht.>", sourceObjectiveStatus = "unverified-source-field" }
quests[25303] = { id = 25303, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In Eurem Element", description = "<Ihr könnt den Text nicht lesen, aber die Diagramme scheinen darauf hinzudeuten, dass die Geräte um Euch herum in einer bestimmten Reihenfolge aktiviert werden müssen.>\n\n<Ein Absatz der Apokryphen wurde in moderne Sprache übersetzt:>\n\nAm Anfang war der ewige Schatten.\nHass loderte und FEUER ward geboren.\nWunden vernarbten und zeugten die ERDE.\nSchmerzensschreie gebaren den WIND.\nUnd der Himmel weinte ein Meer aus TRÄNEN. \nWir leben im Schatten\nDie Welt, die wir kennen\nErschaffen aus Wut, Leid, Schmerz und Tränen.", sourceObjective = "Aktiviert die vier in der Nähe befindlichen Elementartiegel in der richtigen Reihenfolge, um das Auge des Zwielichts zu kontrollieren.", progress = "<Ihr beugt Euch über die Apokryphen und versucht, einen Sinn hinter alldem zu erkennen.>", completion = "<Erfüllt von den Energien der gefangenen Elementare steht Ihr vor den Zwielichtapokryphen. Die Seiten blättern sich wie von Geisterhand um.>\n\n<Plötzlich seht Ihr, was das Auge sieht. Es steht unter Eurem Befehl!>", sourceObjectiveStatus = "unverified-source-field" }
quests[25304] = { id = 25304, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Schlacht um Sardor", description = "Unsere Siedlung auf der Insel Sardor haben wir an die Nagaschuppen der Hasskämme verloren. Von ihren Zahlen überwältigt mussten wir uns auf das Festland zurückziehen. Während sie sich auf ihrem neuen Sandstrand vergnügten, haben wir an der Küste Neu-Mondfederfeste errichtet und eine weitaus größere Armee zusammengestellt.\n\nJetzt werden wir die Hasskämme zurück ins Meer jagen. Sucht das Urtum des Krieges an der Küste auf. Es wird Euch an die Front bringen. Tambre führt dort die Offensive an.", sourceObjective = "Sprecht mit Tambre auf der Insel Sardor.", completion = "Wir werden diese garstigen Kreaturen zurück ins Meer jagen. Ich hoffe, Ihr seid bereit.", sourceObjectiveStatus = "unverified-source-field" }
quests[25305] = { id = 25305, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kein Blick zurück", description = "Unsere Siedlung auf der Insel Sardor haben wir an die Naga der Hasskämme verloren. Von ihren Zahlen überwältigt mussten wir uns auf das Festland zurückziehen. Während sie sich auf ihrem neuen Sandstrand vergnügten, haben wir an der Küste Neu-Mondfederfeste errichtet und eine weitaus größere Armee zusammengestellt.\n\nJetzt werden wir die Hasskämme zurück ins Meer jagen. Fordert Schildwache Ranadae auf, sich unseren Truppen auf Sardor anzuschließen. Tötet die Naga und sorgt dafür, dass auch derjenige stirbt, der ihnen die Befehle erteilt.", sourceObjective = "Tötet 10 Naga der Hasskämme und ihren Anführer.", sourceObjectiveStatus = "unverified-source-field" }
quests[25306] = { id = 25306, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ihr seid jetzt in der Gnarmee!" }
quests[25308] = { id = 25308, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Saat der Zwietracht", description = "Nach den Informationen, die Ihr gesammelt habt, gibt es starke Spannungen zwischen den Ogern und Nicht-Ogern des Kults.\n\nHochkultist Azennios und der Ogermagier Karr'gonn treffen sich am Sitz der Auserwählten, um zu versuchen, diese Konflikte zu mildern.\n\nAm Sitz der Auserwählten gibt es ein Plumpsklo wie dieses. Geht dorthin und zieht Euch diese Ogerverkleidung an. Sucht nach einem Weg, Azennios auf seiner Friedensmission zu töten.\n\nWir müssen diese Zwietracht so gut es geht ausnutzen!", sourceObjective = "Lenkt Karr'gonn ab und tötet Hochkultist Azennios am Sitz der Auserwählten auf dem Hyjal.", progress = "Habt Ihr es schon erledigt, {name}?", completion = "Ausgezeichnete Arbeit, {name}! Dieses Mal habt Ihr Euch wirklich selbst übertroffen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25309] = { id = 25309, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spirituelles Training: Mitleid ist etwas für Schwächlinge", description = "Ihr habt es so weit geschafft. Andere nicht.\n\nGeht zur Verdammniswacht direkt nördlich von hier. Wir haben alle… Versager zusammengetrommelt. Ich möchte, dass Ihr Euch um sie kümmert. Das ist gut für Euer spirituelles Wachstum.\n\nWenn Ihr Probleme mit einem so kaltblütigen Verhalten haben solltet, betrachtet es einfach als ihre zweite Chance. Sollte es nämlich jemandem von ihnen gelingen, Euch zu töten... nun, dann nimmt er Euren Platz ein.", sourceObjective = "Tötet 5 gescheiterte Bittsteller in der Verdammniswacht.", completion = "Ihr seid auf der Überholspur zum Erfolg. Wollen wir hoffen, dass Ihr Eure makellose Bilanz nicht mit solchen Albernheiten wie Barmherzigkeit und Menschlichkeit verderbt.\n\nKommt schon. Lasst uns über Eure Zukunft sprechen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25310] = { id = 25310, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das größere von zwei Übeln", description = "Wir haben die Flüsternde Schlucht mit Gewalt von den Dämonen der Brennenden Legion zurückerobert. Bis jetzt haben wir unser Gebiet ganz gut verteidigen können, bis auf eine Ausnahme.\n\nKürzlich haben wir die Tore von Sothann an einen Grubenlord und seine Armee verloren. Das können wir nicht auf sich beruhen lassen.\n\nBenutzt diesen Talisman, wenn Ihr in seiner Nähe seid. Ihr erhaltet dann kurzzeitig die Macht eines Flammenaszendenten. Nutzt sie gut!", sourceObjective = "Benutzt den Talisman der Flammenaszendenz und tötet Garnoth, die Faust der Legion, an den Toren von Sothann auf dem Hyjal.", completion = "Ausgezeichnete Arbeit, Arrøwdynamicdamus. Wir müssen allen Möchtegerngegnern zeigen, dass wir nicht so leicht aufgeben.", sourceObjectiveStatus = "unverified-source-field" }
quests[25311] = { id = 25311, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schattenhammergebiet", description = "Die Dämonen der Brennenden Legion glauben, sie könnten hier einfach so aufkreuzen und sich jedes Gebiet nehmen, das ihnen gefällt. Sicher, das Gebiet gehörte früher ihnen, aber darum geht es ja nicht.\n\nWir werden ihnen beibringen, dass sie sich nicht mit dem Schattenhammer anlegen sollten.\n\nBrecht zu den Toren von Sothann auf und vernichtet den Horrorwachentrupp, der in diesem Gebiet sein Unwesen treibt.", sourceObjective = "Tötet 10 Horrorwachen an den Toren von Sothann auf dem Hyjal.", completion = "Pünktlich wie immer. Ihr enttäuscht mich nicht.", sourceObjectiveStatus = "unverified-source-field" }
quests[25312] = { id = 25312, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr zu Abendwisper", description = "<Ihr zwingt Euer eigenes Bild in das Auge und bringt es dazu, den Ogern andere Befehle zu geben. Währenddessen spürt Ihr eine andere Präsenz im Auge, die Euch begutachtet und nach Euren Schwächen sucht. Ein weit entferntes Wesen schäumt vor Wut. Ihr habt Euch heute ein paar Feinde gemacht!>\n\n<Eure Arbeit hier ist getan, und die Oger werden Euch gegenüber freundlich sein. Kehrt zu Royce Abendwisper am Schrein von Goldrinn zurück und berichtet ihm, was Ihr erreicht habt.>", sourceObjective = "Kehrt zu Royce Abendwisper am Schrein von Goldrinn auf dem Hyjal zurück.", completion = "Hallo, ja? Was? Ihr? Oh, Ihr seid einer von denen, die ich auf die Suche nach dem Auge des Zwielichts geschickt habe, oder?\n\nGute Arbeit, sehr gut. Ich schätze, das ist eine wichtige Lektion für Euch:\n\nNehmt niemals Befehle von einem großen violetten Ball an.", sourceObjectiveStatus = "unverified-source-field" }
quests[25314] = { id = 25314, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Redenschreiben für Anfänger", description = "Hört zu, {name}. Ich habe herausgefunden, was Sie mit Jarod Schattensang vorhaben. Die Oger des Schattenhammers wollen ihn als Teil des diesjährigen Initiationsritus opfern.\n\nIch habe gehört, dass der Initiand, der dieses Jahr die Opferrede hält, ein Oger namens Okrog ist, aber jetzt kommt die Überraschung: Ihr seid nur knapp <Zweiter/Zweite> geworden!\n\nWenn wir Jarod befreien möchten, müsst Ihr diese Rede halten. Keine Sorge, ich schreibe Euch ein paar Stichworte auf. Ihr müsst nur dafür sorgen, dass Okrog auf seinem Weg vom Sitz der Auserwählten einen kleinen \"Unfall\" hat.", sourceObjective = "Tötet Okrog außerhalb des Sitzes der Auserwählten auf dem Hyjal.", progress = "Nun, {name}?", completion = "Ausgezeichnete Arbeit, {name}. Unser Plan ist nun fast vollständig.", sourceObjectiveStatus = "unverified-source-field" }
quests[25315] = { id = 25315, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abschlussrede", description = "Ihr seid endlich fertig, {name}damus.\n\nIch bin so stolz auf Euch und alles, was Ihr erreicht habt.\n\nHeute werdet Ihr eine Rede vor Euren Gleichrangigen halten und sie anfeuern, unsere Feinde zu vernichten, bis der Hyjal nur noch ein Häuflein Asche ist.\n\nVergesst nicht, {name}damus. Es ist wichtig, dass Ihr die Gefühle Eures Publikums zu deuten wisst und Worte verwendet, die diesen Gefühlen entsprechen.", sourceObjective = "Benutzt das Initiationspodium in der Verdammniswacht, um die Abschlussrede zu halten.", progress = "Seid Ihr gekommen, um mich kaltzumachen?\n\nNein… Ihr scheint mir… klar im Kopf.", completion = "Ihr. Ihr gehört ganz offensichtlich nicht zu denen.\n\nWer seid Ihr dann? Ein Verbündeter?", sourceObjectiveStatus = "unverified-source-field" }
quests[25316] = { id = 25316, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hyjal in Flammen", description = "{name}! Wir haben schon so viel von Euch und Euren früheren Heldentaten gehört.\n\nEs ist gut, dass Ihr gerade jetzt hier seid, wo Azeroth Euch am meisten braucht.\n\nTodesschwinges Diener greifen den Hyjal an und haben vor, den zerstörerischen Ragnaros in unsere Welt zurückzubringen.\n\nAronus wird Euch zu Malfurions Streitmächten auf dem Hyjal bringen. Helft ihnen, wo Ihr könnt!", sourceObjective = "Fliegt mit Aronus zum Hyjal und sprecht mit Ysera, sobald Ihr angekommen seid.", completion = "<Ysera scheint in einer Art Trance zu sein.>", sourceObjectiveStatus = "unverified-source-field" }
quests[25317] = { id = 25317, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schützt den Weltenbaum", description = "<Yseras Augen sehen abwesend aus, als würde sie Euch nicht ganz erkennen.>\n\nIch fühle es auch, {class}. Ragnaros ist eingetroffen.\n\nWir müssen seine Diener vernichten, bevor er sich ihnen anschließen und ihnen seine Macht leihen kann.\n\nSucht Malfurion Sturmgrimm im Friedvollen Hain westlich von hier auf und helft seinen Streitmächten so gut Ihr könnt.\n\nIch muss im Smaragdgrünen Traum nach Antworten suchen. Ihr müsst den Weltenbaum beschützen, bis ich zurückkehre.", sourceObjective = "Sprecht mit Malfurion Sturmgrimm im Friedvollen Hain auf dem Hyjal.", completion = "Ihr seid gerade rechtzeitig angekommen, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[25319] = { id = 25319, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Krieg dem Schattenhammer", description = "Gebt Euch keinen Illusionen hin, {name}. Der Ausgang dieses Krieges entscheidet über das Überleben der Welt, wie wir sie kennen.\n\nDer Schattenhammerkult ist mit Todesschwinges Rückkehr sogar noch mächtiger geworden. Falls es ihnen gelingen sollte, den Weltenbaum an sich zu reißen, könnten sie uns einen Schlag versetzen, von dem wir uns nie erholen werden.\n\nEs ist an der Zeit, den Feind zurückzudrängen. Es ist an der Zeit, den Schattenhammer zu vernichten.", sourceObjective = "Tötet 4 Zwielichtflammenrufer und 10 Zwielichtbezwinger.", completion = "Das habt Ihr gut gemacht, {name}. Aber ich fürchte, dass die Schlacht noch lange nicht vorüber ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[25320] = { id = 25320, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die gefangene Späherin", description = "Ich habe von Euch gehört, {name}, und ich kenne die Nachrichten, die Ihr aus dem Süden bringt. Die Schlacht hat eine Pattsituation erreicht.\n\nDoch ich fürchte, dass sich diese Lage mit dem Wiedererwecken des Feuerlords schlagartig ändern wird.\n\nEs sei denn natürlich, wir könnten das Schicksal zu unseren Gunsten beeinflussen.\n\nEine unserer Späherinnen wurde vom Schattenhammer gefangen genommen. Ich glaube, sie war im Besitz von unschätzbar wertvollen Informationen. Sucht im Zwielichtlager im Westen nach ihr.", sourceObjective = "Findet Späherin Larandia bei der Zwielichtblockade auf dem Hyjal.", completion = "Endlich kommt mir jemand zu Hilfe!", sourceObjectiveStatus = "unverified-source-field" }
quests[25321] = { id = 25321, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gefangene des Zwielichts", description = "Ich habe fast einen ganzen Tag lang hinter den feindlichen Reihen gespäht, bis sie mich gefasst haben.\n\nDieser Angriff an unserer Front ist nicht das, was er zu sein scheint, {name}.\n\nIch berichte Euch alle Einzelheiten, aber holt mich zuerst hier raus!\n\nNur die Vorarbeiter haben die Schlüssel zu diesen Käfigen.\n\nSoweit ich mich erinnern kann, halten sie sich in der Mitte des Kraters auf, mitten im Getümmel.\n\nSchaut, ob Ihr einem von ihnen einen Schlüssel abnehmen könnt.", sourceObjective = "Beschafft Euch einen Schlüssel eines Zwielichtvorarbeiters im Schattenkommandoposten auf dem Hyjal.", progress = "Der Schlüssel, {name}. Habt Ihr ihn?", completion = "Ich bin Euch sehr dankbar, {name}. Ich werde unseren Leuten von meinen Erkenntnissen berichten.", sourceObjectiveStatus = "unverified-source-field" }
quests[25323] = { id = 25323, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flammenbrecher", description = "Die großen Elementare, die uns belagern, sind keine einzelnen Wesen.\n\nEs sind mehrere geringere Geister, durch die Magie der Schattenhammerkultisten zu einem verbunden.\n\nMit dem wiederhergestellten Flammenseherstab sind wir mächtig genug, dieses Band zu lösen.\n\nSobald Ihr die gefährlicheren großen aufgespalten habt, vernichtet die kleineren Elementare.", sourceObjective = "Tötet 30 ungebundene Flammengeister.", completion = "Gut gemacht, {name}. So gewinnen wir die Oberhand über den Feind.", sourceObjectiveStatus = "unverified-source-field" }
quests[25324] = { id = 25324, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein interessanter Gefangener", description = "Der Schattenhammer möchte Fandral Hirschhaupt befreien?\n\nMalfurion ist der Meinung, dass seine Verderbtheit weit fortgeschritten ist... und dies ist der beste Beweis dafür.\n\nWir können auf keinen Fall zulassen, dass unser Feind einen so mächtigen Erzdruiden in die Finger bekommt.\n\nIch habe einen Plan, {name}. Wir werden den Gefangenen durch den Smaragdgrünen Traum fortschaffen. Es wird riskant, aber bei den ganzen Kultisten hier ist es vielleicht unsere einzige Hoffnung auf Erfolg.\n\nBringt diesen Schlüssel zu Saynna Sturmläufer in den Grabhügeln im Nordosten.", sourceObjective = "Sprecht mit Hauptmann Saynna Sturmläufer in den Grabhügeln auf dem Hyjal.", completion = "Der Drache hat vielleicht Recht. Der Schattenhammer hat unsere Sicherheitsmaßnahmen umgangen. Und dies ist schließlich unser gefährlichster Gefangener.", sourceObjectiveStatus = "unverified-source-field" }
quests[25325] = { id = 25325, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Durch den Traum", description = "Alysras Plan ist vielleicht notwendig, {name}. Ich weiß nicht, wie lange wir die Kultisten noch zurückhalten können.\n\nFandral Hirschhaupt wird von mächtigen Zaubern gebunden. Er könnte Euch nicht einmal im Smaragdgrünen Traum entkommen.\n\nDoch seid vorsichtig, denn soweit wir wissen hat der Alptraum sich innerhalb des Traums auf diesen Teil der Welt ausgebreitet.\n\nBringt Fandral an die Oberfläche und übergebt ihn Alysra. Wollen wir hoffen, dass er auf der Mondlichtung sicherer aufgehoben ist als hier.", sourceObjective = "Liefert Erzdruide Fandral Hirschhaupt an Alysra am Eingang zu den Grabhügeln auf dem Hyjal aus.", progress = "Ist Hirschhaupt bei Euch, {name}?", completion = "Das habt Ihr gut gemacht, {name}. Ich werde Fandral selbst zur Mondlichtung bringen.\n\nSein Gefängnis wird weit genug von der Schlacht hier entfernt liegen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25328] = { id = 25328, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gar'gol muss gehen!", description = "<Kristoff reckt seinen Hals, um Euch in die Augen blicken zu können.>\n\nHört zu, Ihr müsst mich hier rausholen. Entweder fressen sie mich oder sie übergeben mich dem Schattenhammer. Vielleicht sogar beides.\n\nSie haben mich in Ketten gelegt und sie mit einem Schloss fest gesichert. Gar'gol bewahrt den Schlüssel in seiner persönlichen Schatzkiste auf. Tötet Gar'gol, wenn Ihr müsst, solange Ihr mir den Schüssel besorgt!\n\n<Kristoff schüttelt verzweifelt seine Gliedmaßen.>", sourceObjective = "Besorgt den rostigen Schädelschlüssel aus Gar'gols persönlicher Schatzkiste.", progress = "Schlüssel? Jetzt? Bitte?", completion = "<Kristoff streckt sich nach unten, um den Schlüssel zu schnappen.>\n\nDas wurde aber auch Zeit!\n\n<Er windet sich in seinen Fesseln und versucht, das Schloss auf seinem Rücken zu erreichen.>\n\nÄh… könnt Ihr mir hier vielleicht ein bisschen helfen?", sourceObjectiveStatus = "unverified-source-field" }
quests[25329] = { id = 25329, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Macht der Steinbrecher", description = "Der Schattenhammer meint also, hier eine Ogerarmee aufstellen zu können? Mitten im Gebiet der Horde?\n\nDas werden wir sehen.\n\nOger respektieren nur eines: Stärke. Ich möchte, dass Ihr bei der Zeremonie von Cho'gall ein Attentat verübt, {name}. Reißt die Tore Düsterbruchs auf, begebt Euch in die Menge der Anwesenden und ermordet sie.", sourceObjective = "Stört die Schattenhammerzeremonie Cho'galls.", completion = "Wir haben es geschafft! Cho'gall wurde von Euch absolut gedemütigt. Seine Diener sind tot, die Gordok sind in alle Richtungen verstreut, und alle werden von der Macht der Horde erfahren! Lok'tar, {name}! Ihr habt Euch Eure Belohnung redlich verdient.", sourceObjectiveStatus = "unverified-source-field" }
quests[25330] = { id = 25330, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verschwendetes Fleisch", description = "Schaut Euch diese Narren an. Die Hälfte von ihnen wird nicht einmal diese Prüfung bestehen.\n\nSie sind es nicht wert, in unsere inneren Kreise aufzusteigen. Aber vielleicht… vielleicht eignen sie sich ja für niedere Lakaiendienste.\n\nNehmt diesen Edelstein und nutzt seine Macht, um einige der weniger fähigen Bittsteller zu retten. Diejenigen, die keine Chance auf Erfolg haben. Bevorzugt jene, die in Flammen stehen.", sourceObjective = "Benutzt den Froststurmkristall, um 4 brennende Bittsteller zu löschen.", progress = "Habt Ihr geeignete Diener für mich gefunden, Siskdamus?", completion = "Ausgezeichnete Arbeit, Agamoldamus. Ich lasse die Diener, die Ihr für mich ausgesucht habt, in ihre neuen Pflichten einweisen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25332] = { id = 25332, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Holt mich hier raus!", description = "<Ihr greift nach oben, um Kristoffs Fesseln zu lösen.>\n\nGut! Spurtet zum Ausgang. Ich werde Euch folgen.\n\nWenn wir getrennt werden, meldet Euch wieder hier und stellt sicher, dass sie mich nicht erneut geschnappt haben.", sourceObjective = "Begleitet Kristoff aus Gar'gols Unterschlupf hinaus.", completion = "Kristoff, Kristoff… Oh ja, jetzt erinnere ich mich. Ich habe ihn auf etwas geschickt, was man als Selbstmordmission bezeichnen könnte.\n\nEr hat überlebt? Das heißt dann wohl, dass er gescheitert ist.\n\nDennoch verdient Ihr eine kleine Entlohnung für Eure Mühen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25333] = { id = 25333, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Macht der Schildwachen", description = "Der Schattenhammer? Hier?\n\nEs ist schwerwiegender, als ich dachte. Wir müssen dem ein Ende setzen. Ich weiß nicht, ob ich bereit bin, eine solche Offensive zu führen, aber ich werde nicht zulassen, dass etwas, was getan werden muss, unterlassen wird, nur weil ich Angst habe!\n\nIch werde die Streitkräfte der Mondfederfeste versammeln. Begebt Euch nach Düsterbruch, um die Aktivitäten von Cho'gall zu stören. Wir werden die Verwirrung, die dadurch entsteht, für unseren Angriff nutzen.", sourceObjective = "Stört die Schattenhammerzeremonie Cho'galls.", completion = "Willkommen zurück von der Schlacht! In den Augen der Gordunni wurde der Schattenhammer erniedrigt und aus Feralas vertrieben.\n\nWir haben die Ehre der Allianz heute in vollem Glanz gezeigt! Seid stolz!", sourceObjectiveStatus = "unverified-source-field" }
quests[25334] = { id = 25334, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die drohende Gefahr", description = "Fühlt Ihr, wie wüt'nd die Elemente sind? Schon als wir gerade erst angekomm'n war'n, wollt'n sie uns angreif'n und fress'n. Wir müss'n sie beruhigen, aber dazu müss'n wir erstmal wiss'n, was sie überhaupt aufbringt.\n\nKommt und setzt Euch neb'n mich ans Feuer. Lasst Eure Gedank'n in den Flamm'n streif'n... Lasst Eur'n Geist in die wahre Bedrohung blick'n.", sourceObjective = "Sprecht mit Scharfseher Gadra, um in Eure Geistertrance einzutauchen.", progress = "Verliert Euch ganz in den tanz'nden Flamm'n. Kommt mit mir, tiefer nach Vashj'ir, damit wir das Gesicht unseres Feindes kennenlern'n.", completion = "Wir dacht'n alle, dass es die Naga sind, aber ich wusste nich', dass der Schattenhammerkult sich unter den Well'n versteckt. Sie verderb'n und verdreh'n die Elemente und mach'n sie zu dies'n Schreck'n.\n\nWir müss'n diese beid'n Bedrohung'n bekämpf'n, um eine Chance auf Fried'n in Vashj'ir zu hab'n. Wir hab'n noch nich' genug Leute, um das zu tun.\n\nKommt, {class}. Wir hab'n viel zu tun.", sourceObjectiveStatus = "unverified-source-field" }
quests[25336] = { id = 25336, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Gefäß wird getestet", description = "Meister Uzer'i hat mich in der Herstellung mächtiger Geisterwaffen unterrichtet. Ich werde Euch unterweisen, wie man die Waffen herstellen kann, wenn Ihr mir die Möglichkeit gebt, mein Handwerk zu verfeinern.\n\nDieses Gefäß kann besiegte Kreaturen verkleinern und gefangen halten. Wir brauchen zuerst Eisenfellbärenmuisek und Langzahnläufermuisek. Tötet die Kreaturen und benutzt das Muisekgefäß, um sie zu schrumpfen und einzufangen, bevor ihre Geister fliehen können.", sourceObjective = "Tötet 10 Eisenfellbären oder Langzahnläufer, und benutzt das Gefäß für Bestienmuisek, um die gefallenen Bestien zu schrumpfen und einzufangen.", progress = "Konntet Ihr das Bestienmuisek erhalten?", completion = "Wie mein Meister es mir erklärt hat...\n\nNach einem gewaltsamen Tod kann das Muisek einer Kreatur fliehen und Rache verlangen. Durch das Schrumpfen der Kreaturen wird die Flucht verhindert. Das habt Ihr ja auch gemacht, {name}. Jetzt können wir das Muisek nach Herzenslust verwenden!", sourceObjectiveStatus = "unverified-source-field" }
quests[25337] = { id = 25337, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Muisek von Hippogryphen", description = "Als nächstes sind die Hippogryphen dran.\n\nLaut Meister Uzer'i sind die Hippogryphen den Nachtelfen jahrelang treue Begleiter gewesen, und ihre Geister sind loyal und standhaft.\n\nIch glaube nicht, dass es ihnen auffallen wird, wenn ein paar Hippogryphen fehlen, und selbst wenn, dann soll mich das nicht stören. Wir brauchen Muisek von zehn Fransenfederhippogryphen, die in der Wildnis südlich von hier zu finden sind.", sourceObjective = "Schaltet 10 Fransenfederhippogryphen eines beliebigen Typs aus und benutzt dann das Muisekgefäß, um sie zu schrumpfen und einzufangen.", progress = "Konntet Ihr die Hippogryphen einfangen?", completion = "Mein Meister hat immer gesagt, \"wenn man ein Tier tötet und das Muisek flieht, so kann es die Form einer noch wilderen Bestie annehmen\". Es ist wirklich gefährlich. Ich danke Euch, dass Ihr mir bei meinem Studium helft.", sourceObjectiveStatus = "unverified-source-field" }
quests[25338] = { id = 25338, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Muisek von Treants", description = "Die umherwandernden Waldgänger, die überall im Wald zu finden sind, sind unser nächstes Ziel, {name}. Nachtelfen haben Treants als Verbündete rekrutiert, um gegen die Horde zu kämpfen. Sie mögen zwar langsam sein, aber als Beschützer sind sie nicht zu unterschätzen.\n\nBald werden wir diese Macht für unsere eigenen Zwecke nutzen können.\n\nFindet drei umherwandernde Waldgänger, schaltet sie aus und benutzt das Muisekgefäß, um sie zu schrumpfen und einzufangen.", sourceObjective = "Schaltet 3 umherwandernde Waldgänger aus. Benutzt das Muisekgefäß, um die gefallenen Treants zu schrumpfen und einzufangen.", progress = "Konntet Ihr die wandernden Waldgänger einfangen?", completion = "Danke, {name}. Das ist das erste Mal, dass ich mit Treantmuisek arbeite...", sourceObjectiveStatus = "unverified-source-field" }
quests[25339] = { id = 25339, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rache an den Nordschwingen", description = "Zu meiner Zeit war ich ein erfahrener Jäger. Es gab keine Kreatur, die ich fürchtete. Bis...\n\nIch war draußen im Wald, um nach einem heftigen Kampf meine Klinge zu schärfen, als ich in einen Hinterhalt geriet. Harpyien umzingelten mich, und ich schaffte es kaum, mich in Sicherheit zu bringen.\n\nSelbst heute noch kann ich das Echo ihrer Schreie vernehmen...\n\nDanach war ich nicht mehr derselbe. Aber der Hass kocht in meinem Inneren - ich will Rache, auch noch nach all diesen Jahren.\n\nDie Harpyien der Nordschwingen leben westlich von hier. {name}, rächt mich.", sourceObjective = "Tötet 6 Harpyien der Nordschwingen und 6 Windruferinnen der Nordschwingen.", completion = "Danke, {name}. Ihr habt dem Geist eines alten Tauren Ruhe gegeben.", sourceObjectiveStatus = "unverified-source-field" }
quests[25340] = { id = 25340, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dunkles Herz", description = "Edana Hasskralle ist die Königin der Nordschwingen, die in den Ruinen im Westen zu Hause sind. Sie ist das vollkommen Böse; ich habe gehört, dass sie ein Herz aus Kristall hat. Sie ist bar jeglicher Emotionen außer dem Hass, den sie für alle anderen fühlt. Ihr müsst Euch Edana stellen und mir ihr dunkles Herz zurückbringen.\n\nIch habe von einem Horn gehört, das die Harpyien tragen - wenn es bei den Hasskrallensteinen, im nördlichen Teil der Ruinen, geblasen wird, wird die Königin beschworen.\n\nStellt Euch ihre Überraschung vor, wenn es nicht die ihren sind, die auf sie warten, sondern ihr Tod.", sourceObjective = "Talo Dornhuf im Camp Mojache will das dunkle Herz von Edana Hasskralle.", progress = "Der Hass, den Edana über das Land verbreitet, muss gestoppt werden.", completion = "Jetzt weiß ich, dass Edana wahrhaft tot ist. Dieses Herz; ich werde es in Erinnerung an das behalten, was Ihr hier für mich getan habt, {name}. Danke.", sourceObjectiveStatus = "unverified-source-field" }
quests[25341] = { id = 25341, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Gordunnikugel", description = "Während Ihr Schädel eingeschlagen habt...\n\nWir haben Berichte erhalten, laut denen die Oger eine größere Bedrohung darstellen als normalerweise. Ihre Hexenmeister wurden mit Kugeln gesehen, die Gegenstände mit großer Macht sein könnten.\n\nEs wäre einfach, sie als etwas anderes abzutun, aber wir müssen der Sache nachgehen, damit es keine bösen Überraschungen gibt. Bringt mir eine dieser Kugeln.", sourceObjective = "Erlangt eine Gordunnikugel von einem Hexenmeister der Gordunni.", progress = "Habt Ihr die Kugel?", completion = "Gut gemacht. Lasst mich mal sehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25342] = { id = 25342, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sprecht mit Swar'jan", description = "Hmpf, wir hatten Glück und Pech zur gleichen Zeit. Glück, dass ich Euch gebeten habe, mir diesen Gegenstand zu bringen, und Pech, weil sich meine Befürchtungen bewahrheitet haben. Dieses Ding stinkt förmlich nach Verderbtheit.\n\nUnd es ist auch viel zu neu, um einfach in den Ruinen gefunden worden zu sein. Jemand versorgt die Oger und wir müssen herausfinden, wer, bevor es ein Problem wird.\n\nBringt dieses dreckige Ding zu Swar'jan, dem Hexenmeister oben auf dem Wachturm. Er hat oft gute Ideen - wenn ich Ihr wäre, würde ich mir seine Meinung anhören.", sourceObjective = "Bringt die Gordunnikugel zu Swar'jan in der Festung der Steinbrecher.", progress = "Ja?", completion = "Was habt Ihr für mich? Ihr sagt, Ihr habt sie von den Gordunni?\n\nEkelhaft...", sourceObjectiveStatus = "unverified-source-field" }
quests[25344] = { id = 25344, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ogerentführung", description = "Es ist unmöglich, dass die Gordunni sie selbst hergestellt haben. Sie werden damit versorgt. Jemand macht ihnen Machtgeschenke und wir müssen herausfinden, wer.\n\nDie Gordok, die mit der Aufgabe geehrt werden, Düsterbruch zu bewachen, werden mehr darüber wissen. Orhan wird dich sicherlich beauftragen, ihre Reihen zu lichten, aber ich brauche einen, der am Leben ist.\n\nBringt die Kugel zurück. Sie ist einem Seelenstein ähnlich, und ich habe einige... Änderungen vorgenommen. Haltet die Kugel vor einem geschwächten Gordok hoch, und bringt ihn hier her, sobald Ihr ihn gefangen habt.", sourceObjective = "Benutzt die modifizierte Seelenkugel, um einen Ogermagier der Gordok gefangenzunehmen.", completion = "Ahh, man kann den Welpen in ihm spüren. Wir sollten ihm ein paar Fragen stellen...", sourceObjectiveStatus = "unverified-source-field" }
quests[25345] = { id = 25345, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Muisek von Feendrachen", description = "{name}, als Nächstes müsst Ihr für mich eine Kreatur fangen, die vom Aussehen her sehr zerbrechlich scheint, aber ihr mächtiger Geist ist das, was wir eigentlich besitzen wollen. Die Feendrachen, von denen ich spreche, dienen den Nachtelfen als Verbündete. Wir müssen einen von ihnen einfangen, damit auch die Horde von seiner Geisteskraft profitieren kann.\n\nHier ist das Muisekgefäß, {name}. Schaltet 8 Grimmlingflitzer oder Grimmlingdrachen aus und fangt ihr Muisek ein. Ihr könnt sie westlich von hier finden.", sourceObjective = "Schaltet 8 Grimmlingflitzer oder Grimmlingdrachen aus. Benutzt das Muisekgefäß, um die gefallenen Feendrachen zu schrumpfen und einzufangen.", progress = "Konntet Ihr das Muisek der Feendrachen einfangen?", completion = "Danke, {name}. Jetzt steht die geistige Macht der Feendrachen auch uns zur Verfügung.\n\nIch hoffe, Ihr seid willens, eine weitere Aufgabe für mich zu vollbringen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25346] = { id = 25346, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bergriesenmuisek", description = "Die Bergriesen haben die Berge verlassen, um den Nachtelfen zu helfen, als die Brennende Legion erschien. Ihr könnt sie leicht an ihrer Größe erkennen, und auch schon von Weitem daran, wie der Boden wackelt, wenn Ihr Euch ihnen nähert.\n\nIch bin sehr interessiert daran, Kraft in diesem Ausmaß nutzen zu können. Tötet sieben Bergriesen und benutzt das Muisekgefäß, um ihre mächtigen Muisek einzufangen.", sourceObjective = "Tötet 7 Bergriesen und benutzt das Gefäß für Bergriesenmuisek, um die gefallenen Bergriesen zu schrumpfen und einzusammeln.", progress = "Konntet Ihr die Bergriesen gefangennehmen?", completion = "Stellt Euch nur die Möglichkeiten vor, die wir nun haben, {name}. Mit den Materialien, die Ihr gesammelt habt, werden wir den Muisek dieser Kreaturen festhalten können, wo immer wir es wünschen", sourceObjectiveStatus = "unverified-source-field" }
quests[25349] = { id = 25349, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die verdrehten Schwestern", description = "Ich habe von Eurem Kampf mit den verderbten Drachen gehört, {name}, und ich möchte Euch für Euren Mut danken... leider habe ich schlechte Nachrichten.\n\nDie Dryaden des Waldes haben sich uns gegenüber immer friedlich verhalten, obwohl sie Verbündete der Nachtelfen sind. Sie wurden jedoch grausam und ihr Geist wurde verdreht, so dass sie nun alle angreifen, die die Wildnis östlich von hier betreten.\n\nIch mache mir um die Sicherheit der Flüchtlinge Sorgen, {name}. Bitte, bereitet den verdrehten Dryaden ein Ende.", sourceObjective = "Tötet 7 verderbte Dryaden.", completion = "Ich danke Euch, {name}, aber die Geschichte Eurer Jagd erfüllt mich mit Sorge. So viele hätten es nicht sein sollen.\n\nDie Krankheit breitet sich weiter aus...", sourceObjectiveStatus = "unverified-source-field" }
quests[25350] = { id = 25350, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der verschollene Lehrling", description = "{class}, wenn Ihr kurz Zeit hättet...\n\nEiner meiner Studenten hat sich alleine nach Süden zu den Dunkelnebelruinen aufgemacht. Ich habe ihn gewarnt, dass es zu gefährlich sei, aber er war zu aufgeregt, um mir zuzuhören... \n\nEstulan erlaubt nicht, dass wir ihm folgen. Falls Ihr in diese Richtung unterwegs seid, könnt Ihr bitte nach ihm schauen?", sourceObjective = "Sucht nach dem verschollenen Lehrling in den Dunkelnebelruinen.", completion = "<Die Leiche des Lehrlings ist kalt. Er ist schon eine Zeit lang tot.>", sourceObjectiveStatus = "unverified-source-field" }
quests[25352] = { id = 25352, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wischt den Sims sauber", description = "Ihr habt in dem Unterschlupf ausgezeichnete Arbeit geleistet, {name}. Während Eurer Abwesenheit habe ich am Schrein gebetet. In meinen Visionen hatte Goldrinn ein aufmerksames Auge auf Euch.\n\nAber wir verharren schon zu lange in Verteidigungsstellung. Es ist Zeit, dem Schattenhammer direkt gegenüberzutreten.\n\nFliegt hinauf auf den Gewittersims und durchkreuzt ihre Vorhaben. Tötet die Sturmrufer und Monstrositäten, die sie entfesseln wollen!", sourceObjective = "Tötet 8 Zwielichtsturmrufer und 5 heulende Rissbewohner.", completion = "Ihr hättet die Schlacht von hier aus sehen sollen! Die Leichen stürzten nur so von den Klippen. Spektakulär!", sourceObjectiveStatus = "unverified-source-field" }
quests[25353] = { id = 25353, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blitz in der Flasche", description = "Als ich am Schrein betete, gewährte Goldrinn mir eine weitere Vision. Ich sah Euch entschlossen auf dem Gewittersims stehen, mit Blitzen in Euren Händen. Goldrinn schien der Meinung zu sein, dass dies von größter Wichtigkeit sei, aber ich verstehe nicht, was der Ahn geplant hat...\n\n{name}, geht zum Gewittersims. Der Schattenhammer führt Versuche mit etwas durch, das sich \"Blitzkanal\" nennt. Untersucht diese Kanäle und verwendet dann dieses Totem, um den Geist von Goldrinn zu rufen und zu sehen, was er auf dem Herzen hat...", sourceObjective = "Sammelt ein aufgeladenes Kondensatorglas von einem Blitzkanal des Schattenhammers.", progress = "So treffen wir uns wieder, {class}. Wo Ihr wandelt, hinterlasst Ihr eine Spur aus Angst und Verwirrung.", completion = "Also ist es wahr! Ihr tragt wirklich Blitze in Euren Händen.\n\nIhr seid der Auserwählte, {name}. Ihr werdet mein Champion sein und meine Rache in Reiche tragen, die ich nicht betreten kann.", sourceObjectiveStatus = "unverified-source-field" }
quests[25354] = { id = 25354, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wischt den Sims sauber", description = "Der Schrein ist sicher, die Oger sind in Aufruhr. Genug. Es ist an der Zeit, in die Offensive zu gehen.\n\nEtwas Böses braut sich über uns auf dem Gewittersims zusammen. Wir müssen den Zorn der Ahnen entfesseln!\n\nFliegt hinauf zum Gewittersims und vernichtet die Anhänger des Schattenhammers dort. Zerschmettert sie, {name}! Erschlagt ihre Kreaturen und werft ihre Körper den Berg hinab!", sourceObjective = "Tötet 8 Zwielichtsturmrufer und 5 heulende Rissbewohner.", completion = "Beeindruckend, {name}. Sehr beeindruckend.\n\nIn Euch vereint sich die Stärke des Wolfsahnen mit der Weisheit, Eure Kräfte geschickt einzusetzen. Ich salutiere vor Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[25355] = { id = 25355, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blitz in der Flasche", description = "Während Ihr in dem Unterschlupf wart, gewährte Lo'Gosh mir eine Vision, {name}. Ich sah Euch den Gewittersims entlang spazieren, mit Blitzen in Euren Händen. Die Vision war sehr bewegend. Lo'Gosh schien der Meinung zu sein, dass dies von größter Wichtigkeit sei. Wir dürfen den Ahnen nicht enttäuschen.\n\nDer Schattenhammer führt Versuche mit Geräten durch, die sie \"Blitzkanal\" nennen.\n\nUntersucht diese Kanäle und verwendet dann dieses Totem, um den Geist von Lo'Gosh zu rufen und zu sehen, was er vorhat...", sourceObjective = "Sammelt ein aufgeladenes Kondensatorglas von einem Blitzkanal des Schattenhammers.", progress = "So treffen wir uns wieder, {class}. Wo Ihr wandelt, hinterlasst Ihr eine Spur aus Angst und Verwirrung.", completion = "Also ist es wahr! Ihr tragt wirklich Blitze in Euren Händen.\n\nIhr seid der Auserwählte, {name}. Ihr werdet mein Champion sein und meine Rache in Reiche tragen, die ich nicht betreten kann.", sourceObjectiveStatus = "unverified-source-field" }
quests[25356] = { id = 25356, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zum Gipfel", description = "Wir sind dabei, am Westlichen Gipfel für das ganze Gebiet in Tausend Nadeln Hilfsmaßnahmen in die Wege zu leiten. Shyn wird Euch meinen Windreiter zur Verfügung stellen, so dass Ihr sicher ankommt. Sprecht mit Kanati Grauwolke, sobald Ihr gelandet seid.\n\nIhr müsst Euch beeilen, um Leben retten zu können!", sourceObjective = "Leiht Euch von Shyn einen Windreiter und sprecht mit Kanati Grauwolke am Westlichen Gipfel in Tausend Nadeln.", completion = "Jawn schickt Euch? Gut! Wir brauchen Eure Hilfe, jetzt gleich!", sourceObjectiveStatus = "unverified-source-field" }
quests[25357] = { id = 25357, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verschafft uns Zeit", description = "So viele gute Männer mussten heute ihr Leben lassen. Ohne Euch wäre diese Zahl sogar noch höher.\n\nIhr habt unseren Dank.\n\nWenn das, was der Schamane sagt, stimmt, dann haben wir keine Zeit zu verlieren. Die Naga durchkämmen die Gewässer auf der Suche nach Überlebenden.\n\nWir sind noch nicht bereit, um zu kämpfen. Ihr müsst uns Zeit für die Vorbereitung verschaffen. Findet die Naga, die uns jagen und verlangsamt ihre Fortschritte.", sourceObjective = "Tötet 8 Räuber des Zin'jatar.", progress = "Habt Ihr den Naga einen Grund zum Nachdenken gegeben, {class}?", completion = "Hoffen wir einfach, dass Eure Anstrengungen ausreichen, um sie abzulenken.", sourceObjectiveStatus = "unverified-source-field" }
quests[25358] = { id = 25358, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nerventonikum", description = "Wie es mir geht, fragt Ihr?\n\nNun, nachdem ich von einem riesigen Seemonster vom Deck unseres Schiffes gerissen wurde und im Meer kurz vor dem Ertrinken stand… gewöhnungsbedürftig, würde ich sagen!\n\nEhrlich gesagt bin ich mit den Nerven total am Ende.\n\nWenn Ihr einige der Vorräte zusammensuchen könntet, die in den umliegenden Schiffswracks umhertreiben, könnte ich sicher etwas aus dem Hut zaubern, was die Lage etwas erträglicher macht.", sourceObjective = "Mack möchte, dass Ihr 5 Stück gesunkene Fracht im Tang'tharwald sammelt.", progress = "Konntet Ihr ein paar der Vorräte sammeln, {race}?", completion = "Ich glaube, wir beide wissen, was in diesen Kisten vor sich geht…\n\nGenau… Ferrrmenntation! Hier, bitte. Mein persönliches Geheimrezept.\n\nKein anderer Kerl würde Euch das hier geben!", sourceObjectiveStatus = "unverified-source-field" }
quests[25359] = { id = 25359, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Toshes Rache", description = "Ihr habt Toshe in der Dunstlichtkammer getroffen, oder? Er ist einigen der fliehenden Naga zu den Ruinen im Osten gefolgt und hat dann Hilfe angefordert.\n\nSucht so schnell wie möglich in den Ruinen nach Toshe. Wenn Ihr herausfindet, was die Naga wollen, lasst es uns bitte wissen!", sourceObjective = "Sprecht mit Toshe Chaosberster in den Ruinen des Thelseraitempels.", completion = "Ich erinnere mich an Euch. Ihr wart da, als sie uns in der Höhle angegriffen haben.\n\nSchön, Euch an meiner Seite zu wissen, {class}. Seid Ihr bereit für ein wenig Rache?", sourceObjectiveStatus = "unverified-source-field" }
quests[25360] = { id = 25360, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Krebs straft man nicht mit Ersäufen", description = "Diese Krebse sind nicht nett. Nicht. Nett.\n\nSams endlose Bohrerei versetzt sie in Aufruhr. Ich weiß aus Erfahrung, dass Sam sich nicht aufhalten lässt, also sollten wir uns um die andere Partei in dieser Angelegenheit kümmern. Meint Ihr nicht auch?", sourceObjective = "Tötet 10 grüne Sandkrebse.", progress = "Vorsicht. Sie kneifen.", completion = "Ist hier eigentlich alles riesengroß? Ohhh! Da kommt mir eine Idee. Vielleicht gibt es hier ja auch irgendwo ein paar stattliche Seegoblins.\n\nVielen Dank übrigens!", sourceObjectiveStatus = "unverified-source-field" }
quests[25361] = { id = 25361, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schimmer für einen neuen Umhang", description = "Grüße, {class}. Ich bin mit meinen Gefährten auf einer Mission für unsere Meister aus Orgrimmar hinunter nach Feralas gereist.\n\nMeine Lebensgefährtin Korrin liebt neue Kleider und daher habe ich vor, ihr einen neuen Umhang zu fertigen, der mit den hauchzarten Flügeln von Feendrachen geschmückt ist. Seid Ihr vielleicht in der Lage, mir zu helfen? Grimmlingflitzer mit prachtvollen Flügeln, wie ich sie will, gibt es westlich vom Camp Mojache.", sourceObjective = "Bringt 10 regenbogenfarbene Grimmlingflitzerflügel zu Krueg Schädelspalter nach Camp Mojache.", progress = "Die Grimmlingflitzer können gefährliche Tierwesen sein, wenn man sie provoziert. Seid vorsichtig im Umgang mit ihnen, {class}. Und passt noch viel mehr auf etwaige Nachtelfen in der Gegend auf. Diese lästigen Narren überfallen einen gern in den Wäldern.\n\nWenn Ihr genug Flügel habt, lasst es mich wissen, ich werde Euch sicher gut entlohnen!", completion = "Wunderbar, {class}! Die sind perfekt. Das sind genug, um einen Umhang für Korrin zu fertigen und vielleicht noch anderes! Danke.\n\nIch hoffe, die Reise war nicht zu gefährlich... Das Gebiet von Feralas ist nicht gerade als harmlos bekannt, aber Ihr habt Euch offensichtlich recht gut geschlagen.\n\nNochmals danke, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[25362] = { id = 25362, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine grausige Entdeckung", description = "Der Stamm der Grimmtotem! Diese feigen Verräter treiben sich hier immer noch herum, was?\n\nIhr müsst wieder dorthin zurück, {class}. Geht zurück und bringt mir ihre Hörner... haufenweise, wenn möglich. Die Grimmtotem sollten nicht einfach als Kleinigkeit abgestempelt oder unterschätzt werden. Geht zurück und tötet sie. Färbt die Flüsse Feralas' Rot mit ihrem dunklen Blut.", sourceObjective = "Bringt 20 Grimmtotemhörner zu Krueg Schädelspalter in Camp Mojache.", progress = "Nehmt meine Worte ernst, {class}, der Stamm der Grimmtotem ist böse. Wenn Ihr herausgefunden habt, wo sie sich aufhalten, so müsst Ihr diesen Ort aufsuchen und ihren Stamm zuerst angreifen... bevor sie in unsere Ländereien eindringen und unsere Dörfer plündern oder unser Land einnehmen.", completion = "Verräter an der Horde und an ihrem eigenen Volk...\n\nIch glaube, sie sind nicht ganz unnütz. Zumindest werden wir feine Trinkhörner daraus machen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[25363] = { id = 25363, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Krieg gegen die Waldpfoten", description = "Die Gnolle... sie sind mehr als nur ein Ärgernis. Sie sind eine konstante Bedrohung für die Existenz dieses gesamten Lagers! Es ist unwichtig, ob sie Eingeborene des Feralas sind oder nicht. Wenn wir uns nicht gegen sie wappnen, werden wir uns eines Tages aus dem gesamten Gebiet vertrieben sehen.\n\nDie Gnollangriffe auf das Lager wurden in letzter Zeit heftiger. Wir brauchen Eure Hilfe dabei, ihre Anzahl zu reduzieren. Bringt mir zehn ihrer Mähnen und ich werde Euch stattlich für Eure Mühe entlohnen.\n\nLos!", sourceObjective = "Bringt Hadoken Flinkschreiter im Camp Mojache 10 Mähnen eines Waldpfotengnolls.", progress = "Wir schlagen sie zurück und trotzdem greifen sie weiter an! Irgendjemand oder irgendetwas muss sie zur Raserei treiben... Oh, Ihr seid wieder da, was, {name}? Habt Ihr die Mähnen, die ich benötige, um das Kopfgeld auszahlen zu können?", completion = "Dies zeugt von einem guten Anfang, {name}. Euer Geschick als Soldat verdient Lob.\n\nIhr seid nicht der Einzige, dem ich diesen Auftrag gab. Viele haben bereits vor Euch gegen sie gekämpft und in der Vergangenheit haben unsere Bemühungen sie in Schach gehalten. In letzter Zeit haben jedoch ihre Versuche, nordwärts in unser Einflussgebiet einzudringen, dramatisch zugenommen. Ihre Angriffe sind außerdem wilder geworden... fast als wären sie verzweifelt.\n\nIch habe allerdings einen Plan, {name}, der die Sache mit ihnen ein für alle Mal erledigen sollte...", sourceObjectiveStatus = "unverified-source-field" }
quests[25364] = { id = 25364, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schlag gegen die Alphas", description = "Die Widerstandsfähigkeit der Gnolle kann sich leider mit ihrer Brutalität und Dummheit messen. Ich habe die Gnolle immer und immer wieder aus unserem Lager vertrieben und sie sind nur aufgrund der Gnade unseres Häuptlings noch nicht ausgerottet.\n\nIm Laufe der Jahre wurde es zu einem wahren Tanz aus Stärke und Dominanz. Wenn sie noch mehr werden und damit drohen, das Lager anzugreifen, müssen wir die Alphas, die stärksten Gnolle, ausmerzen.\n\nDas wird sie zurück in die Wälder vertreiben und uns etwas Frieden einbringen, zumindest, bis sie die erteilte Lektion wieder vergessen haben.", sourceObjective = "Töte 5 Alphas der Waldpfoten.", completion = "Ihr habt getan, was ich von Euch verlangt habe, und dafür zolle ich Euch Ehre. Nehmt dies als kleine Belohnung für Eure Anstrengungen, {name}.\n\nNun, da wir ihre Zahlen geschwächt und ihre Anführer getötet haben, werden es sich die Gnolle zweimal überlegen, unser Lager anzugreifen. Das löst aber unser eigentliches Problem nicht...\n\nEs muss einen Grund geben, warum die Gnolle in einen solchen Wahnsinn verfallen sind. Findet heraus, wo der Ursprung dessen liegt, bevor sie sich neu formieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[25365] = { id = 25365, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Waldpfotennachforschung", description = "Gnolle sind zwar nicht die Hellsten, aber sie werden bestimmt die Strategie ihrer jüngsten Aktivitäten irgendwo dokumentiert haben. Wenn wir diese Pläne finden würden, hätten wir eine bessere Vorstellung davon, was sie so aufbringt.\n\nIch möchte, dass Ihr zu den Waldpfoten zurückgeht und nach allem sucht, was Ähnlichkeit mit ihren Schlachtplänen haben könnte. Irgendwas muss es geben, ihre Angriffe waren einfach zu gut koordiniert. Findet diese Schlachtpläne und kommt zu mir zurück, sobald Ihr sie habt.", sourceObjective = "Findet die Schlachtpläne der Gnolle irgendwo in den Gnoll-Lagern südlich vom Camp Mojache.", completion = "Eine Untersuchung der Karte zeigt, dass es sich um die Schlachtpläne handelt, die Hadoken Flinkschreiter haben will. Zahlreiche Pfeile, die vielleicht Truppenbewegungen darstellen, befinden sich auf der Karte, allerdings scheinen die meisten nach Süden zu deuten, nicht nach Norden, wo das Camp Mojache liegt.\n\nEin anderer Teil der Karte enthält ein Bild von etwas, das man für irgendein großes Insekt halten könnte. Darunter befindet sich eine Art Strichliste. So, wie die Gnolle aussehen, stellt diese vielleicht ihre Verluste gegen das unbekannte Ungeziefer dar...", sourceObjectiveStatus = "unverified-source-field" }
quests[25366] = { id = 25366, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Schlachtpläne", description = "Jetzt, nachdem die Schlachtpläne der Gnolle entdeckt wurden, bleibt nur noch, die Pläne zu Hadoken Flinkschreiter in Camp Mojache zurückzubringen. Vielleicht kann er oder irgendjemand dort besser darauf schließen, was die Gnolle vorhaben.", sourceObjective = "Bringt die Schlachtpläne der Waldpfoten zu Hadoken Flinkschreiter in Camp Mojache.", progress = "Willkommen zurück, {name}. Habt Ihr ein paar nützliche Hinweise auf die Pläne der Gnolle gefunden?", completion = "Ah, das ist genau, was wir gebraucht haben. Auch wenn ich nicht sehr geschickt darin bin, das ganze Gekritzel auf dieser Karte zu entziffern, so habe ich doch in meinem Leben genug Schlachtpläne gesehen, um zu verstehen, was mit den Gnollen passiert. Es sieht so aus, als würden sie derzeit einen Zwei-Fronten-Krieg führen. Einen mit uns... Aber wie es scheint, konzentrieren sie außerdem einen Großteil ihrer Energie auf einen Feind im Süden.\n\nHier läuft mehr, als auf den ersten Blick zu erkennen ist. Wir sollten möglichst bald herausfinden, wer dieser andere Feind ist, dem sie gegenüberstehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25367] = { id = 25367, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zukk'ash-Plage", description = "Schenken wir unseren angesammelten Erkundungen Glauben, so gehört der Gegner südlich der Gnolle einer insektenartigen Rasse an. Offen gesagt spielt es keine Rolle, solange sie lebendig sind. Wenn sie die Gnolle gegen uns aufhetzen, dann sind sie eine mindestens genauso große Bedrohung - wenn nicht sogar eine größere - als die Gnolle selbst.\n\nDringt tief in das Gebiet vor, in dem die Insekten der Zukk'ash hausen; auch bekannt als Gewundene Tiefe. Dezimiert ihre Anzahl, berichtet mir von Euren Entdeckungen und bringt ihre Knochenpanzer als Beweis Eurer Taten zurück.", sourceObjective = "Bringt Hadoken Flinkschreiter im Camp Mojache in Feralas 20 Zukk'ashknochenpanzer.", progress = "Was macht die Jagd, {name}? Seid Ihr hier, um von Eurem Erfolg zu berichten?", completion = "Gut gemacht, {class}. Obwohl man der hohen Ausbreitung der Zukk'ash mit nichts anderem als einer wahren Invasion entgegentreten kann, so habt Ihr uns doch etwas Zeit verschafft, um eine geeignete Strategie entwickeln zu können.\n\nIch werde dafür sorgen, dass man diese Knochenpanzer untersucht; wir müssen alles über sie herausfinden, bevor wir es mit dem zu tun bekommen, was sich unglücklicherweise als eine schwerwiegendere Angelegenheit als angenommen entwickelt hat.", sourceObjectiveStatus = "unverified-source-field" }
quests[25368] = { id = 25368, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verinias der Verwachsene", description = "Die anderen Geister und ich werden von einem bösartigen Dämon namens Verinias gefangen gehalten; eine wahnsinnige, verunstaltete Bestie, die sich seit Jahrtausenden an unseren Seelen labt.\n\nDie Seelen und die arkane Magie, die Ihr mir gebracht habt, werden es einfach machen, ihn herauszulocken. Nehmt diese kondensierte Essenz zu dem toten Baum weit im Norden der Ruinen. Benutzt sie, um Verinias herauszulocken und tötet ihn, so dass ich endlich wieder in Freiheit sein kann.", sourceObjective = "Besiegt Verinias den Verwachsenen.", completion = "Ich bin frei... endlich! Oh, es tut so gut, frei zu sein...\n\nOh, Ihr habt es gesehen, oder?", sourceObjectiveStatus = "unverified-source-field" }
quests[25369] = { id = 25369, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zornstachel", description = "Einer unserer Späher berichtete, dass er bei den Untersuchungen der Gewundenen Tiefe ein riesiges Insekt - viel größer als die anderen gesichteten Insekten - gesehen habe, das durch das verschlungene Gelände umherstreift. Es ist nicht nur größer, es scheint auch eine Art Aura abzusondern, was die anderen Insekten nicht tun. Wir haben ihm einen Namen gegeben - Zornstachel.\n\nEine Untersuchung der Innereien dieser Bestie wäre von unschätzbarem Wert, um herauszufinden, wie man mit dieser Bedrohung am besten umgehen kann. Schneidet seine Sekretionsdrüsen heraus und bringt sie sofort zu mir zurück!", sourceObjective = "Besiegt Zornstachel in der Gewundenen Tiefe und bringt seine Drüsen zu Hadoken Flinkschreiter im Camp Mojache in Feralas zurück.", progress = "Konntet Ihr Zornstachel bereits besiegen?", completion = "Beeindruckend, {class}... sehr beeindruckend! Sollte Zornstachel wirklich eine ihrer stärksten Kreaturen sein, so werden sich die Untersuchungen der Bestie mit der Zeit als sehr wertvoll erweisen. Es liegt nun an mir, sicherzustellen, dass wir uns lange genug verteidigen können, um davon zu profitieren.\n\nBitte nehmt diese Prämie als Dankeszeichen des gesamten Camps an, {name}. Gut gemacht.", sourceObjectiveStatus = "unverified-source-field" }
quests[25370] = { id = 25370, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Entzündete Elemente", description = "Das ist kein natürliches Ereignis, {name}. Dahinter muss eine zwielichtige Macht stecken, die wir nicht bedacht haben.\n\nEs kann sein, dass derjenige, der diese elementaren Störungen verursacht, sich mit böser Magie vor unseren Augen verbirgt.\n\nIhr benötigt die Hilfe der Feendrachen, die sich in der Nähe des Weltenbaums aufhalten. Sie können die Illusionen unserer Feinde durchschauen.\n\nFüttert ihnen Wacholderbeeren, die in der Nähe wachsen, um ihr Vertrauen zu erlangen.", sourceObjective = "Füttert die Feendrachen mit Wacholderbeeren und tötet 4 Zwielichtzünder.", progress = "Schon zurück, {name}?", completion = "Das habt Ihr gut gemacht, {name}. Wir dürfen nicht zulassen, dass die Spione des Schattenhammerkults sich so nahe am Weltenbaum aufhalten.", sourceObjectiveStatus = "unverified-source-field" }
quests[25371] = { id = 25371, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der abyssische Ritt", description = "Wenn Ihr Euch in diesem Tang'tharwald fortbewegen wollt, braucht Ihr ein zuverlässiges Reittier. Ich glaube, mir ist etwas Besseres als eine Meeresschildkröte eingefallen. Und es ist auch ganz in der Nähe!\n\nBindet einen Köder an das Seil direkt westlich von uns und steigt dann auf das Seepferdchen, das dadurch angelockt wird.\n\nAber seid gewarnt. Es kann ein hartes Stück Arbeit werden, bis der Wille des Tiers gebrochen ist.", sourceObjective = "Lockt ein abyssisches Seepferdchen an und zähmt es.", progress = "Die Eleganz dieser Tiere ist einfach atemberaubend. Sie werden perfekte Reittiere abgeben.", completion = "Beeindruckend! Ihr seht erschöpft aus. Offensichtlich ließ es sich nicht so einfach zähmen.\n\nMit einem treuen Reittier an Eurer Seite sollte das Leben hier unten gleich viel einfacher sein. Herzlichen Glückwunsch, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[25372] = { id = 25372, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aessinas Wunder", description = "<Die fingerartigen Zweige an einer von Nordus Gliedmaßen brechen auf. Zum Vorschein kommt ein unberührter, glitzernder Samen.>\n\nDies ist das Herz des Waldes, der Samen des Lebens.\n\nBringt ihn zu Eurem Erzdruiden im Hain von Aessina. Hamuul Runentotem wird sicher wissen, wie seine Macht zu erwecken ist. Ich verspreche Euch, dass der Geist der Wildnis nicht länger schweigen wird. Neues Leben wird aus der Asche des alten erblühen.\n\nDanke Euch, {race}. Meine Zeit hier ist um.", sourceObjective = "Bringt das Herz des Waldes zu Hamuul Runentotem im Hain von Aessina auf dem Hyjal.", progress = "Ich bin mit meinem Latein am Ende, {name}! Aessina schweigt.\n\nHabt Ihr etwas gefunden? Was ist das?", completion = "Das ist der Schlüssel, {name}! Mit den Setzlingen, die Ihr für mich gesammelt, den Tieren, die Ihr auf dem gesamten Hyjal gerettet und dem Herz des Waldes, das Ihr jetzt auch noch entdeckt habt, können wir dieses Land direkt unter den Füßen des Schattenhammerkults wieder verjüngen. Stellt Euch nur ihre erstaunten Gesichter vor, wenn das Leben über das Chaos triumphiert...\n\nIch werde sofort mit der Zeremonie beginnen!", sourceObjectiveStatus = "unverified-source-field" }
quests[25373] = { id = 25373, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Bedrohung vom Hügel", description = "Ich bin stolz darauf, dass Mojache als sicherer Ort in der Wildnis von Feralas gilt, aber auch unserem Camp bleiben Bedrohungen nicht fern. Die Oger der Gordunni haben ein Gebiet in der Nähe des nördlichen Vorgebirges eingenommen und zerstören die Wildnis.\n\nDa unsere Brüder und Schwestern nun hier sind, um sich in Sicherheit zu bringen, kann ich nicht länger zulassen, dass die Oger in der Nähe sind. Begebt Euch nach Norden und vertreibt die Oger.", sourceObjective = "Tötet 5 Hügelwächter der Gordunni.", completion = "Ich danke Euch, {name}. Leider gibt es noch mehr Arbeit zu verrichten, um das Camp weiterhin zu sichern. Hört mir zu.", sourceObjectiveStatus = "unverified-source-field" }
quests[25374] = { id = 25374, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sasquatch-Sichtung", description = "Ihr mögt es mit Euren eigenen Augen gesehen zu haben, aber meine Fernläufer berichteten mir von etwas, das mich sehr beunruhigt. Die Gordunni in den Hügeln haben einen riesigen wilden Sasquatch eingefangen.\n\nIch weiß nicht, wie lange sie ihn festgehalten haben, aber es ist sicherlich nicht aus Spaß an der Freude. Ich fürchte, sie wollen das misshandelte Biest auf Camp Mojache loslassen.\n\nTief im Außenposten der Gordunni halten sie den Sasquatch gefangen. Geht dorthin und tötet ihn, {name}.", sourceObjective = "Tötet Großfaust.", completion = "Nun kann ich problemlos ruhen, {name}. Ihr habt unser Lager vor einer schrecklichen Bedrohung gerettet.", sourceObjectiveStatus = "unverified-source-field" }
quests[25375] = { id = 25375, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Zähmer zähmen", description = "Die Gordunni sind nicht für das Zähmen von Tieren bekannt. Wenn sie diese Fähigkeit erlernen, so ist das ein Grund, alarmiert zu sein. Nicht nur ist der Sasquatch, den sie gezähmt haben, eine enorme Gefahr für unser Lager - auch die Gordunni, die ihn eingefangen haben, müssen ihre rechte Strafe finden. Wenn wir sie am Leben lassen, können sie einfach einen weiteren Sasquatch einfangen.\n\nTötet die Zähmer der Gordunni und stellt sicher, dass die Oger verstehen, dass wir ihre Anstrengungen nicht tolerieren werden!", sourceObjective = "Tötet 6 Zähmer der Gordunni.", completion = "Gut. Hoffen wir, dass die Oger zumindest schlau genug sind, um zu verstehen, dass wir ihnen mit dieser Aktion eine Nachricht vermitteln wollten.", sourceObjectiveStatus = "unverified-source-field" }
quests[25377] = { id = 25377, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Hort der Horde", description = "<Es ist nicht ganz klar, welche Wesen diese zufällig wirkenden Markierungen auf dieses Pergament gekritzelt haben. Bei genauerer Betrachtung scheinen die obskuren Formen Orientierungspunkte zu sein.>\n\n<Ihr lasst Euren Blick über den Meeresboden wandern und seid der Meinung, einige der Punkte zu erkennen, unter anderem ein gesunkenes Schiff in der Nähe. Wenn Ihr mit Eurer Vermutung richtig liegt, sollte sich in der Nähe des Wracks eine Art Schatz befinden.>\n\n<Ihr kommt nicht umhin Euch zu fragen, was diese schuppige, schlangenartige Figur auf der Karte darstellen soll...>", sourceObjective = "Besiegt Akasha, um den Schlüssel zur Kiste der Horde zu bekommen. Öffnet dann mit dem Schlüssel die versunkene Kiste der Horde.", progress = "<Das leicht verrostete Schloss sollte noch funktionieren.>", completion = "<Ihr habt einen verlorenen Schatz entdeckt!>\n\n<Eure Gedanken überschlagen sich geradezu bei dem Gedanken, was sonst noch in der Tiefe des Meers verborgen sein könnte.>", sourceObjectiveStatus = "unverified-source-field" }
quests[25378] = { id = 25378, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ysondres Aufforderung", description = "Die Drachen der Natur... folgt ihrer Aufforderung, {name}. Wartet nicht. Ysondres Aufforderung, ihr zu helfen, ist sowohl eine große Ehre als auch ein Omen schrecklicher Gefahren.\n\nSie sprach von einem Ort namens Smaragdgipfel. Ein Pfad, weitab der Hauptstraße, führt durch die Untere Wildnis zu den hohen Steinplateaus. Dort befindet sich ein Schrein.\n\nDas Schicksal Feralas' liegt in Euren Händen. Möge die Erdenmutter über Euch wachen.", sourceObjective = "Sprecht mit Ysondre am Smaragdgipfel in der Unteren Wildnis.", completion = "Ihr seid angekommen.\n\nIch schäme mich, Euch diese Aufgabe aufzubürden, {class}, aber ich bin schon zu lange vor ihm auf der Flucht. Taerar muss aufgehalten werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[25379] = { id = 25379, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Taerars Sturz", description = "Smariss und Lethlas sind nicht mehr hier. Nur wir sind noch übrig. Ich kann mich nicht länger verstecken. Alles, was ich als Teil der Brut getan habe... all das Leid, das ich verursacht habe... ich muss es wieder gutmachen.\n\nIch bin noch immer schwach, {name}. Meine wahre Gestalt kann ich noch nicht annehmen, egal, wie sehr ich es versuche. Ich werde jedoch im Kampf an Eurer Seite stehen.\n\nWenn Ihr so weit seid, werde ich Taerar rufen. Er wird der Versuchung nicht widerstehen können, mir die Verderbtheit wieder aufzulegen.", sourceObjective = "Besiegt Taerar.", completion = "Es ist vollbracht.\n\nDas Land, das so sehr gelitten hat, kann nun ruhen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25381] = { id = 25381, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feuer mit… irgendwas bekämpfen", description = "Das Inferno, das vor uns tobt, bildet die Frontlinie zwischen uns und den Streitmächten des Feuerlords. Diese entfesselten Feuerelementare sind anders als alles, was ich je gesehen habe.\n\nKönnt Ihr uns helfen, diese Flut der Zerstörung aufzuhalten? Tötet die tobenden Feuerstürme... bevor sie den Hain von Aessina verschlingen und alle Hoffnung, diesen Berg dereinst zurückzugewinnen, zunichtemachen!", sourceObjective = "Tötet 10 tobende Feuerstürme innerhalb des Infernos.", completion = "Vielen Dank, {name}. Ihr habt uns die Chance gegeben, wieder die Oberhand zu erringen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25382] = { id = 25382, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Rituale unterbrechen", description = "Die Feuerstürme vor uns sind ungebundene Elementare in ihrer reinsten Form. Ich hätte nie gedacht, dass sie außerhalb ihrer Ebene überleben könnten. Nur äußerst geschickte Beschwörer könnten solche Wesen entfesseln.\n\n{name}, begebt Euch in das Inferno und sucht die Zwielichtinfernofürsten. Sie beschwören bestimmt just in diesem Moment Verstärkung. Bringt sie zum Schweigen... für immer!", sourceObjective = "Tötet 6 Zwielichtinfernofürsten im Inferno.", completion = "Tot? Gut!\n\nAber es scheint, als hätten wir noch so viel zu tun… so viele Feuer zu ersticken… so viel Boden zu heilen…\n\nIch hoffe, Ihr bleibt in der Nähe und helft uns dabei, den Hyjal zurückzugewinnen!", sourceObjectiveStatus = "unverified-source-field" }
quests[25383] = { id = 25383, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ysondres Abschied", description = "Nun bin nur noch ich übrig.\n\nSelbst wenn ich in dieser Welt bleiben sollte, so kann ich dem grünen Schwarm nicht wieder beitreten. Dieser Sieg erfüllt mich jedoch mit Hoffnung. Vielleicht kann ich zu gegebener Zeit ein einfaches Leben in Frieden unter den Sterblichen führen.\n\nIhr müsst zu Eurem Volk zurück. Berichtet ihnen, dass die Drachen des Alptraums nicht länger sind und diese Länder nicht mehr bedrohen werden.", sourceObjective = "Sprecht mit Häuptling Geisterhorn in Camp Mojache.", completion = "Ihr seid wahrlich von der Erdenmutter gesegnet, {name}, wenn Ihr mit den Wächtern der Natur kämpfen und überleben durftet.\n\nSeid Euch darüber im Klaren, dass alles Leben in diesem Camp Euch seine Sicherheit verdankt - und wahrscheinlich nicht nur in diesem Camp, sondern im gesamten Wald. Nehmt diese Geschenke als Zeichen unserer tiefsten Dankbarkeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[25384] = { id = 25384, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rohmaterial", description = "Danke, {class}. Wir verdanken Euch unser Leben.\n\nAber wenn wir je wieder die Oberfläche sehen wollen, müssen wir uns hier raus kämpfen. Das bedeutet, dass ich mehr Waffen und Rüstungen herstellen muss.\n\nBevor Ihr mich gefunden habt, habe ich gesehen, wie ein Soldat von einem dieser Orcas da oben gefressen wurde.\n\nIch wette, dass Ihr in ihren Mägen bestimmt ein Haufen Altmetall finden werdet, mit dem ich arbeiten kann.\n\nWenn Ihr nicht zu ihnen hinaufschwimmen möchtet, könnte man bestimmt einen mit ein paar Eingeweiden herlocken...", sourceObjective = "Samir möchte, dass Ihr 3 Stück zerfetzten Altmetalls von einem rasenden Orca im Tang'tharwald sammelt.\n\nIhr könnt einen Orca mit Zangeninnereien von Klickschnapperzangen anlocken.", sourceObjectiveStatus = "unverified-source-field" }
quests[25385] = { id = 25385, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rettet die armen Tierchen", description = "Helft uns, {class}! Der Wald steht in Flammen und die armen Tierchen finden keinen Weg hinaus. Sie können doch nicht für sich selbst kämpfen mit ihren winzig kleinen Zähnchen und ihren weichen pelzigen Pfötchen! Sie sind so kuschelig und süß.\n\nSie haben so kleine feuchte Näschen!\n\nWenn Ihr sie nicht rettet... Ach, ich will nicht einmal daran DENKEN.\n\n<Sie schlägt sich die Handflächen vor die Augen.>\n\nIch denke gar nicht darüber nach!", sourceObjective = "Geht in das Inferno und rettet eine beliebige Kombination aus 10 panischen Häschen oder verängstigten Eichhörnchen.", progress = "Habt Ihr die armen Tierchen gerettet? Und ihre armen kleinen Freunde?", completion = "Huiiiiii!\n\nHat der nette Herr {class} dich aus den Flammen gerettet, kleiner Freund? Du bist jetzt in Sicherheit!\n\nHurra!", sourceObjectiveStatus = "unverified-source-field" }
quests[25386] = { id = 25386, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zur Festung der Steinbrecher", description = "Ihr müsst jemandem von den Ereignissen hier berichten, {name}. Südlich von hier befindet sich die Festung der Steinbrecher. Unsere Verbündeten haben dort ein paar Oger der Horde versammelt, um diejenigen zu bekämpfen, die die Wälder plündern.\n\nSprecht mit Orhan Ogerklinge. Sie führt den Stamm der Steinbrecher an und muss wissen, was hier passiert ist. Seid weiterhin vorsichtig, solange noch Verderbtheit in den Landen ist...", sourceObjective = "Sprecht mit Orhan Ogerklinge in der Festung der Steinbrecher.", completion = "Ihr habt Euch mit Drachen herumgeschlagen, hm?\n\nDas gefällt mir. Wir können jemanden wie Euch gebrauchen. Seid Ihr bereit, um für die Horde zu kämpfen?", sourceObjectiveStatus = "unverified-source-field" }
quests[25387] = { id = 25387, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf nach Camp Mojache", description = "Ihr habt hier sehr gute Arbeit geleistet, {name}. Nun, da der Schattenhammer erniedrigt und die Gordunni blutend und verletzt zurückgelassen wurden, werden wir unser Augenmerk auf unser wahren Kampf mit der Allianz richten können.\n\nEs wird Zeit in Anspruch nehmen, unsere Streitmächte auszubauen, um mit den Nachtelfen mithalten zu können, die diesen Ort verpesten. Ich werde Euch nach Camp Mojache östlich von hier vorausschicken. Es gibt dort Probleme und wir können nicht zulassen, dass noch mehr Gebiete der Horde besetzt werden.\n\nLok'tar!", sourceObjective = "Sprecht mit Häuptling Geisterhorn in Camp Mojache.", completion = "Ich bin über Euer Kommen sehr dankbar, {class}. Unser Camp wird von vielen Gefahren heimgesucht, doch wir müssen uns um jene kümmern, die vor der Vernichtung des Kataklysmus auf der Flucht sind.\n\nWenn Camp Mojache wirklich ein Zufluchtsort bleiben soll, so brauchen wir Eure Hilfe.", sourceObjectiveStatus = "unverified-source-field" }
quests[25388] = { id = 25388, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kiste mit Krabbenfleisch", description = "<Diese Kiste mit der Aufschrift \"Lebende Krebse\" scheint von einem kürzlich gesunkenen Frachtschiff gefallen zu sein.>\n\n<Adarrah würde sich über diesen Fund sicher sehr freuen, vor allem nach den Strapazen, die sie durchmachen musste.>", sourceObjective = "Bringt die Kiste mit Krabbenfleisch zu Adarrah in Schmugglerschmiss.", progress = "Was habt Ihr da, {name}?", completion = "Ach, {name}! Was für eine Überraschung!\n\nWenn jemals mal jemand Euren Charakter in Frage stellt, schickt ihn nur zu mir.\n\nIch erkläre jedem, der zuhört, dass Ihr mir wirklich aus der Klemme geholfen habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[25389] = { id = 25389, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Guten Hummer", description = "Es könnte Tage dauern, bis wir an die Oberfläche aufbrechen können. Um ehrlich zu sein bin ich jetzt schon ganz schön hungrig.\n\nIch will ja nicht wählerisch erscheinen, aber es gibt nur sehr wenige Meeresfrüchte, die ich hinunterbekomme.\n\nWenn Ihr also zufällig ein paar Hummer findet, würde ich Euch für ihre Schwänze gerne mit allem belohnen, was ich habe.", sourceObjective = "Adarrah möchte, dass Ihr ihr 4 Klickschnapperschwänze bringt.", progress = "Oh, bitte sagt, dass Ihr etwas zu essen für mich gefunden habt, {class}.", completion = "Hui!\n\nDas sind die größten und saftigsten Hummerschwänze, die ich je gesehen habe!", sourceObjectiveStatus = "unverified-source-field" }
quests[25390] = { id = 25390, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Diamant ist unvergänglich", description = "Legen wir einfach mal die Karten auf den Tisch. Ich weiß, was es heißt, zu lieben, {name}.\n\nWenn ich in all den Jahren eines gelernt habe, dann dass die materiellen Werte in der Liebe länger andauern, als die Flammen der Leidenschaft.\n\nIch habe so einiges an diesen Geschenken zusammengesammelt – Edelsteine, Ringe, Halsketten und so weiter. Und ich trage sie immer bei mir.\n\nZumindest habe ich das bisher getan...\n\nAls ich vom Schiff geworfen wurde, wurden all meine Wertsachen in den Wellen verstreut. Helft mir, sie wiederzufinden. Ich werde Euch für Eure Hilfe entlohnen.", sourceObjective = "Adarrah möchte, dass Ihr 6 Andenken von Adarrah wiederbeschafft.", progress = "Nun, {race}?\n\nKonntet Ihr meine Wertsachen finden?", completion = "Oh, Ihr habt sie gefunden! Ich war mir sicher, dass sie für immer verloren sind…\n\nNehmt dies, {name}. Ich hoffe, das ist eine ausreichende Entlohnung.", sourceObjectiveStatus = "unverified-source-field" }
quests[25391] = { id = 25391, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Waffen des Geistes", description = "Es ist ein äußerst komplizierter Vorgang, die Waffen mit dem Muisek zu erfüllen. Aber da ich jetzt sowohl über alle erforderlichen Materialien als auch über das Muisek der von Euch eingefangenen Kreaturen verfüge, kann ich endlich beginnen. Bitte wartet hier, ich werde gleich zurück sein.", sourceObjective = "Hexendoktor Uzer'i will, dass Ihr einen Moment wartet, während er die Waffen vorbereitet.", completion = "Wie versprochen, habt Ihr nun die Wahl, {name}. Das Muisek dieser Kreaturen wurde auf ewig in die Macht dieser Waffen eingeschlossen.\n\nIhre Energie ist nun die Eure. Verwendet sie gut.", sourceObjectiveStatus = "unverified-source-field" }
quests[25392] = { id = 25392, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reh-Animation", description = "Sprecht Ihr Rehisch? Das Wichtigste ist die Nase.\n\n<Sie zeigt auf ihre Nase.>\n\nDie Rehe konnten vor dem Feuer flüchten, aber ihre kleinen Kitze… Einige davon sind immer noch im Feuer eingeschlossen und leiden fürchterliche Schmerzen!\n\nGeht zurück ins Inferno und begleitet drei verletzte Kitze zu ihren Müttern hier bei mir.\n\nBitte rettet die kleinen Kitze. Sonst muss ich Euch mit meinem Hundeblick dazu bringen!\n\n<Ihre Augen werden ganz groß und glänzen vor Tränen.>", sourceObjective = "Rettet drei verletzte Kitze aus dem Inferno und begleitet sie zurück zu Mylune im Hain von Aessina.", progress = "Schnell! Ich kann den Rauch riechen!", completion = "Oh, juhu! Glückliche kleine Rehlein!\n\nJetzt können sie groß werden und ABENTEUER erleben!\n\nIhr seid klasse!", sourceObjectiveStatus = "unverified-source-field" }
quests[25393] = { id = 25393, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Operation: Gnomeregan", description = "Jetzt sollte jeden Augenblick der Multiphasenangriff auf Gnomeregan beginnen, der Robogenieur Thermadraht und seine Leute ihrer gerechten Strafe zuführen wird! Zu lange schon war es Thermadraht möglich, in den Tiefen unserer Heimat zu gären, verteidigt von einer korrupten und verstrahlten Armee.\n\nDer Angriff beginnt in einem Augenblick! Seid bereit, Rekrut, dieser Kampf wird nichts für zaghafte Gemüter.", sourceObjective = "Helft König Mekkadrill beim Angriff auf Gnomeregan.", completion = "Verflucht! Wir mussten uns zurückziehen. Aber Thermadraht hat verloren, und er weiß es... er hat sich nur mehr Zeit erkauft. Wir werden die Oberfläche halten, und wenn die Strahlung abklingt, greifen wir Gnomeregan an und erobern es mit einer doppelt so großen Streitmacht zurück!", sourceObjectiveStatus = "unverified-source-field" }
quests[25394] = { id = 25394, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mehr als Krankheit", description = "Ich habe auf der Straße nördlich von hier ein paar Drachenjunge gefunden, die an einem ähnlichen Gebrechen zu leiden scheinen. Gründrachen sind die geheiligten Wächter der Natur. Allein die Tatsache, dass sich die Krankheit auf die Drachen ausbreiten konnte, ist sehr alarmierend.\n\nWir müssen verhindern, dass sie sich weiter verbreitet, egal wie. Tötet die vergifteten Welpen, {name}, und kehrt zu mir zurück.", sourceObjective = "Tötet 10 giftige Welpen.", completion = "Diese Ereignisse sorgen mich sehr. Es ist nicht das erste Mal, dass so etwas passiert...", sourceObjectiveStatus = "unverified-source-field" }
quests[25395] = { id = 25395, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das gestohlene Fass", description = "Ihr müsst uns helfen, <mein Freund/meine Liebe>. Man hat uns mit der Aufgabe betraut, eine wertvolle Ladung zu unseren Zwergenlandsleuten zu begleiten... ein Fass des feinsten Bieres, das man hier bekommt!\n\nLeider ist das Spatzenhirn da drüben bei der Arbeit eingeschlafen! Diese verfluchten Orcs haben das Fass gestohlen und nach Dun Algaz verschleppt, wo sie sich verstecken.\n\nDas geht so nicht! Nun, ich werde hierbleiben und versuchen, diesem Idioten klarzumachen, dass das sein Fehler war. Ich möchte, dass Ihr dort hineingeht und das Fass zurückholt. Für Khaz Modan!", sourceObjective = "Holt das Gebirgsjägerbier aus Dun Algaz heraus.", progress = "Habt Ihr es? Ist das arme Ding unversehrt?", completion = "Den Schöpfern sei Dank! Es ist makellos. Offenbar konnten die Orcs mit dem Schloss am Zapfhahn nichts anfangen... und in das meisterlich gefertigte Stück Handwerk der Böttcher in Eisenschmiede konnten sie mit ihren primitiven Waffen keine Löcher schlagen!", sourceObjectiveStatus = "unverified-source-field" }
quests[25396] = { id = 25396, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tränen der Steine", description = "Ihr habt gehört, wie der Drache Ysondre uns erzählt hat, dass die Tränen des Landes das Portal schließen können, aus dem die Verderbnis strömt.\n\nIhre Worte entsprechen der Wahrheit; in dem Tal westlich von hier habe ich gesehen, dass die Bergriesen leiden. Sie waren wild vor Frustration, und als sie weinten, wurden ihre Tränen, die auf die Steine fielen, zu Kristallen.\n\nDie Riesen weinen zwar nicht mehr, aber diese Steintränen sind wohl das, worauf Ysondre sich bezogen hat. Wir brauchen diese Tränen.", sourceObjective = "Sammelt 7 Steintränen.", progress = "Diese Tränen sind auf dem Gestein, aus dem die Riesen selbst entstanden sind. Am Fuße der Berge in der Nähe der großen Monolithen sollten lose Tränen sein.", completion = "Die Bergriesen sind für unser Volk wichtige Verbündete. Wir müssen die Verderbnis aufhalten, bevor noch mehr der Kreaturen des Waldes von ihr befallen werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[25397] = { id = 25397, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das verderbte Land", description = "Die Klippenriesen von Feralas sind Ausläufer der Erde selbst, {name}. Wenn es der Natur gut geht, so sind sie wohlwollende Beschützer und friedliche Wächter.\n\nDoch wenn der Wald leidet, so leiden auch sie.\n\nWenn sie von dieser Krankheit heimgesucht und verderbt werden, so werden sie sich gewaltvoll gegen die Bäume, die Tiere und selbst das Gestein, aus dem sie selbst entstanden sind, richten.\n\nSeid vorsichtig bei Eurer Aufgabe. Wenn Ihr verderbte Riesen findet, zerstört sie, zum Schutz aller, die noch nicht verderbt wurden.", sourceObjective = "Tötet 6 verderbte Klippenriesen.", completion = "Die Geister der Beschützer werden wieder zurückkehren, {name}. Ihr habt sie befreit und nun können sie im Kreislauf der Natur ihre Wege gehen.\n\nJetzt liegt es an uns, sicherzustellen, dass der Kreislauf frei von Verderbnis und grundlosem Schmerz ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[25398] = { id = 25398, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Traum versiegeln", description = "Es ist soweit. Nehmt dies, {name}; ein Fanal der Essenz der Natur, das von Ysondres Willen gesegnet wurde.\n\nNördlich von hier, auf der anderen Seite des Baches, befindet sich das Traumgeäst. Dort steht der Große Baum, der größte Baum Feralas', ein Schössling des Weltenbaums selbst. In seinem Stamm ist ein Portal, das direkt zum Smaragdgrünen Traum führt. Dieses Portal müsst Ihr schließen.\n\nDas Portal wird bewacht sein; Ihr dürft nicht verzagen.", sourceObjective = "Benutzt Ysondres Träne, um das Portal im Traumgeäst zu versiegeln.", completion = "Dank Eurem Mut haben wir eines unserer Probleme lösen können! Der Smaragdgrüne Alptraum wurde von diesem Land ausgeschlossen.\n\nDas Schicksal des Drachen Taerar besorgt mich... aber es gibt noch viel Arbeit zu verrichten. Ich kann mich mit Taerar im Moment nicht befassen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25399] = { id = 25399, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Streitmacht der Hasskämme", description = "Die Hasskämme kämpfen erbittert! Ihren Anführer auszumerzen hat oberste Priorität, aber wir müssen so viele wie möglich töten.\n\nGeht schon einmal vor, ich werde Euch auf dem Schlachtfeld treffen. Zeigt ihnen keine Gnade!", sourceObjective = "Tötet 10 Naga der Hasskämme.", completion = "Mir wurde von Eurem Heldenmut in den mir zugetragenen Berichten erzählt, {name}. Ihr habt mein Lob.", sourceObjectiveStatus = "unverified-source-field" }
quests[25400] = { id = 25400, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bedrohung durch die Gordunni", description = "Estulan, der Hochgeborene oben im Turm, lebt sehr zurückgezogen. Ich konnte mich kaum mit ihm unterhalten. Allerdings hat er mir erzählt, dass die Ruinen in der Oberen Wildnis südlich von hier voll von Ogern der Gordunni sind.\n\nDie Oger sind nicht nur eine Gefahr, sie zerstören auch den Wald und die Wildnis, in der sie sich bewegen. Estulan hat mich auch davor gewarnt, was passiert, wenn sie Artefakte mit der Macht der Hochgeborenen in den Ruinen finden...\n\nBegebt Euch nach Süden, {name}, und tötet alle Gordunni, die Ihr finden könnt!", sourceObjective = "Tötet 16 Oger der Gordunni in der Oberen Wildnis.", completion = "Es scheint, als wären es mehr Oger, als wir gedacht haben! Ich danke Euch für Euren Mut und Eure Arbeit, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[25401] = { id = 25401, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Gordunnikugel", description = "Wir müssen den Ogern nicht nur ein Ende bereiten...\n\nEstulan hat noch etwas anderes gesagt. Er meinte, die Hexenmeister der Oger hätten eine Kugel im Besitz, oder einen anderen, mächtigen Gegenstand.\n\nEr war sehr wortkarg, doch er schien beunruhigt... er sagte, es sei \"unmöglich, dass sie Hochgeborene sind\", und ich glaube, er will nur wissen, wo sie die Kugeln herhaben. Bringt mir eine dieser Kugeln.", sourceObjective = "Erhaltet eine Gordunnikugel von einem Hexenmeister der Gordunni.", progress = "Habt Ihr die Kugel?", completion = "Das ist die Kugel? Mal sehen...", sourceObjectiveStatus = "unverified-source-field" }
quests[25402] = { id = 25402, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Estulans Untersuchung", description = "Er hat Recht. Ich habe nicht viel Zeit mit den Nachtelfen verbracht, aber ich kann mit Sicherheit sagen, dass diese Markierungen nicht nach Verzierungen der Kaldorei aussehen...\n\nEstulan muss sich das anschauen. Bringt die Kugel zu ihm in seinem Turm. Er mag unwirsch erscheinen, aber stört Euch nicht daran. Sobald er die Kugel sieht, wird er merken, dass es sich um eine wichtige Angelegenheit handelt.", sourceObjective = "Bringt die Gordunnikugel zu Estulan.", progress = "Was habt Ihr da?", completion = "Ahh, die Kugel, die ich erwähnt hatte. Ein guter Grund, mich zu stören.", sourceObjectiveStatus = "unverified-source-field" }
quests[25403] = { id = 25403, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ogerentführung", description = "Nein, es ist kein einfaches Schmuckstück der Oger, und auch kein altes Relikt meines Volkes. Der Aufbau ist mir gänzlich unbekannt... und genau diese Tatsache besorgt mich sehr.\n\nDas Wolfmädchen wird Euch bald nach Düsterbruch schicken, um die Elitekämpfer der Gordok zu bekämpfen. Sie sind die Anführer der Gordunni und werden wissen, wer sie mit diesen Kugeln versorgt.\n\nNehmt die Kugel wieder an Euch - ich habe sie ein bisschen verzaubert. Haltet sie vor einem geschwächten Oger der Gordok in die Höhe. Ihr werdet ihn gefangennehmen können. Kehrt dann zu mir zurück.", sourceObjective = "Benutzt die modifizierte Seelenkugel, um einen Ogermagier der Gordok gefangenzunehmen.", completion = "Ah, Ihr habt ihn. Jetzt muss ich nur noch die Schmerzen ertragen, mir seine Worte anzuhören.", sourceObjectiveStatus = "unverified-source-field" }
quests[25404] = { id = 25404, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wenn Ihr nicht gegen uns seid…", description = "Südlich von hier findet Ihr einen alleinstehenden Turm, der als \"Schwarzhorns Buße\" bekannt ist. An ihn ist ein Dämon gebunden, Tyrus Schwarzhorn.\n\nIhr mögt mich für verrückt halten, dass ich einen ehemaligen Feind um Hilfe bitte, aber Schwarzhorn war einst sterblich. Ich kann mir kaum vorstellen, dass er dem Schattenhammer den Sieg gönnt.\n\nSprecht mit Schwarzhorn und versucht, ihn zu überreden, uns bei unserem Kampf zu helfen. Vielleicht kann er sich ja so reinwaschen.\n\nAber lasst ihn bloß nicht frei!", sourceObjective = "Sprecht mit Tyrus Schwarzhorn und überzeugt ihn, im Kampf gegen den Schattenhammer zu helfen.", progress = "Ihr wurdet hierher geschickt, um zu reden, {race}. Also. Redet.", completion = "Nun denn, {race}. Ich werde Euch Sterblichen helfen, sogar mit den mir auferlegten Fesseln.\n\nAber verursacht mir keine Übelkeit mit der Verheißung meiner Erlösung. Ich tue das aus meinen ganz persönlichen Beweggründen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25405] = { id = 25405, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rast für die Erschöpften", description = "Ihr habt Eure Aufgabe gut gemacht, {race}, aber es gibt noch viel mehr zu tun und ich bin langsam erschöpft.\n\nIch habe sehr viel Energie darauf verwendet, ein Notsignal an die Anführer des Irdenen Rings zu senden und sie um Hilfe zu bitten.\n\nWenn ich uns hier noch weiter von Nutzen sein möchte, muss ich mich ausruhen.\n\nSprecht mit dem Anführer der Männer, die Ihr gerettet habt und tut was Ihr könnt, um ihnen bei den Schlachtvorbereitungen zu helfen.\n\nDie Naga durchkämmen das Wasser nach uns. Es ist nur eine Frage der Zeit, bis sie zurückkehren. Und dann werden sie ganz sicher noch zahlreicher sein.", sourceObjective = "Sprecht mit Kapitän Taylor.", completion = "Ich verstehe, {race}.\n\nIch weiß, wie dringend es ist, aber diese Männer sind nicht in der Lage zu kämpfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25406] = { id = 25406, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Wachen der Gordok", description = "Nun, da wir uns den Ogern in der Nähe angenommen haben, sollten wir mit unserer Offensive in ihre Gebiete eindringen und angreifen.\n\nDie Oger der Gordok führen den Stamm der Gordunni an und leiten ihre Operationen von den Ruinen aus, die Düsterbruch genannt werden. Sie sind stärker als gewöhnliche Gordunni, aber ich habe keinen Zweifel daran, dass Ihr mit ihnen umzugehen vermögt, {name}. Sie werden nicht wissen, was auf sie zukommt.", sourceObjective = "Tötet 6 Vollstrecker der Gordok und 6 Ogermagier der Gordok.", completion = "Wunderbar! Alles läuft genau nach Plan. Lady Shandris wird zufrieden sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[25407] = { id = 25407, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Naturgewalten: Irrwische", description = "Die Schildwachen machen einen Großteil unserer Streitmächte aus, aber eine gut formierte Nachtelfenarmee braucht mehr als nur Nachtelfen. Die Kreaturen des Waldes, der Heimat unserer Vorfahren, haben uns seit Jahrhunderten beschützt. Wir müssen sie nur zusammenrufen.\n\nDieser Ruf wird Euch dabei helfen - unsere Verbündeten kennen den Klang und Ihr werdet sie damit versammeln können.\n\nBevor Ihr Euch jedoch aufmacht, um die Kreaturen zu versammeln, möchte ich, dass Ihr ein bisschen mit unseren Irrwischen übt. Ihr findet sie außerhalb der Festung in den Bäumen.", sourceObjective = "Benutzt Tessinas Irrwischruf, um 3 Irrwische bei der Mondfederfeste zu versammeln.", completion = "Irrwische haben seit jeher in Harmonie mit den Nachtelfen gelebt, und wir vertrauen bei vielen Dingen auf ihre Hilfe. Die Irrwische, die Ihr eben versammelt habt, werden uns nun mit ein paar Bauarbeiten und Reparaturen helfen.\n\nSeid Ihr bereit für mehr Arbeit?", sourceObjectiveStatus = "unverified-source-field" }
quests[25408] = { id = 25408, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Saat ihres Untergangs", description = "Wir werden die Schattenhammerkultisten dezimieren, indem wir sie verderben und unterwandern.\n\nDa Ihr nicht vorzuhaben scheint, mich aus meinen Banden zu entlassen, fordere ich, dass Ihr mir ein paar Reagenzien sammelt. Meine eigene dämonische Essenz hat die Pflanzen um meinen Schrein herum verderbt. Ihr müsst vom klagenden Gras um diesen Turm herum Gallbeeren ernten.\n\nMeine kleinen Haustierchen werden im Gegenzug versuchen, EUCH zu ernten. Versucht zu verhindern, dass sie sich gegenseitig aufstacheln.", sourceObjective = "Sammelt 8 Gallbeeren.", progress = "Macht Euch die Pflanzenwelt hier das Leben schwer?\n\n<Schwarzhorn grinst beunruhigend.>", completion = "Sehr gut. Bitte stampft die Beeren zu dickflüssigem Brei. Ein wundervolles Aroma, oder?\n\nNa, na! Nicht würgen! Das ist unter Eurer Würde.", sourceObjectiveStatus = "unverified-source-field" }
quests[25409] = { id = 25409, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Naturgewalten: Hippogryphen", description = "Hippogryphen sind majestätische Kreaturen. Es wird ihnen nachgesagt, dass sie von Cenarius selbst als Geschenk für die Nachtelfen erschaffen wurden. Sie sind anderen Völkern gegenüber misstrauisch, aber sie sind intelligent genug, um die Freunde ihrer Freunde als solche zu erkennen.\n\nIch brauche mehr Hippogryphen, um mit den Übungen für unsere neuen Bogenschützen zu beginnen, die das Reiten der Hippogryphen erlernen müssen. Nehmt die Pfeife und ruft damit die Fransenfederhippogryphen am Hain südlich vom Turm von Estulan zusammen.", sourceObjective = "Benutzt Tessinas Hippogryphenruf, um 10 Fransenfederhippogryphen zu versammeln.", completion = "Ein gut ausgebildeter Trupp Hippogryphenreiter kann sich fast jeder feindlichen Streitmacht annehmen. Mondfederfeste wird mit diesen noblen Kreaturen zur Seite weitaus sicherer sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[25410] = { id = 25410, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Naturgewalten: Treants", description = "Es gibt Leute, die glauben, dass die Treants zu nicht sehr viel mehr nützlich sind, als in Kriegen Getränke zu holen. Diese Leute haben nie gesehen, wie gesamte Verteidigungslinien von etwas zerstört wurden, was sie für Schutz hielten.\n\nUnd habt Ihr je gesehen, wie ein Peon versucht hat, einen von ihnen zu fällen und überrascht wurde? Ich habe Tränen gelacht...\n\nWie dem auch sei, die Treants sind unglaublich wichtige Verbündete. Ihr könnt einige von ihnen außerhalb des Turmes von Estulan umherwandern sehen. Außerdem gibt es auch noch welche im östlichen Wald, südöstlich von Düsterbruch. Seid auf der Hut vor der Horde!", sourceObjective = "Benutzt Tessinas Treantruf, um 6 wandernde Waldgänger zu versammeln.", completion = "Man mag es ihnen nicht ansehen, aber manche Treants werden zu alten Beschützern. Wir könnten ein paar mehr gut gebrauchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25411] = { id = 25411, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein neuer Meister", description = "Der Trank, den Ihr gebraut habt, ist ekelhaft genug, um die Toten zu erwecken. Und das soll er ja schließlich auch.\n\nTötet einen Zwielichtinfernofürsten und kippt ihm das Gebräu in den Rachen. Er wird wieder auferstehen, wenn auch nur kurz. In dieser Zeit steht er vollkommen unter Eurer Kontrolle.\n\nSprecht mit ihm und erfahrt den wahren Namen des Feuerelementars, den er in diese Welt geschickt hat, um Euren geliebten Wald niederzubrennen.", sourceObjective = "Benutzt das abgefüllte Gallbeerengebräu an der Leiche eines Zwielichtinfernofürsten und sprecht dann mit ihm.", progress = "<Der zitternde Leichnam wird kurz durch bösartige Magie zum Leben erweckt.>\n\n<Er nimmt keine Notiz von Euch.>", completion = "<Die gebeutelte Kreatur vor Euch spricht mit zitternder Stimme. Der Körper ist geschunden, wurde jedoch durch Schwarzhorns übles Gebräu kurz wieder zum Leben erweckt.>\n\nJa, Meister?", sourceObjectiveStatus = "unverified-source-field" }
quests[25412] = { id = 25412, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Unaussprechliche", description = "Wir haben den Zorn und die Flammen des Einen heraufbeschworen, meines ehemaligen Meisters.\n\nDas Inferno ist sein Werk.\n\nSein wahrer Name darf nie ausgesprochen werden, denn er ist die Quelle seiner Macht.\n\nJeder von uns erfuhr nur einen kleinen Teil davon, der auf einem Feuerstein eingeritzt wurde.\n\nDer wahre Name des Einen ist hier, im Inferno. Sucht die drei Steine...", sourceObjective = "Setzt den wahren Namen zusammen, indem Ihr die drei Feuersteine untersucht.", completion = "Ja, ja! Zeigt mir die Runen, die Ihr gefunden habt.\n\n\"Vol'talo Thol'embaar.\" Das ist der Name Eures echten Feinds.\n\nWahrscheinlich handelt es sich dabei um einen von Ragnaros' Generälen, die hierher geschickt wurden, um den Weg für seinen ruhmreichen Einzug zu ebnen.\n\nIch werde Euch zeigen, wie Ihr ihn vernichten könnt.", sourceObjectiveStatus = "unverified-source-field" }
quests[25413] = { id = 25413, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Planänderung", description = "In Ordnung, <Bursche/Mädel>. Kleine Planänderung…\n\nIch glaube, ich habe einen Weg gefunden, um diesem Monster den Garaus zu machen. Und Ihr werdet mir dabei helfen.\n\nSo wie ich das sehe, steht Ihr in meiner Schuld, bis meine Arbeit hier vorbei ist. Und ohne das Artefakt gehe ich bestimmt nicht.\n\nZuerst müsst Ihr für mich diese alten Schiffswracks nach einem geeigneten Seil und einer funktionierenden Harpune durchsuchen.\n\nDann.. nun, den Rest erzähle ich Euch später.", sourceObjective = "Beschafft Euch die rostige Harpune und 3 Seile.", sourceObjectiveStatus = "unverified-source-field" }
quests[25419] = { id = 25419, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lady La-Las Medaillon", description = "<Diese schwere Kette besteht aus Dutzenden von massiven Goldgliedern.>\n\n<Vom mittleren Glied hängt ein opalschimmerndes Fragment herunter, das wohl einst ein großes muschelförmiges Medaillon gewesen sein muss.>\n\n<Ihr fragt Euch, ob die anderen Bruchstücke vielleicht in der Nähe herumliegen und ob man das Medaillon wieder zu seinem ursprünglichen Zustand zusammensetzen könnte.>", sourceObjective = "Sammelt 5 Medaillonfragmente von den Sammlern der Gilblin und setzt sie zu Lady La-Las Medaillon zusammen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25420] = { id = 25420, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Uralte Hindernisse", description = "Ich habe dieses Tor jahrelang untersucht und versucht, einen Eingang zu finden, der die uralte Architektur nicht beeinträchtigt. Und dann kommen ein paar enorme Erdbeben und schlagen das ganze Ding entzwei! Was geschehen ist, ist geschehen und nun liegt der Eingang nach Uldum frei.\n\nIch hatte aber nicht damit gerechnet, dass etwas aus den Ruinen kommt, bevor wir hineingehen. Eine Masse von Golems rennen nun im Tal umher, und drinnen sind noch mehr. Jemand muss sie aus dem Weg schaffen, damit wir ins Innere können.", sourceObjective = "Zerstört 6 Sandsteingolems.", completion = "Gute Arbeit, {class}. Wir sind den Geheimnissen Uldums schon einen Schritt näher.", sourceObjectiveStatus = "unverified-source-field" }
quests[25421] = { id = 25421, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die große Tafel", description = "Auf dem Boden der Truhe findet Ihr eine große Tafel. Das Material scheint Stein zu ähneln, ist aber ganz sanft und fein anzusehen und mit seltsamen Schriften versehen.\n\nEin Teil der Schrift ist der gleiche wie an den Mauern, doch es sind auch andere Schriften darauf zu finden. Gunstan wird sich sicherlich dafür interessieren.", sourceObjective = "Bringt die große Tafel zu Gunstan.", progress = "Ihr seid zurück! Was habt Ihr gefunden?", completion = "Das ist wirklich unglaublich. Die Hieroglyphen sind zweifellos von den Titanen, aber die Markierungen darunter...\n\nIch würde hoffen, dass es sich dabei um den gleichen Text in meheren uralten Sprachen handelt. Wir könnten es benutzen, um die Hieroglyphen zu entziffern! Wenn die Vorkammer wirklich voll mit diesen Schriften ist, so werden wir noch weitaus mehr lernen können.\n\nIch möchte Euch gerne eine große Belohnung geben, {name}. Das ist der Fund des Jahrhunderts!", sourceObjectiveStatus = "unverified-source-field" }
quests[25422] = { id = 25422, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Graunebelvermächtnis", description = "Ich bin an diesen Ort gekettet... es kostet viel Energie, nur mit Euch zu sprechen. Ich halte es kaum aus, in dieser Form zu bleiben.\n\nIch kann Euch helfen, aber bitte helft mir zuerst, in dieser Welt fußzufassen. Sobald ich es geschafft habe, meine Konzentration auf diese Ebene zu lenken, sollte ich Euch helfen können...\n\nBitte, bringt mir etwas von der Erde außerhalb der Gruft. Sie ist voller uralter arkaner Ablagerungen und liegt seit Jahrhunderten vergessen dort.", sourceObjective = "Sammelt 6 Haufen leuchtende Erde.", progress = "Habt Ihr die Erde? Es fällt mir wirklich schwer, mich zusammenzuhalten... Beeilt Euch...", completion = "Vielen Dank! Ich danke Euch...\n\nEs geht mir schon viel besser. Noch ein bisschen mehr...", sourceObjectiveStatus = "unverified-source-field" }
quests[25423] = { id = 25423, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Uraltes Leiden", description = "Seid vorsichtig, wenn Ihr Eure Reise fortsetzt. Andere Geister sind an diesen Ort gebunden, bösartige Geister voller Hass. Sie haben zu viel gelitten.\n\nNichts, was sie einst waren, ist noch übrig, nur ihr Leid und der Wille, zu leben. Wir brauchen diesen Willen, um den Oberanführer zu beschwören, der mich hier festhält. Bitte, sammelt die Seelenessenzen der Geister und bringt sie mir.", sourceObjective = "Sammelt 6 Seelenessenzen.", progress = "Habt Ihr sie erhalten können?", completion = "Ihr könnt ihre Pein spüren, nicht wahr?\n\nMeine armen Freunde. Wenigstens kann ich sie benutzen, um hier etwas zu verändern...", sourceObjectiveStatus = "unverified-source-field" }
quests[25424] = { id = 25424, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr zu Alysra", description = "Ich danke Euch, dass Ihr mich befreit habt, {name}. Ich werde unseren Verbündeten von unseren Erkenntnissen berichten.\n\nIch schlage vor, dass Ihr zu dem Smaragddrachen zurückkehrt, der Euch geschickt hat.\n\nDer Schattenhammer versucht mit diesem Angriff nicht nur, neue Gebiete zu erobern. Sie sind auch hinter einem Gefangenen her.\n\nFandral Hirschhaupt wird in den Grabhügeln gefangen gehalten. Der Angriff dient auch als Ablenkungsmanöver, um ihn zu befreien. Welchen Zweck das haben soll, weiß ich nicht. Vielleicht kann unser Drachenverbündeter etwas Licht ins Dunkel bringen.", sourceObjective = "Kehrt zu Alysra bei den Ruinen von Lar'donir auf dem Hyjal zurück.", completion = "Diese Entwicklung ist sehr beunruhigend, {name}. Wir müssen schnell handeln.", sourceObjectiveStatus = "unverified-source-field" }
quests[25426] = { id = 25426, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Krieg gegen die Waldpfoten", description = "Der erste direkte Befehl von Shandris lautet, die Waldpfotengnolle hier unter Kontrolle zu bringen. Sie haben sich zu schnell zu weit verbreitet und wachsen zu einer Bedrohung für den Wald und für unsere Kriegsanstrengungen heran.\n\nSie wissen, dass wir hier sind. Nachdem wir dieses Lager eingenommen haben, haben wir verdeckte Angriffe gegen sie durchgeführt. Es ist an der Zeit einen Großangriff zu starten; bringt mir zehn von ihren Mähnen, dann sind wir bereit für die nächste Phase.", sourceObjective = "Sammelt 10 Mähnen von Waldpfotengnollen.", progress = "Die Mähnen sind keinesfalls bloß als Trophäen gedacht. Wenn es schon Blutvergießen geben muss, dann sollten wir daraus auch einen Nutzen ziehen.", completion = "Ausgezeichnete Arbeit, {name}. Wusste ich es doch, dass diese Gnolle kein Problem für Euch sein würden.", sourceObjectiveStatus = "unverified-source-field" }
quests[25427] = { id = 25427, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schlag gegen die Alphas", description = "Man sollte keine Gefahr jemals unterschätzen. Die Gnolle sehen wie einfache Rohlinge aus, aber sie haben die Gerissenheit von Tieren.\n\nDie Gnolle sind ein Rudel und jedes Rudel hat Alphamännchen: die stärksten, größten und rücksichtslosesten Mitglieder des Rudels, die sich ihre Dominanz durch nichts als den Einsatz ihrer Klauen sichern. Sie sind auch diejenigen, die die Befehle erteilen, und genau deswegen diejenigen, die wir als Nächstes töten werden.\n\nEs gibt mindestens fünf von ihnen in den verschiedenen Lagern verstreut. Ihr erkennt sie an ihrem unfreundlichen Verhalten den anderen gegenüber. Findet sie und verhaltet Euch ihnen gegenüber noch unfreundlicher.", sourceObjective = "Tötet 5 Alphas der Waldpfoten.", completion = "Perfekt. Die Gnolle, die noch übrig sind, sind nichts weiter als Beute, die in den Wäldern verloren gegangen ist.\n\nHehe... hier, Soldat, nehmt diese Belohnung, bevor ich es vergesse. Es gibt noch andere Gefahren, um die wir uns kümmern müssen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25428] = { id = 25428, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das schwarze Herz der Flamme", description = "Jetzt werdet Ihr unser neu gewonnenes Wissen nutzen, um Thol'embaar auf die Ebene der Sterblichen zu zerren, wie ein schreiendes Kind aus dem Leib der Mutter. Und dann werdet Ihr ihn vernichten.\n\nDas Ritual ist einfach: Nehmt diesen verkohlten Ast, stoßt ihn dreimal auf den Boden und sprecht laut seinen Namen.\n\nIhr müsst ihn mitten aus dem Herz des Infernos rufen. Vernichtet ihn und bringt mir sein schwarzes Herz.", sourceObjective = "Benutzt den verkohlten Ast im Inferno, um Thol'embaar herbeizurufen. Tötet ihn und nehmt Euch Thol'embaars schwarzes Herz.", progress = "Sagt mir! Habt Ihr schon gegen Thol'embaar gekämpft?\n\nIch lebe mein Leben stellvertretend durch Euch, {race}. Also enttäuscht mich nicht!", completion = "Da ist es! Welch Trophäe! Geboren in den Feuern einer anderen Ebene…\n\nLos, {race}. Zerquetscht es. Zerquetscht sein verkohltes Herz in Euren Händen und lasst den Wind die Asche forttragen… Ja, ja.", sourceObjectiveStatus = "unverified-source-field" }
quests[25429] = { id = 25429, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zukk'ash-Plage", description = "Jetzt, da die Gnolle aus dem Weg geräumt sind, können wir uns unseren anderen Feinden widmen. Unsere Späher haben in der Nähe eine Art Schwarmbau entdeckt, der sich tief unter dem Boden ausbreitet.\n\nDie Insekten in diesem Bau sind sehr groß und aggressiv. Wahrscheinlich sind sie eine noch größere Bedrohung als die Gnolle. Ich möchte, dass Ihr Euch mit äußerster Vorsicht dem Schwarmbau nähert. Vernichtet eine ansehnliche Menge der Käfer und bringt mir ihre Knochenpanzer, damit ich sie weiter untersuchen kann.", sourceObjective = "Sammelt 20 Zukk'ashknochenpanzer.", progress = "Was macht die Jagd, {name}? Seid Ihr hier, um von Eurem Erfolg zu berichten?", completion = "Also handelt es sich dabei doch um Silithiden… Ich war mir nicht sicher, da ich nie persönlich einen zu Gesicht bekommen habe. Wir hatten in Gilneas so unsere Probleme, aber zumindest gibt es bei uns nicht solche riesigen Monstrositäten!", sourceObjectiveStatus = "unverified-source-field" }
quests[25430] = { id = 25430, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Smaragdgrüne Verbündete", description = "Die Druiden des Hyjal sind nicht die Einzigen, die geschworen haben, dieses Land zu beschützen. Auch die Smaragddrachen haben sich uns erneut angeschlossen, um uns bei unserer Aufgabe zu unterstützen.\n\nSprecht mit Alysra bei den Ruinen von Lar'donir im Norden und findet heraus, wie Ihr helfen könnt.", sourceObjective = "Sprecht mit Alysra bei den Ruinen von Lar'donir am Berg Hyjal.", completion = "Meine Pflicht hier besteht darin, die Bewegung des Feindes von oben zu beobachten und unseren Armeen bei Bedarf Anweisungen zu geben.\n\nEure Hilfe kommt mir sehr gelegen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25431] = { id = 25431, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zornstachel", description = "Die meisten Insekten, die wir aus dem Schwarm bisher gesehen haben, waren groß genug, aber meine Späher haben von einem enorm großen Insekt berichtet. Anscheinend ist es eine riesige Wespe, die in erster Linie die Arbeiter an die Erde leitet.\n\nIch kenne mich damit nicht wirklich aus, aber wenn sie sich mit dieser Erdgrube nicht mehr zufrieden geben, werden wir ihnen ein Ende bereiten müssen. Tötet diese Riesenwespe und kehrt dann zu mir zurück.", sourceObjective = "Tötet Zornstachel in der Gewundenen Tiefe.", completion = "Gut gemacht, {name}! Ihr stellt Euch als äußerst nützlich bei der Sicherung dieses Gebiets für die Allianz heraus.", sourceObjectiveStatus = "unverified-source-field" }
quests[25432] = { id = 25432, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nicht aller Oger Abend", description = "Wir haben den Gordunni in Düsterbruch viel Schaden zugefügt, aber wir sind noch nicht ganz fertig mit unserem Vorhaben. Meine Späher berichten von einer Gruppe von Gordunni, die sich in den Hügeln nördlich von hier aus irgendeinem Grund versammelt haben.\n\nVielleicht sind sie an dem Lager der Horde in der Nähe interessiert, aber ich muss es mit Sicherheit wissen. Erkundet die Gegend, tötet alle Oger, die Euch über den Weg laufen, und meldet Euch wieder bei mir.", sourceObjective = "Tötet 5 Hügelwächter der Gordunni.", completion = "Gut, Euch wiederzusehen. Wir haben viel über die Situation der Oger in Erfahrung gebracht.", sourceObjectiveStatus = "unverified-source-field" }
quests[25433] = { id = 25433, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sasquatch-Sichtung", description = "Ihr habt es vielleicht selbst schon gesehen - unsere Späher berichten von einer enormen Bestie, die von den Ogern gefangen gehalten wird. Es wird gesagt, sie sehe wie ein Sasquatch aus, und wenn das der Fall ist, dann ist es wohl der größte Sasquatch, der je in Feralas gesichtet wurde.\n\nDie Oger haben wohl vor, ihn zu zähmen. Die Vorstellung ist zwar schon fast amüsant, aber ich werde nicht rumsitzen und zuschauen, wie sie dem Ding beibringen, sich auf Kommando auf die Seite zu rollen. Kehrt zu den Hügeln zurück und tötet den Sasquatch.", sourceObjective = "Tötet Großfaust.", completion = "Gut gemacht, {name}, auf Euch kann man sich verlassen. Eine weitere Gefahr wurde dank Euch aus Feralas entfernt.", sourceObjectiveStatus = "unverified-source-field" }
quests[25434] = { id = 25434, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Zähmer zähmen", description = "Die Sasquatch mögen die größere Bedrohung sein, aber zuerst müssen wir uns um die Oger kümmern. Die Gordunni sind uns schon lange ein Dorn im Auge und Lady Shandris möchte, dass wir sie ausmerzen. Hoffen wir, dass es wirklich die letzten sind.\n\nTötet die Zähmer der Gordunni, die die Biester in Ketten halten, und stellt sicher, dass sie den Preis für ihre Taten zahlen werden.", sourceObjective = "Tötet 6 Zähmer der Gordunni.", completion = "Gute Arbeit - die sind wir los! Ich hoffe, wir werden hier nie wieder irgendwelche Oger sehen!", sourceObjectiveStatus = "unverified-source-field" }
quests[25435] = { id = 25435, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schwimmt Euch in den Sattel", description = "'N Tag, <Kumpel/Mädel>.\n\nIch bin Rendel.\n\nSieht aus, als wär'n die gute alte Moanah und ich gerade rechtzeitig hier eingetroffen, was?\n\nErunak hat nicht gescherzt, als er sagte, es ginge um Leben oder Tod!\n\nWährend er sich bemüht, ein kuscheliges Versteck für uns zu finden, werd' ich mal versuchen, Euch ein Reittier zu sichern.\n\nIch bin jetzt vielleicht nicht so auf dem Laufenden, was das Leben im Meer angeht, aber die Naga scheinen hier unten bestens zurecht zu kommen.\n\nWarum sucht Ihr nicht ein paar Kleinigkeiten für das Zaumzeug zusammen? Ich arbeite solange schon einmal an der Verzauberung.", sourceObjective = "Sammelt 3 Haisehnen von gefräßigen Dreschern und 2 geschärfte Krebsscheren von Säbelklauenhuschern.\n\nIhr könnt die gefräßigen Drescher auch mit Krebsinnereien herbeirufen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25436] = { id = 25436, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Boshafte Schwestern", description = "Es ist etwas sehr beunruhigendes passiert. Auf einer ihrer Patrouillen wurden ein paar meiner Späher von Dryaden angegriffen.\n\nDie Dryaden sind enge Verbündete der Nachtelfen und Wächter des Waldes. Zuerst dachte ich, der Anblick der Worgen hätte ihnen Angst eingejagt, aber auch die Schildwachen, die ich danach losgeschickt habe, wurden angegriffen.\n\nIch weiß nicht, was hier vor sich geht, aber ich weiß, dass es mir nicht gefällt. Ich möchte, dass Ihr die Sache untersucht. Wenn auch die Dryaden der Verderbnis zum Opfer gefallen sind, so müsst Ihr sie töten.", sourceObjective = "Tötet 8 verderbte Dryaden.", completion = "Ich möchte Euch nicht ängstigen, aber wir befinden uns in einer furchtbaren Lage. Wenn das Portal im Traumgeäst verschlossen wurde und die Verderbnis sich trotzdem weiter ausbreitet...", sourceObjectiveStatus = "unverified-source-field" }
quests[25437] = { id = 25437, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ysondres Aufforderung", description = "Ein Drache des smaragdgrünen Traums... worauf habt Ihr Euch nur eingelassen, {name}?\n\nIch würde sie an Eurer Stelle nicht warten lassen. Der Ort, von dem sie sprach, ist der Smaragdgipfel. Ein Pfad, weitab der Hauptstraße, führt durch die Untere Wildnis zu den hohen Steinplateaus. Dort befindet sich ein Schrein.\n\nIch wünsche Euch viel Glück, {name}. Ich hoffe, Ihr kommt sicher zurück.", sourceObjective = "Sprecht mit Ysondre auf dem Smaragdgipfel in der Unteren Wildnis.", completion = "Ihr seid angekommen.\n\nIch schäme mich, Euch diese Aufgabe aufzubürden, {class}, aber ich bin schon zu lange vor ihm auf der Flucht. Taerar muss aufgehalten werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[25438] = { id = 25438, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ysondres Abschied", description = "Nun bin nur noch ich übrig.\n\nSelbst wenn ich in dieser Welt bleiben sollte, so kann ich dem grünen Schwarm nicht wieder beitreten. Dieser Sieg erfüllt mich jedoch mit Hoffnung. Vielleicht kann ich zu gegebener Zeit ein einfaches Leben in Frieden unter den Sterblichen führen.\n\nIhr müsst zu Eurem Volk zurück. Berichtet ihnen, dass die Drachen des Alptraums nicht länger sind und diese Länder nicht mehr bedrohen werden.", sourceObjective = "Sprecht mit Adella im Schattengeäst.", completion = "In einen Kampf der Drachen verwickelt zu werden... ich weiß nicht, ob Ihr gesegnet oder verflucht seid.\n\nLady Shandris hat von all Euren Taten gehört und hat Euch dies persönlich als Belohnung überbringen lassen. Ich bin froh, dass Ihr heil hier angekommen seid, um es in Empfang zu nehmen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25439] = { id = 25439, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das rachsüchtige Herz", description = "Das sind die Naga, die unsere Leute entführt haben. Ich brauche nur einen, um ihn zu befragen. Tötet den Rest.\n\nHabt kein Erbarmen, {class}, denn auch sie würden uns kein Mitleid gewähren.", sourceObjective = "Tötet 10 Verheerer des Zin'jatar.", completion = "Es ist gut, einen echten Krieger an meiner Seite zu haben. Meine Schamanenbrüder sind der Aufgabe zu oft einfach nicht gewachsen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25440] = { id = 25440, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tiefenlord Zin'jatar", description = "Der Tiefenlord ist hier, am anderen Ende der Ruinen. Er hat noch einige Verletzungen von unserer letzten Schlacht.\n\nIch überlasse Euch das Vergnügen, aber gebt Acht, dass er uns dieses Mal nicht entwischt!", sourceObjective = "Tötet Tiefenlord Zin'jatar.", completion = "Und damit verebben ihre Angriffe auf uns hoffentlich für eine Weile.", sourceObjectiveStatus = "unverified-source-field" }
quests[25441] = { id = 25441, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vortex", description = "Ich bin kein Freund von Schlangen, noch weniger von denen hier unten. Zu unserem Glück gehorcht das Wasser vorerst noch meinem Willen.\n\nNehmt diese Kugeln und werft sie auf den Boden, damit sich ein Vortex bildet, der alle Schlangen in der Nähe mit sich reißt. Die Naga werden die Schlangen sicher gegen uns einsetzen, also tragt die Kugeln besser immer bei Euch.", sourceObjective = "Benutzt die Kugeln des stürmischen Wassers, um 30 schwärmende Schlangen einzufangen.", completion = "Wir werden oft mit Druiden verwechselt. Bei einigen Schamanen mag das ja stimmen, aber lasst Euch nicht von dem allgemeinen Irrglauben täuschen, dass wir immer friedlich wären.\n\nNichts von dem, was ich tue, ist harmonisch. Ich beherrsche die Elemente ganz so, wie ich es will. Dafür gibt es keine Gegenleistung. Und ich würde es mir auch nicht anders wünschen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25442] = { id = 25442, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Perle der Weisheit", description = "<Diese Perle ist anders als alles, was Ihr je gesehen habt. Sie verströmt Licht und, falls Ihr Euch nicht täuscht, auch mächtige Magie.>\n\n<Erdheiler Duarn in der Silberfluthöhle wäre sicher sehr an ihr interessiert.>", sourceObjective = "Bringt die leuchtende Perle zu Erdheiler Duarn in der Silberfluthöhle.", progress = "Ja, {class}? Habt Ihr etwas gefunden?", completion = "Was ist das? Eine Perle? Hm, viel mehr noch, glaube ich.\n\nGenau danach habe ich gesucht. Vielen Dank, dass Ihr sie mir gebracht habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[25443] = { id = 25443, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Unaussprechliche", description = "Hat mein Trank gewirkt? Habt Ihr mit einem von ihnen gesprochen?\n\nDann wisst Ihr ja, was zu tun ist. Der Name ihres Elementarmeisters steht auf drei Feuersteinen geschrieben, die überall im Inferno verstreut sind. Überprüft jeden einzelnen von diesen Steinen und wir haben den Namen, den wir brauchen.\n\nSchnell! Euer geliebter Wald brennt!", sourceObjective = "Setzt den wahren Namen zusammen, indem Ihr die drei Feuersteine im Inferno untersucht.", sourceObjectiveStatus = "unverified-source-field" }
quests[25444] = { id = 25444, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die perfekten Spione", description = "Es wär dumm, hia blind zu arbeiten, also mach' ich 'n paar winzige Spione, die für Vol'jin Informationen sammeln soll'n. Er muss wissen, was drüben auf den Inseln passiat.\n\nIch könnt' die Hilfe brauch'n, wenn Euch danach is. Ich sag' Euch, was zu tun is. East müsst Iah die Frösche fang'n. Sie bleim gean im Schatten dea Palmen um Sen'jin rum.\n\nWenn Iah die Frösche habt, bringtse hia rüber zu mei'm Totem des Wachens un' stimmt se auf meine Sicht ab.", sourceObjective = "Fangt 5 Frösche aus Sen'jin und stimmt sie bei Vaniras Totem des Wachens auf ihre Sicht ab.", progress = "Helft Iah jetzt mit die Frösche oder nich?", completion = "Das is genug für meine Zwecke. Nu zum schwierigen Teil.", sourceObjectiveStatus = "unverified-source-field" }
quests[25445] = { id = 25445, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zalazanes Sturz", description = "Die Zeit zum Kämpfen ist jetzt! Schon bald brechen wir auf zu den Inseln, halt dich also bereit.\n\nZalazane hat nicht mehr viel Zeit.", sourceObjective = "Helft Vol'jin die Echoinseln zurückzuerobern und Zalazane zu töten.", completion = "{name}, du bist ein mächtiger Krieger und ein leidenschaftlicher Kamerad der Dunkelspeere. Die Echoinseln sind jetzt UNSER und wir hätten es ohne dich nie schaffen können.\n\nNimm diesen Umhang. Trag ihn mit Stolz. Jetzt bist du Mitglied des Stamms!\n\nBald haben die Trolle wieder eine Heimat und wir haben dir dafür zu danken.", sourceObjectiveStatus = "unverified-source-field" }
quests[25446] = { id = 25446, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Frösche frei!", description = "Nu, wo die Frösche startklar sin', brauch' ich Eure Hilfe, um sie rüba auf die Inseln zu schick'n.\n\nIm Osten von Sen'jin is Tiaführer Marnlek. Eah füaht die Fledamäuse für Vol'jins Späher und kann Euch 'ne Fledermaus leih'n, um raus zu den Inseln zu kommen.\n\nNehmt den Sack Frösche hia mit. Ich hab' die Geista um Hilfe gebeten. Sie ham Rauch geschickt, um Euch zu zeig'n, wo ich die Augen am meisten brauch. Wenn Iah auf'er Fledermaus sitzt, greift in'n Sack un' werft die Frösche in'n weißen Rauch.", sourceObjective = "Benutzt, während Ihr Euch auf dem Rücken einer Fledermaus befindet, den Sack Frösche, um 12 abgestimmte Frösche bei den Markierungen auf den Echoinseln zu platzieren.", completion = "Ich seh' schon, was die Frösche seh'n. Iah habt das pafekt gemacht, {name}. Nu können Vol'jin un' ich seh'n, was Zalazane voahat.", sourceObjectiveStatus = "unverified-source-field" }
quests[25447] = { id = 25447, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zeichen des Wandels", description = "Eine üble Krankheit hat die Kreaturen unseres Waldes heimgesucht. Zuerst dachte ich, es wäre einfach eine der Tücken der Natur, aber der Krankheit scheint kein Heilungsprozess zu folgen.\n\nDie Hirsche des Waldes, die normalerweise sehr stark und friedlich sind, haben am meisten gelitten. Einige finden in ihrer Schwäche ihr Ende. Andere sind tollwütig und sehr gefährlich. Um die Geister zu befragen und mehr über die Krankheit in Erfahrung zu bringen, benötige ich die Geweihe der Hirsche.", sourceObjective = "Sammelt 8 infizierte Hirschgeweihe.", progress = "Es ist keine schöne Aufgabe, aber es muss getan werden, {name}.", completion = "Zumindest haben wir dem Leiden dieser Kreaturen ein Ende bereitet. Lasst uns hoffen, dass durch ihr Opfer weiteres Leid verhindert werden kann.", sourceObjectiveStatus = "unverified-source-field" }
quests[25448] = { id = 25448, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Nordschwingenbedrohung", description = "Meine Aufgabe ist es, über Telaron zu wachen. Auch ohne die Meditation, die ihn so verletzlich macht, gibt es in diesem Wald genügend Bedrohungen, die uns beschäftigen.\n\nGenau deshalb stört es mich so sehr, dass ich das Camp nicht verlassen kann. Mehr Harpyien als je zuvor suchen das Gebiet im Nordwesten heim... bösartige Kreaturen, die ihren Dreck überall in den alten Ruinen hinterlassen und sich nicht daran stören.\n\nSie sind eine Bedrohung für unser Lager und haben an diesen Orten nichts zu suchen. Ich werde Euch reichlich belohnen, wenn Ihr Euch ihnen annehmt.", sourceObjective = "Tötet 6 Harpyien der Nordschwingen und 6 Windruferinnen der Nordschwingen.", completion = "Danke, {class}. Eine Störung weniger, um die ich mich kümmern muss.", sourceObjectiveStatus = "unverified-source-field" }
quests[25449] = { id = 25449, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Zeichen der Qualität", description = "Meine Einstellung zur Lederverarbeitung verlangt, dass die Arbeit von bestmöglicher Qualität zu sein hat - ohne Kompromisse. Jeder, der behauptet, Qualität sei unwichtig, wird auch versuchen, Euch ein Küstengrundstück in Dun Morogh zu verkaufen!\n\nAuf meiner jüngsten Suche nach hochwertigem Material fand ich dicke Yetibälge. Die Yetis sind in Feralas zuhause und viele findet man in der Wutschrammfeste im Nordosten. Ich hätte gern ein paar Bälge und wenn Ihr mir zehn davon bringt, dürft Ihr Euch ein beliebiges Stück meiner Lederwaren aussuchen. Haltet Ihr das für angemessen? Dann sind wir im Geschäft.", sourceObjective = "Sammelt 10 dicke Yetibälge.", progress = "Für zehn Yetibälge könnt Ihr Euch ein beliebiges Stück meiner Lederwaren aussuchen. Qualität ist mir wichtig und Ihr könnt Euch sicher sein, dass Ihr etwas Hochwertiges erhalten werdet!", completion = "Hattet Ihr die Zeit, die Beschaffenheit dieser Bälge zu bewundern? Richtig verarbeitet können sie widerstandsfähiger sein als Eisen. Nur wenige Leute sind mit diesen Bälgen vertraut und in Verbindung mit bestimmten Lösungen kann ich damit richtige Qualitätswaren herstellen - dank Euch natürlich!\n\nBitte, sucht Euch etwas aus meinem Sortiment aus, als Dank für Eure Mühen!", sourceObjectiveStatus = "unverified-source-field" }
quests[25450] = { id = 25450, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beste Qualität", description = "Es ist schon faszinierend, wie sich die Dinge ändern. Die Yetis aus dem Norden haben immer die besten Bälge gehabt, aber diese hier... die Qualität ist wirklich nicht so gut wie sie einst war. Vielleicht sind sie krank, oder werden von etwas krank gemacht.\n\nGlücklicherweise sieht es bei den Wildschrammyetis viel besser aus als früher. Ich wette, dass ihre Bälge jetzt weitaus besser als früher sind!\n\nIch würde Euch für zehn ihrer Bälge gebührend entlohnen. Bringt mir die Bälge, und wir sind im Geschäft.", sourceObjective = "Sammelt 10 Wildschrammyetibälge.", progress = "Diese Bälge sind zwar nicht so widerstandsfähig wie Thorium, aber sie sind gut und fest.", completion = "Exzellent, Exzellent! Ich denke, diese Bälge werden ihren Zweck hervorragend erfüllen - und mit der richtigen Behandlung werden sie noch um einiges widerstandsfähiger werden.\n\nDanke nochmal für Eure Unterstützung, {name}. Hier, nehmt eine meiner neuesten Kreationen!", sourceObjectiveStatus = "unverified-source-field" }
quests[25451] = { id = 25451, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Makelloser Yetibalg", description = "Ihr habt einen makellosen Yetibalg gefunden, der besonders dick und widerstandsfähig ist - sogar robuster als die Yetibälge aus der Wutschrammfeste.\n\nIn Anbetracht der Tatsache, dass Pratt McGrubben in der Mondfederfeste mit Yetibälgen handelt, dürfte ihn dieser Fund besonders interessieren.", sourceObjective = "Bringt Pratt McGrubben in der Mondfederfeste den makellosen Yetibalg.", progress = "Was ist los, {name} - habt Ihr etwas Interessantes für mich?", completion = "Fantastisch! Es sieht so aus, als hättet Ihr die Mutter aller Yetibälger gefunden!\n\nIhr könnt Euch darauf verlassen, dass mir dieser Fund einiges wert ist. Normalerweise zahle ich niemandem so viel für einen einzelnen Balg. Doch bin ich mir sicher, dass sich aus diesem hier etwas ganz Besonderes herstellen lässt. Danke {name}, dass Ihr bei Eurem Fund an mich gedacht habt!", sourceObjectiveStatus = "unverified-source-field" }
quests[25452] = { id = 25452, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Zeichen der Qualität", description = "Ich bin stolz auf meine Lederarbeiten und ich glaube, das sieht man ihnen an; Qualität sollte niemals zweitrangig sein. Jeder, der behauptet, Qualität sei unwichtig, wird Euch wahrscheinlich auch glauben machen wollen, dass die Erde keine Geheimnisse enthält!\n\nAuf meiner jüngsten Suche nach hochwertigem Material habe ich dicke Yetibälge entdeckt. Die Yetis sind in Feralas beheimatet und man findet sie nördlich von hier, in der Wutschrammfeste. Ihr dürft Euch ein beliebiges Stück meiner Lederwaren aussuchen für einen Zehnerstapel Yetibälge. Wenn das für Euch akzeptabel ist, dann sind wir im Geschäft!", sourceObjective = "Sammelt 10 dicke Yetibälge.", progress = "Konntet Ihr alle Yetibälge besorgen? Meine Lederwaren sind unvergleichlich und ich werde Euch ein Stück meiner handverarbeiteten Qualitätswaren zukommen lassen, wenn Ihr die Bälge habt.", completion = "Ah, wunderbar! Ich sage Euch, diese Bälge sind so widerstandsfähig wie Eisen, man muss ihnen nur eine besondere Behandlung zuteilwerden lassen. Es wird einige Versuche kosten, die richtige Mischung zum Gerben zu finden, aber ich bin zuversichtlich, dass sie mein Zeichen der Qualität noch weiter aufwerten werden.\n\nAber nun zu Euch, {name}: Eure Hilfe hat sich als unschätzbar für mich erwiesen. Bitte sucht Euch einen der Gegenstände aus, die ich hergestellt habe.", sourceObjectiveStatus = "unverified-source-field" }
quests[25453] = { id = 25453, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beste Qualität", description = "Ich bin etwas verwirrt. Die Wutschrammyetis waren einst die Quelle des besten Leders dieser Länder... aber diese Bälge sind schwach und an manchen Stellen verrottet. Die Kreaturen müssen an einer Art Krankheit leiden.\n\nIch werde eine andere Bezugsquelle finden müssen. Die Yetis aus Wildschrammtal im Süden haben auch sehr starke Bälge. Sie sind aber auch viel gefährlicher; man sollte bei der Jagd auf sie sehr vorsichtig sein.", sourceObjective = "Sammelt 10 Wildschrammyetibälge von Wildschrammyetis.", progress = "Sind die Wildschrammyetis noch da? Habt Ihr die Bälge?", completion = "Exzellent, Exzellent! Ich denke, diese Bälge werden ihren Zweck hervorragend erfüllen - und mit der richtigen Behandlung werden sie noch um einiges widerstandsfähiger werden.\n\nDanke nochmal für Eure Unterstützung, {name}. Hier, nehmt eine meiner neuesten Kreationen!", sourceObjectiveStatus = "unverified-source-field" }
quests[25454] = { id = 25454, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Perfekter Yetibalg", description = "Ihr habt einen Yetibalg gefunden, der beinahe perfekt scheint. Euch fällt schnell auf, dass dieser außergewöhnlich dick und widerstandsfähig ist - sogar robuster als die Yetibälge aus der Wutschrammfeste.\n\nIn Anbetracht der Tatsache, dass Jangdor Flinkschreiter in der Festung der Steinbrecher mit Yetibälgen handelt, dürfte ihn dieser Fund besonders interessieren.", sourceObjective = "Bringt Jangdor Flinkschreiter in der Steinbrecherfestung in Feralas den perfekten Yetibalg.", progress = "Was ist los, {name} - habt Ihr etwas Interessantes für mich?", completion = "Dieser Fund ist einfach unglaublich! Ich glaube dies hier ist der beste Balg, den ich je gesehen habe!\n\nTatsächlich wäre hier eine großzügige Belohnung angebracht. Normalerweise zahle ich niemandem so viel für einen einzelnen Balg. Doch bin ich mir sicher, dass sich aus diesem hier etwas ganz Besonderes herstellen lässt. Danke {name}, dass Ihr bei Eurem Fund an mich gedacht habt!", sourceObjectiveStatus = "unverified-source-field" }
quests[25456] = { id = 25456, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unversehrte Rückkehr", description = "Ja, ja, ich bin mir sicher, dass Felora Euch zurückhaben möchte. Diese Frau hat einfach keinen Respekt vor Innovationen. Als ich ihr von den Modifizierungen für meinen Erdelementar erzählt habe, hat sie fast einen Anfall bekommen.\n\nGeht schon und sagt ihr, dass alles fein und klärchen ist. Und sagt ihr auch, dass ich ihr nichts von meinem unausbleiblichen Vermögen abgeben werde.\n\nWahrscheinlich schläft sie sowieso am liebsten auf dem Felsen.", sourceObjective = "Kehrt zu Felora Feuerkranz in der Silberfluthöhle zurück.", completion = "Also ist Sam unversehrt? Und seine arme Assistentin Felice? Das ist gut zu hören.\n\nIch hoffe, dass die Elemente für ihn eines Tages mehr als nur Werkzeuge sind.", sourceObjectiveStatus = "unverified-source-field" }
quests[25458] = { id = 25458, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kommandant Skessesh", description = "Die Anführer dieser Streitmächte müssen fallen! Die Offensive der Naga wird zerbrechen, wenn niemand mehr da ist, um sie anzuführen.\n\nIch habe gesehen, wie der Feigling sich in einem der verlassenen Gebäude versteckt hat. Bahnt Euren Weg durch die anderen und besorgt mir seinen Kopf! Lady Shandris wird ihn selbst in den Händen halten wollen.", sourceObjective = "Tötet General Skessesh und nehmt seinen Kopf.", progress = "Ist der General gefallen?", completion = "Gut gemacht, diese garstigen Kreaturen verdienen es nicht anders. Mögen die Naga ins Meer zurückglitschen und diesen Ort nie wieder aufsuchen.\n\nIhr habt Euch auf dem Schlachtfeld bewiesen, {name}. Ich werde bei der Verteidigung dieser Länder Eure Hilfe noch öfter in Anspruch nehmen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25459] = { id = 25459, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ophidophobie", description = "Wenn es eine Sache gibt, die ich nicht leiden kann, dann sind es Schlangen. Alle Schlangen, egal welche Art.\n\nWährend ich da draußen nach verwertbaren Teilen gesucht habe, habe ich ein Nest von Seeschlangen um das nahegelegene Wrack herum gesehen.\n\nIch fühle mich einfach nicht wohl bei dem Gedanken, dass diese schrecklichen Biester sich jeden Moment hier herein schlängeln könnten.\n\nBitte, {class}! Unternehmt etwas gegen sie!", sourceObjective = "Tötet 4 Laugenschuppenschlangen in Gorroks Klage.", completion = "Da fällt mir aber ein Stein vom Herzen.\n\nVielen Dank noch einmal, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[25460] = { id = 25460, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Erde erhebt sich", description = "Sogar hier, so nahe am Weltenbaum, fühlen wir die Folgen des Angriffs des Schattenhammers.\n\nUnd da die Bäume in Flammen stehen, wendet sich sogar die Erde in rasendem Zorn gegen uns.\n\nWir dürfen nicht zulassen, dass die Elementare frei durch die Gegend streifen. Geht und helft unseren Männern, ihrer Herr zu werden.", sourceObjective = "Tötet 8 brühende Felselementare.", completion = "Ich danke Euch, {name}. Euer Kampfgeschick ist beeindruckend. Ihr werdet in unserem Bestreben, dem Angriff der Elementare ein Ende zu setzen, eine entscheidende Rolle spielen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25461] = { id = 25461, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Freiwillige Trolle vor!", description = "Vol'jin hat mir seine Kriegstrommeln gegeben und mia die Verantwortung für die Ausbildung von den neuen Rekruten hia übageben. Das Dumme is nur, dass wia keine neuen Rekruten ham.\n\nWenn ich Euch diese Trommel leih'n wüade, wüadet Iah füa Vol'jin nach Klingenhügel gehn un da den Kriegsruf vabreiten? Wenn Iah auch nua n paar Trolle dazu inspirian könntet, sich anzuschließn, wüade das schon nen Untaschied machen. Wenn Iah sie übazeugt habt, sich freiwillig zu meld'n, bringt sie zu mia zum Ausbilden zurück. Geht rüba zu Tiaführer Marnlek im Süd'n. Eah kann Euch eine Fledamaus für den Flug nach Klingenhügel leih'n.", sourceObjective = "Benutzt Vol'jins Kriegstrommeln, um 5 Trollbürger in Klingenhügel zu rekrutieren.\n\nIhr könnt mit Tierführer Marnlek sprechen, um eine Fledermaus nach Klingenhügel zu bekommen.", progress = "Wia brauch'n alle Freiwilligen, die wia krieg'n könn'.", completion = "Iah habt 'n paa gute Rekrut'n gefund'n. Ich trainier' sie hart, un' wia wern nich' aufhör'n, bis wia Zalazane von unsern Inseln vartrieben ham.", sourceObjectiveStatus = "unverified-source-field" }
quests[25462] = { id = 25462, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Runter kommen sie alle", description = "Fürchtet Euch nicht vor den Bären in diesem Hain, {class}. Ich habe sie für eine Weile besänftigt.\n\nIch sorge mich vielmehr um das Wohlergehen der Bärenjungen. Aus Angst vor dem Feuer sind die Kleinen auf die Bäume geflüchtet und sitzen jetzt dort fest. Wir müssen die Bären wieder heil auf den Boden bringen!\n\nFliegende Wesen schüchtern sie ein, also müsst Ihr wohl selbst auf die Bäume klettern. Sucht die Stämme nach geeigneten Stellen ab, klettert auf die Bäume, schnappt Euch die Bären und werft sie VORSICHTIG auf das Ziel hier.\n\nDieser Plan ist narrensicher.", sourceObjective = "Klettert auf die Bäume im Rauschenden Hain, greift nach hilflosen Hyjalbärenjungen und werft sie oben vom Baum aus auf das weiche Ziel. Ihnen kann nichts passieren.", progress = "Bitte verletzt die Bäume nicht. Oder die Bären.\n\nOder Euch selbst.", completion = "Ich danke Euch, {name}. Diese kleinen Bären haben einiges mitgemacht, aber sie werden überleben.\n\nZumindest die, die auf der Matte gelandet sind.", sourceObjectiveStatus = "unverified-source-field" }
quests[25463] = { id = 25463, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Berichtet Silvia", description = "Ein hochgeborener Magus namens Estulan hat östlich von hier einen Turm gebaut, nachdem er sich von seinen überlebenden Brüdern entfremdet hat, und unterrichtet dort nun junge Nachtelfen in arkaner Magie.\n\nWenn Hohepriesterin Tyrande nicht vor Kurzem Gnade über die Seinen hätte walten lassen, so wäre es nun laut unserer Gesetze meine Aufgabe, ihn hinzurichten. Er wird streng bewacht, doch nur aus Stolz kann ich den Schildwachen Hilfe nicht abschlagen.\n\nIch habe Silvia vorgeschickt, um beim Turm von Estulan die Offensive gegen die Oger in der Nähe einzuleiten, die die Wälder in der Nähe heimsuchen. Meldet Euch bei ihr, um weitere Anweisungen zu erhalten.", sourceObjective = "Meldet Euch bei Siliva am Turm von Estulan.", completion = "Gut, Euch hier zu sehen. Estulan ist... schwierig. Wir werden uns zuerst für Shandris alleine um die Oger kümmern müssen, bevor Estulan eine Entscheidung treffen wird, ob er uns helfen möchte oder nicht.", sourceObjectiveStatus = "unverified-source-field" }
quests[25464] = { id = 25464, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Baron Geddons Rückkehr", description = "Ragnaros ist nicht der einzige mächtige Elementar, der wieder in unsere Welt gelangt ist.\n\nDer gefürchtete Baron Geddon führt das Massaker an. Wir müssen seiner Zerstörungswut ein Ende setzen.\n\nDer Flammenseherstab hat sich als sehr mächtig erwiesen. Vielleicht ist er mächtig genug, um den Baron so zu schwächen, dass unsere Erzdruiden ihn an Ort und Stelle fesseln können.\n\nGeht, {name}, und seid vorsichtig. Baron Geddon ist ein rachsüchtiges und heimtückisches Wesen.", sourceObjective = "Nutzt die Macht des Flammenseherstabs, um Baron Geddon zu schwächen.", progress = "Habt Ihr Eure Aufgabe schon erledigt, {name}?", completion = "Gut gemacht, {name}. Wir können es uns nicht leisten, noch mehr Gebiete auf dem Hyjal zu verlieren.\n\nBaron Geddon auszuschalten hat unserem Feind einen schweren Schlag versetzt.", sourceObjectiveStatus = "unverified-source-field" }
quests[25465] = { id = 25465, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Immer noch am Riesen schrumpfen", description = "He, Ihr da! Ich arbeite immer noch an einer Variante von gnomischen Schrumpfstrahlen, benutze aber die weitaus bessere GOBLIN-Technologien dafür! Um Unannehmlichkeiten wie beispielsweise meinen Tod zu vermeiden, möchte ich Euch bitten, es für mich an den Meeresriesen an der Küste zu testen. Ihr solltet nach dem Prozess Schrumpfüberreste auf ihnen finden, bringt mir diese bitte!", sourceObjective = "Benutzt Zorbins Ultraschrumpfer, um Uferschreiter zu schrumpfen und sammelt 6 Schrumpfüberreste.", progress = "Ich musste den Schrumpfer überarbeiten, damit er nicht mehr bei Bergriesen funktioniert. Ich bin zwar nicht rumgerannt und hab wie wild alles geschrumpft, aber die Nachtelfen haben mir ganz schön einen übergehauen, als sie gesehen haben, dass die Bergriesen geschrumpft waren.", completion = "Großartig! Wie ich sehe, habt Ihr nicht nur die Überreste mitgebracht, sondern seid sogar noch in einem Stück! Äh... natürlich gab es nie irgendwelche Gefahren bei der Verwendung des Ultraschrumpfers.\n\nIch muss mich bei Euch für Eure Bemühungen bedanken, {name}. Ihr seid ein wirklicher Freund der Goblins. Akzeptiert dies als Zeichen meiner Dankbarkeit!", sourceObjectiveStatus = "unverified-source-field" }
quests[25466] = { id = 25466, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Noch mehr Treibstoff fürs Schrumpfen", description = "Wenn ich gegen mein besseres Wissen und Gewissen handele und nun doch bleibe, um meinen Ingenieurladen an der Vergessenen Küste aufzumachen, muss ich mich dringend um diese nervigen Elementare kümmern. Verdammt sei der unkontrollierte Elementalismus, sage ich!\n\nGlücklicherweise stellen die Elementare eine ideale Quelle reiner Kraft für meinen Ultraschrumpfer dar – insofern, gebt ihnen Saures! Wenn Ihr dies allerdings tut, bringt mir doch bitte auch ein paar Elementarkerne.", sourceObjective = "Sammelt 10 Wasserelementarkerne von den Meereselementaren und Meeresschauern.", progress = "Ich könnte Euch natürlich auch mit den technischen Einzelheiten langweilen, die sich hinter den Elementarkernen verstecken, aber stattdessen werde ich Euch dazu bringen, diese Aufgabe abzuschließen, indem ich Euch wertvolle Münzen und Belohnungen dafür anbiete. Seid Ihr schon fertig?", completion = "Hervorragend! Diese Kerne werden mich einige Zeit beschäftigen. Nicht zu vergessen, dass es entlang der Küste nun weniger Elementare gibt, die uns Sorgen bereiten werden. Möglicherweise muss ich mich jetzt nicht mehr in den Schlaf weinen, wenn ich daran denke, dass ich mein Lager ausgerechnet am schlimmsten Ort der Welt aufgeschlagen habe.\n\nVielen Dank, {name}, für Eure Hilfe in dieser Angelegenheit. Es mag vielleicht meine Finanzen ein wenig überstrapazieren, aber ich denke, ich möchte mein Wohlwollen Euch gegenüber in einer Weise ausdrücken, die Ihr versteht... ich hätte da etwas Ausrüstung für Euch!", sourceObjectiveStatus = "unverified-source-field" }
quests[25467] = { id = 25467, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kliklaks Kehle", description = "<Ihr seid angenehm überrascht, dass die Karte noch gut lesbar ist, nachdem sie von einem Meereskrebs so zerfetzt und zerkaut wurde.>\n\n<Sie zeigt ganz deutlich, dass im Tang'tharwald hinter einem riesigen Schalentier eine Schließkiste vergraben liegt.>\n\n<Eine gut getroffene Zeichnung auf der Rückseite der Karte zeigt, dass der Besitzer zusammen mit dem Schlüssel von einem überdimensionalen Krustentier namens Kliklak gefressen wurde.>", sourceObjective = "Beschafft Euch den rostigen Schlüssel von Kliklak, um die halb vergrabene Schließkiste im Tang'tharwald zu öffnen.", progress = "<Das Schlüsselloch der Kiste ist mit kleinen Muscheln verkrustet, sieht aber noch funktionstüchtig aus.>", completion = "<Dem befriedigenden Geräusch einer sich öffnenden Truhe folgt der Anblick eines einst versteckten Schatzes.>", sourceObjectiveStatus = "unverified-source-field" }
quests[25468] = { id = 25468, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Naturgewalten: Feendrachen", description = "Man sieht es ihnen wirklich nicht an, aber die reizenden Feendrachen dieses Waldes können sich mit der richtigen Abrichtung als furchterregend erweisen. Sie können unglaubliche Sachen mit magischer Energie anstellen... sie aufsaugen, umleiten und sogar komplett auslöschen.\n\nAlleine sind sie beinahe harmlos, aber in Gruppen können sie in einem Kampf für überwältigende Ergebnisse sorgen. Ihr könnt Feendrachen in den Feldern nordwestlich von hier finden, aber seid vorsichtig, denn die Horde ist in der Nähe.", sourceObjective = "Benutzt Jesanas Feendrachenlockruf, um 10 Grimmlingdrachen oder Grimmlingflitzer zu versammeln.", completion = "Sind sie nicht entzückend? Die Welpen sind sogar noch süßer.", sourceObjectiveStatus = "unverified-source-field" }
quests[25469] = { id = 25469, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Naturgewalten: Bergriesen", description = "Die Bergriesen sind unsere mächtigsten Verbündeten in den Wäldern. Sie bestehen aus dem Land selbst.\n\nWenige unserer Feinde wollen sich mit einem wandelnden Berg anlegen. Schon allein ein paar wenige Bergriesen können den Ausgang einer Schlacht bestimmen.\n\nDie Bergriesen hier leiden aber seit einiger Zeit an einer Krankheit - die Bergriesen im Südwesten scheinen aber gesund zu sein.", sourceObjective = "Benutzt Jesanas Riesenlockruf, um 5 Bergriesen zu versammeln.", completion = "Ausgezeichnet!\n\n{name}, Ihr habt uns geholfen, unsere Streitkräfte zu stärken und habt viele dieser Waldkreaturen vor der Horde gerettet. Unsere Armee ist bereit und Mondfederfeste wird allen Bedrohungen standhalten, von der Horde und anderen Feinden!\n\nIm Namen von Lady Mondfeder überreiche ich Euch diese Waffe, die einer Schildwache würdig ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[25470] = { id = 25470, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Herrin der Tiger", description = "Erinnat Iah Euch an die Frösche, die Iah zu mein'n Augen un' Ohren gemacht habt? Tja, die ham was Intressantes gefund'n.\n\nAuf 'ner Insel im Südosten ham sie 'nen Tiger entdeckt, den soga die andern Katzen fürcht'n. Diesa Tiger, so was hab'ich noch nie geseh'n.\n\nDea jagt mit'm Instinkt von 'ner Katze, aber dem Vastand von 'ner Person. Könnte 'n mächtiger Geist sein, und 'n starka Vabündeta.\n\nIch ruf den Geist vom Tiger auf Euch runter. Benutzt seine Talente, um die Katze zu find'n un' rauszufordern. Seht zu, dass Iah ihre Hilfe in unserm Kampf um die Inseln gewinnt.", sourceObjective = "Lockt die Tigermatriarchin aus ihrem Versteck, während Ihr vom Geist des Tigers erfüllt seid, und benutzt Eure neuen Fähigkeiten, um sie im Kampf zu besiegen.", progress = "Habta schon was üba diesen Tiger rausgefund'n?", completion = "Vaniras Frösche sagen also die Wahrheit? Dieser Tiger ist eine Druidin und eine Verbündete? Das hätte nicht besser laufen können. Das ist ein gutes Omen für die kommende Schlacht.", sourceObjectiveStatus = "unverified-source-field" }
quests[25471] = { id = 25471, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Über den Großen Graben", description = "Wenn wir herausfinden wollen, was die Naga hier vorhaben, müssen wir weiter nach Vashj'ir vordringen.\n\nGeht zu den Lichtlosen Weiten, der riesigen Schlucht, die an den Tang'tharwald im Westen grenzt. Wenn Ihr hinüberseht, solltet Ihr eine Ansammlung von Pflanzen sehen, die den Eingang zur Dunstlichtkammer umgeben.\n\nSobald Ihr in der Höhle seid, dauert es eine ganze Weile, bis Ihr an die Oberfläche kommt, aber ich habe dort Freunde, die Euch herzlich willkommen heißen werden.", sourceObjective = "Sprecht mit Scharfseher Gadra in der Dunstlichtkammer.", completion = "Hallo, Mann! Ihr seht kompetenter aus als die meist'n, die hier durchkomm'n.\n\nKommt und ruht Euch 'n wenig aus. Fühlt Euch ganz wie daheim!", sourceObjectiveStatus = "unverified-source-field" }
quests[25472] = { id = 25472, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Flammenseherstab", description = "Ein mächtiges Artefakt, das als Flammenseherstab bekannt ist, befand sich das letzte Mal, als der Hyjal angegriffen wurde, im Besitz eines Ältesten der Tauren. Es war ein uralter Knochenstab, der seinem Besitzer die Macht über die Feuerelemente verlieh.\n\nSeine Fragmente sind überall hier verstreut. Findet sie und bringt sie zu Malfurion. Vielleicht können wir die Macht des Artefakts noch nutzen.", sourceObjective = "Sammelt 8 verkohlte Knochenstabfragmente.", progress = "Ja, {name}?", completion = "Ausgezeichnet, {name}. Dies wird eine ausgezeichnete Waffe gegen die feindlichen Armeen sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[25473] = { id = 25473, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kaja'Cola", description = "Sassy Hartzang hat mich damit gelöchert, ihr etwas Kaja'Cola für die Party zu Euren Ehren heute Abend zu besorgen.\n\nUps, war das eine Überraschung? Von mir habt Ihr es nicht!\n\nNaja, aber mit dem Produktionstief der letzten paar Tage ist das hier alles, was ich herstellen konnte. Könntet Ihr es ihr bringen?", sourceObjective = "Bringt das Sechserpack Kaja'Cola zu Sassy Hartzang im Hauptquartier der HGK in Kezan.", progress = "<Sassy beobachtet das Sechserpack als würde sie erwarten dass es explodiert, sobald Ihr es ihr gegeben habt.>\n\nWir brauchen mehr Kaja'Cola als das.\n\nIch schwöre, ich werde Feuchtlunte feuern, wenn ich ihn nicht zuerst umbringe!", completion = "Nur dass Ihr es wisst: Kaja'Cola gibt es überall hier im Ort. Es ist das meistverkaufte Produkt des Bilgewasserkartells aller Zeiten! \n\nVergesst nicht, dass ein gepflegtes Image das A und O ist, wenn Ihr auf eine weitere Beförderung aus seid!\n\nNein, wartet! Profit ist das A und O! Aber Explosionen kommen gleich danach. Und dann: Image!", sourceObjectiveStatus = "unverified-source-field" }
quests[25474] = { id = 25474, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Noch einmaal mit Gefühl", description = "Aale gehören zu den widerlichsten Wesen in ganz Azeroth.\n\nSicher, da gibt es diejenigen, denen sie angeblich egal sind. Und dann noch diejenigen, die sogar behaupten, sie zu mögen.\n\nSie lügen.\n\nIn Wahrheit mag nämlich niemand Aale. Nicht einmal Aale mögen Aale.\n\nAzeroth wäre ein besserer Ort, wenn niemand sich ausmalen müsste, wie ein glitschiger Aal sich aus den trüben Tiefen hervor windet und zubeißt.\n\nMitten ins Gesicht.", sourceObjective = "Tötet 15 beliebige Aale im Tang'tharwald.", sourceObjectiveStatus = "unverified-source-field" }
quests[25475] = { id = 25475, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Findet OOX-22/FE!", description = "Ihr habt ein merkwürdiges Gerät aus Metall entdeckt, das die Form eines Eis hat. Als Ihr einen der Knöpfe berührt, erwacht das Ei zum Leben und verwandelt sich in eine Art Gnom-Roboter-Apparat! Aus dem Inneren des Roboteis erklingt eine rasselnde Stimme.\n\n\"Mein Name ist Glotz Widrikus und mein Leitroboter ist abgestürzt! Ich werde Euch belohnen, wenn Ihr ihn aufspürt. Bringt dem Roboter bitte diesen Signalgeber!\"\n\n\"Ich habe jetzt die Koordinaten des Roboters für Euch berechnet. Er ist in der Nähe des Wildschrammtals abgestürzt!\"", sourceObjective = "Bringt das Notrufsignal zu Glotz' Leitroboter in einer Höhle in der Nähe des Wildschrammtals.", progress = "Ihr habt anscheinend das Wrack eines... Robothuhns entdeckt... Aus dem Ei erklingt wieder die rasselnde Stimme:\n\n\"Ja, hervorragende Arbeit! Das ist tatsächlich mein Leitroboter, aber meine Sensoren zeigen an, dass er Starthilfe benötigt, bevor er zur Reparatur nach Beutebucht zurückfliegen kann. Bitte legt den Signalgeber in den Rover. Der Signalgeber wird den Rest übernehmen!\"", completion = "Ihr legt das Ei... das Notsignal... in das Huhn... den Leitroboter.\n\nAus dem Roboter ertönt ein Brummen und Surren, als er versucht aufzustehen. Nachdem der Roboter zum Leben erwacht ist, ertönt die Stimme von Glotz ein weiteres Mal, diesmal aus dem Inneren des Roboters:\n\n\"OOX-22/FE funktioniert endlich, aber es sind umfangreiche Reparaturen erforderlich! Er ist zu schwer, als dass Ihr ihn tragen könntet... aber ich glaube, ich habe eine Idee. Könntet Ihr noch etwas auf ihn aufpassen?\"", sourceObjectiveStatus = "unverified-source-field" }
quests[25476] = { id = 25476, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rettet OOX-22/FE", description = "Aus dem Roboter ertönt erneut die blecherne Stimme des Gnoms:\n\n\"Ich muss OOX-22/FE an einen offenen, sicheren Ort schaffen, wo er die langwierige Startprozedur beginnen kann. Er hat eine eingebaute Tarnvorrichtung, aber ich brauche etwas Zeit, um sie von hier aus wieder zum Funktionieren zu bringen. Eskortiert den Roboter von seinem momentanen Standort zu, ach, sagen wir mal, der Hauptstraße. Das sollte der perfekte Ort für mein Vorhaben sein und bis Ihr dort seid, sollte ich auch alles vorbereitet und aktiviert haben.\"\n\n\"Eskortiert ihn dorthin und kommt dann zu mir nach Beutebucht! Glotz Widrikus - Ende!\"", sourceObjective = "Bringt OOX-22/FE in Sicherheit und meldet Euch dann bei Glotz Widrikus in Beutebucht.", completion = "Ach, IHR habt so heldenhaft OOX-22/FE gerettet! Ich kann meine Dankbarkeit für Eure Hilfe nicht einmal ansatzweise ausdrücken! In meine Serie von Leitrobotern muss noch viel Entwicklungsaufwand gesteckt werden, aber Eure Bergung des Roboters hat mir zahllose Stunden zusätzlicher Schraubarbeit gespart, ganz zu schweigen von dem vielen Gold, das ich spare, weil ich ihn nicht neu bauen muss!\n\nBitte sucht Euch einen von diesen Gegenständen hier aus. Ich danke Euch nochmals für Eure großzügige Hilfe, {name}; meine Roboter und ich stehen in Eurer Schuld!", sourceObjectiveStatus = "unverified-source-field" }
quests[25477] = { id = 25477, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Besser spät als tot", description = "Grüße, Freund.\n\nSchön zu sehen, dass Ihr die Schlacht heil überlebt habt.\n\nWährend Erunak nach einem sicheren Zufluchtsort für uns sucht, werde ich Euch dabei helfen, ein weniger anstrengendes Transportmittel zu finden.\n\nIch habe Euch einen Köderstab vorbereitet. Benutzt ihn in der Nähe einer Meeresschildkröte. Es ist vielleicht etwas primitiv, aber damit solltet Ihr das Tier unter Eure Kontrolle bekommen.\n\nSobald Ihr Euch mit der Schildkröte vertraut gemacht habt, führt sie einfach hierher zu mir.", sourceObjective = "Benutzt Moanahs Köderstab bei einer gesprenkelten Meeresschildkröte und reitet dann mit ihr zurück zu Moanah.", progress = "Konntet Ihr eine Meeresschildkröte zähmen, {name}?", completion = "Wie überaus bedauerlich…\n\nNun, in Anbetracht der Tatsache bin ich froh, dass Ihr unversehrt zurückgekommen seid.", sourceObjectiveStatus = "unverified-source-field" }
quests[25478] = { id = 25478, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zum Gipfel", description = "Wir sind dabei, am Westlichen Gipfel für das ganze Gebiet in Tausend Nadeln Hilfsmaßnahmen in die Wege zu leiten. Der Goblin Dyslix Silberraff wird Euch meinen Windreiter zur Verfügung stellen, so dass Ihr sicher ankommt. Sprecht mit Kanati Grauwolke, sobald Ihr gelandet seid.\n\nIhr müsst Euch beeilen, um Leben retten zu können!", sourceObjective = "Leiht Euch von Dyslix Silberraff einen Windreiter und sprecht mit Kanati Grauwolke am Westlichen Gipfel in Tausend Nadeln.", completion = "Nyse schickt Euch? Gut! Wir brauchen Eure Hilfe, jetzt gleich!", sourceObjectiveStatus = "unverified-source-field" }
quests[25479] = { id = 25479, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nach Neu-Thalanaar", description = "Wir sind dabei, in Neu-Thalanaar für das ganze Gebiet in Tausend Nadeln Hilfsmaßnahmen in die Wege zu leiten. Der Goblin Dyslix Silberraff wird Euch meinen Hippogryph zur Verfügung stellen, so dass Ihr sicher ankommt. Sprecht mit Caryssia Jägermond, sobald Ihr gelandet seid.\n\nIhr müsst Euch beeilen, um Leben retten zu können!", sourceObjective = "Leiht Euch von Dyslix Silberraff einen Hippogryph und sprecht mit Caryssia Jägermond in Neu-Thalanaar in Feralas.", completion = "Thyssiana schickt Euch? Gut! Wir brauchen Eure Hilfe, jetzt gleich!", sourceObjectiveStatus = "unverified-source-field" }
quests[25480] = { id = 25480, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tanz der Geister", description = "Die Zeit ist reif, über den Angriff nachzudenken. Champion Uru'zin sagt, seine Männer wären bereit. Ihr und Vanira habt gute Arbeit geleistet, indem ihr Informationen gesammelt und uns neue Verbündete gefunden habt.\n\nJetzt lesen wir die Omen. Wir müssen rausfinden, wann wir den Angriff starten können.\n\nFindet Hexendoktor Hez'tok beim Kreis der Ritualtänzer. Er wird das Ritual anfangen, sobald Ihr bereit seid.", sourceObjective = "Sprecht beim Kreis der Ritualtänzer außerhalb von Sen'jin mit Hexendoktor Hez'tok, wenn Ihr bereit seid, die Omen zu konsultieren.", progress = "Und, was sagen die Omen?", completion = "Ich werde mir den Rat der Geister zu Herzen nehmen. Mit ihnen hinter uns und der Macht der uralten Loas des Dunkelspeerstammes sind wir bereit, uns zurückzuholen, was uns gehört!", sourceObjectiveStatus = "unverified-source-field" }
quests[25481] = { id = 25481, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nach Neu-Thalanaar", description = "Wir sind dabei, in Neu-Thalanaar für das ganze Gebiet in Tausend Nadeln Hilfsmaßnahmen in die Wege zu leiten. Seyala Elmsfeuer wird Euch meinen Hippogryph zur Verfügung stellen, so dass Ihr sicher ankommt. Sprecht mit Caryssia Jägermond, sobald Ihr gelandet seid.\n\nIhr müsst Euch beeilen, um Leben retten zu können!", sourceObjective = "Leiht Euch von Seyala Elmsfeuer einen Hippogryph und sprecht mit Caryssia Jägermond in Neu-Thalanaar in Feralas.", completion = "Falfindel Wegeshut schickt Euch? Gut! Wir brauchen Eure Hilfe, jetzt gleich!", sourceObjectiveStatus = "unverified-source-field" }
quests[25482] = { id = 25482, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "World Event Dungeon - Headless Horseman" }
quests[25483] = { id = 25483, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "World Event Dungeon - Coren Direbrew" }
quests[25484] = { id = 25484, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "World Event Dungeon - Ahune" }
quests[25485] = { id = 25485, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "World Event Dungeon - Hummel" }
quests[25486] = { id = 25486, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Grimmtotem kommen", description = "Es wird eine Zeit lang dauern, aber ich bin sicher, dass wir sie zurückschlagen können.\n\nIhr könnt Tausend Nadeln am besten von einem anderen Ort aus helfen. Es wurde uns berichtet, dass die Gnome und Goblins in den überfluteten Salzwüsten es irgendwie geschafft haben, irgendwie auf einem riesigen Dampfer zu überleben! Rendow an den Docks hat ein Boot, das sie Euch geben kann, um zu dem Dampfer zu gelangen.\n\nEs stört Euch doch nicht, uns auf dem Weg zu ihm ein wenig zu helfen?", sourceObjective = "Tötet 7 Marodeure der Grimmtotem.", completion = "Ein Boot? Ja, dieses hier könnt Ihr haben. Es ist das letzte.", sourceObjectiveStatus = "unverified-source-field" }
quests[25487] = { id = 25487, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Grimmtotem kommen", description = "Die feigen Grimmtotem haben uns überraschenderweise angegriffen, als wir überhaupt nicht vorbereitet waren!\n\nIhr werdet Tausend Nadeln von einem anderen Ort aus besser helfen können, {class}. Es gehen Gerüchte um, dass die Goblins und Gnome irgendwie auf einem Dampfer in den Salzwüsten überlebt haben.\n\nMotega Feuermähne ist auf dem Hügelplateau zu finden - er kann Euch ein Kanu geben, um dorthin zu gelangen.\n\nStört es Euch, wenn Ihr auf Eurem Weg dorthin ein paar Grimmtotem für uns bekämpft?", sourceObjective = "Tötet 7 Plünderer der Grimmtotem.", completion = "Ihr möchtet ein Kanu, um nach Salzwüste zu gelangen? Die Rennbahn wurde doch komplett zerstört?!\n\nWie dem auch sei, für Euren Mut werde ich Euch mein letztes Kanu geben.", sourceObjectiveStatus = "unverified-source-field" }
quests[25488] = { id = 25488, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zwei per Boot", description = "Seid Ihr bereit, {class}? Eine der Schildwachen wird Euch zu der Illusionenrennbahn begleiten.\n\nFalls es dort Überlebende geben sollte, helft ihnen bitte.\n\nDie Göttin stehe Euch bei!", sourceObjective = "Sprecht mit Fizzel Kupferbolz auf Fizzels & Pozziks Turbodampfer in Tausend Nadeln.", completion = "JA?! Unterbreche ich etwa Eure faszinierende Diskussion?\n\nNein... Nein, bitte, redet nur weiter. Ich bin sicher, dass Eure Störung mit etwas sehr Wichtigem zu tun hat. Wichtiger, als sich um das Überleben aller hier zu kümmern, ganz bestimmt.\n\n<Fizzel wippt ungeduldig mit dem Fuß.>", sourceObjectiveStatus = "unverified-source-field" }
quests[25489] = { id = 25489, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zwei per Boot", description = "Seid Ihr bereit, {class}? Einer unserer Kriegerhelden wird Euch zu der Illusionenrennbahn rudern.\n\nFalls es dort Überlebende geben sollte, so werden sie Eure Hilfe dringend benötigen.\n\nMöge die Erdmutter Euch mit einem Lächeln segnen!", sourceObjective = "Sprecht mit Pozzik auf Fizzels & Pozziks Turbodampfer in Tausend Nadeln.", completion = "Hallo, Kindchen, ich bin gleich bei Euch. Muss vorher nur diesen Gnomheini hier dazu bringen, den Mund zu halten.", sourceObjectiveStatus = "unverified-source-field" }
quests[25490] = { id = 25490, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Asche auf ihr Haupt", description = "{name}, diese Fanatiker des Schattenhammers wollen alles Leben auf diesem Berg vernichten. Selbst jetzt folgen sie diesem Inferno und legen auf ihrem Weg alles in Schutt und Asche.\n\nErzdruide Hamuul Runentotem ist den Feuern auf den Fersen und versucht, die Wildnis zu retten, bevor sie voll und ganz von der Karte verschwindet. Reist nach Südosten durch das Inferno und die dahinterliegende Straße entlang. Findet den Erzdruiden und helft ihm.\n\nBefreit auf Eurem Weg dorthin die Straßen von allen Versengern, die Euch begegnen.", sourceObjective = "Tötet 8 Versenger.", completion = "Sehr gut. Wir müssen dem Schattenhammer deutlich klar machen, dass wir nie aufgeben werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[25491] = { id = 25491, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Robuste Saat", description = "Dieses Land wurde vom Feuer völlig versengt, aber es kann sich vielleicht dennoch wieder erholen.\n\nEinige Samen tief im Boden haben die sengende Hitze in der Flammenschneise möglicherweise überlebt. Diese robusten Samen sind der Schlüssel zur Wiedererweckung dieses Waldes. Bitte, sammelt einige dieser Setzlinge für mich.", sourceObjective = "Sammelt 10 Hyjalsetzlinge aus den Haufen versengter Erde.", progress = "Ich glaube, dass immer noch Leben unter der Asche herrscht. Was konntet Ihr finden?", completion = "<Der Erzdruide untersucht die Setzlinge.>\n\nDiese Setzlinge haben einen Weltuntergang überlebt. Selbst wenn es nur eine Handvoll ist, haben sie doch unglaubliche Macht. Das Leben erholt sich stets von ganz alleine und ist danach oft stärker als je zuvor.\n\nSobald der Weg frei ist, werden wir diese Setzlinge benutzen, um auf diesem Berg ein Wunder zu wirken, {name}. Ihr werdet schon sehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25492] = { id = 25492, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feuerschneise", description = "In ihrem Bestreben, den Hyjal zu vernichten, lassen die Schattenhammer Elementare die Erde nach dem Feuer versengen.\n\nSie pulverisieren den Boden, wühlen in der Asche und graben jede noch so kleine Pflanze aus, die überlebt hat, um sie zu zerstören. Es scheint fast so, als würden sie den Weg pflastern für... Ich möchte es mir nicht einmal vorstellen.\n\nHaltet sie auf, bevor es kein Leben mehr auf dem Hyjal gibt. Tötet die Lavawoger!", sourceObjective = "Tötet 10 Lavawoger.", completion = "Gute Arbeit, {name}. Der Wald hat eine Chance, sich doch noch zu erholen.\n\nDoch es gibt noch etwas anderes, was Ihr für mich erledigen sollt…", sourceObjectiveStatus = "unverified-source-field" }
quests[25493] = { id = 25493, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Frische Köder", description = "Ich war sehr überrascht, zu erfahren, dass der Schattenhammer den großen Schildkrötenahnen Tortolla gefunden und gefangen genommen hat. In diesem Moment ist er am Rande des trüben Aschensees angekettet.\n\nTortolla aus seinen Banden zu befreien wird nicht einfach, aber wir werden einfach einen Schritt nach dem anderen tun.\n\nGeht in die Flammenschneise und sammelt mir Kernhundinnereien. Ich erkläre Euch später warum.\n\nUnd hütet Euch vor Nemesis dem Usurpator, wenn Ihr dort seid! Seine Zeit wird auch noch kommen, aber noch sind wir nicht bereit.", sourceObjective = "Sammelt 4 Kernhundinnereien.", progress = "Habt Ihr die Innereien gesammelt?\n\nKernhunde sind in diesem Teil der Welt nicht heimisch. Sie sind dem Schattenhammer aus den Netherregionen der Erde gefolgt. Lasst Euch von ihrer Ausrottung nicht beunruhigen.", completion = "Sehr gut. Wir werden die Innereien als Köder brauchen, solange sie noch warm sind.\n\nHier ist mein Plan…", sourceObjectiveStatus = "unverified-source-field" }
quests[25494] = { id = 25494, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Halsband für einen Champion", description = "Dieser kleiner Kerl ist wirklich bedrohlich, was?\n\nWenn er ein richtiger Kampfwelpe werden soll, müssen wir ihm ein angemessenes Halsband besorgen.\n\nDie Basiliskenmatriarchin hat ihr Nest an der Straße nach Winterquell errichtet. Bringt mir ihre stachelige Haut, damit wir ein schönes Halsband für unseren kleinen Killer hier daraus machen können.", sourceObjective = "Besorgt Euch die stachelige Basiliskenhaut von der Dornenschuppenmatriarchin.", progress = "Habt Ihr sie bekommen?", completion = "Ausgezeichnet! Unser Welpe ist jetzt bereit für den Kampf.", sourceObjectiveStatus = "unverified-source-field" }
quests[25495] = { id = 25495, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vorbereitung auf die Schlacht", description = "Vol'jin macht seine Ausrüstung klar und die Kriega bereit. Er hat mich gebet'n, Euch zu sag'n, dass Iah ihn und Vanira auf dea Insel im Osten treffen sollt.\n\nVon da werd'n er un die Krieger Zalazane angreif'n. Die Vorfahr'n soll'n Euch beisteh'n, {name}. Ohne Euch wär' diese Sache nur'n Schatten von dem, was sie is. Redet mit Tierführer Marnlek im Süden, un' er wird Euch 'ne Fledermaus geben, die Euch zum Sammelpunkt fliegt.", sourceObjective = "Sprecht mit Tierführer Marnlek, um einen Flug zum Sammelpunkt zu bekommen. Trefft Euch auf der Insel östlich des Kriegslagers mit Vol'jin.", completion = "Endlich, alles fertig. Jetzt zeigen wir Zalazane was mit denen passiert, die sich den Dunkelspeeren in den Weg stellen!", sourceObjectiveStatus = "unverified-source-field" }
quests[25496] = { id = 25496, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erbitterter Zweikampf", description = "Ich weiß nicht, ob Ihr davon gehört habt, aber es gibt eine gewisse Rivalität zwischen den Ogern im Schattenhammerkult und dem Rest von uns.\n\nWas mich angeht… ist die Sache persönlich.\n\nDieser Oger namens Gromm'ko hat einen Raptor als Haustier, sein Name ist Schlächter. Er hat meine letzten drei Kernhundwelpen getötet.\n\nAber mit diesem hier wird er das nicht schaffen. Er hat einen echten Killerinstinkt.\n\nGeht zum Sitz der Auserwählten und fordert Gromm'ko zu einem Duell zwischen den beiden Tieren heraus. Erniedrigt ihn für mich, {name}damus.", sourceObjective = "Fordert Gromm'ko am Sitz der Auserwählten auf dem Hyjal heraus.", progress = "Habt Ihr es geschafft, Ntonjaloleydamus? Hat unser kleiner Champion sich gut geschlagen?", completion = "Genau so macht man das!", sourceObjectiveStatus = "unverified-source-field" }
quests[25497] = { id = 25497, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kopf hoch und Arsch in den Sattel", description = "Unsere Lage hier wird immer verzweifelter, {race}.\n\nWir müssen uns auf die Naga und ihre Gefangenen konzentrieren, aber ohne die richtige Vorbereitung wäre das reiner Selbstmord. Und hier unten heißt das, dass Ihr eine schnellere Fortbewegungsmethode braucht.\n\nDiese Haie mögen Meeresschildkrötenfleisch offensichtlich sehr gerne. Wollen wir doch mal sehen, ob wir das zu unserem Vorteil nutzen können.", sourceObjective = "Benutzt 6 Stück Schildkrötenfleisch, um einen Haihappen herzustellen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25499] = { id = 25499, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beweglichkeitstraining: Rennt wie der Teufel!", description = "Bevor wir weitergehen, müssen wir Euch erstmal in Form bringen.\n\nErgebenheit gegenüber den Alten Göttern wird Euch nicht retten, wenn ein Smaragddrache hinter Euch her ist. Leichtfüßigkeit ist das Stichwort.\n\nDoch genug geredet. Wir werden Euren Trainer herbeirufen. Eure Aufgabe besteht darin, vor ihm wegzurennen, ohne dieses Lager zu verlassen.\n\nLos!", sourceObjective = "Rennt 1 Minute lang vor dem flammenden Trainer weg. Verlasst die Schmiede der Unterwerfung dabei nicht.", progress = "Ja?", completion = "Oh. Ihr seid noch am Leben.\n\nNicht schlecht.", sourceObjectiveStatus = "unverified-source-field" }
quests[25500] = { id = 25500, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wortübermittlung", description = "Da haben wir sie. Das ist die Rede, {name}!\n\nSie hat alles, was ein guter Schlachtauftakt braucht: sie ist inspirierend, benutzt eloquente Sprache und spricht den einfachen Gnom direkt an. Nie wurde eine bessere Rede geschrieben!\n\nGebt sie Hauptmann Tret Funkdüse und fragt ihn, ob er noch etwas von Euch braucht.", sourceObjective = "Gebt die Rede Hauptmann Tret Funkdüse bei Stahlrosts Depot.", progress = "Was habt Ihr da, Rekrut?", completion = "Das ist also Tobys Rede? Fantastisch!\n\nRekrut, Ihr habt alles getan, was wir von Euch verlangen können und die Armee Gnomeregans dankt Euch dafür!\n\nWir haben ein Einsatzteam nach Gnomeregan entsendet und ohne Eure Unterstützung wäre das nicht möglich gewesen! Wir möchten Euch bitten, den Reservisten Gnomeregans beizutreten!\n\nDer Sold ist zwar nicht der Rede wert, aber dafür bekommt Ihr diesen todschicken Helm. Passt gut auf ihn auf, eines Tages könntet Ihr ihn brauchen!", sourceObjectiveStatus = "unverified-source-field" }
quests[25502] = { id = 25502, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vorbereitung des Bodens", description = "Der Erzdruide hat mich damit beauftragt, eine Reihe von Flammenzauberschutzen entlang der Grenze dieses Gebiets aufzustellen. Sobald diese aktiviert sind, können wir weitere Angriffe der Feuerelementare vermeiden, die dieses Tal in Schutt und Asche gelegt haben.\n\nSie schützen und nähren zudem den Boden, was auch immer Hamuul damit bezwecken will.\n\nEs ist an der Zeit, zu beginnen. Sucht einen der fünf Flammenzauberschutze, die ich für Euch auf der Karte markiert habe, aktiviert ihn und verteidigt ihn vor einem Gegenangriff, bis seine Magie zu wirken beginnt. Es wird nicht länger als eine Minute dauern.", sourceObjective = "Aktiviert und verteidigt einen Flammenzauberschutz.", completion = "Das ist gut! Dank Eurer Arbeit und der Arbeit anderer ist dieses Tal vor einem Gegenangriff geschützt.\n\nIch habe alles getan, was ich konnte. Jetzt liegt der Rest bei Euch und dem Erzdruiden.", sourceObjectiveStatus = "unverified-source-field" }
quests[25503] = { id = 25503, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schwarzflosses Beute", description = "<Vor dem letzten Eintrag befindet sich eine lädierte Seite, auf der steht:>\n\nUnser selbsternannter König schreckt vor nichts zurück, um an das Vermögen meiner Familie zu gelangen. Er hat mich unaufhörlich bedroht und belästigt.\n\nIch ertrage es nicht mehr!\n\nIch habe den Schatz vergraben und die Karte an Schwarzflosse verfüttert.\n\nDas sollte die gierigen kleinen Griffel meines Vetters von unseren wertvollen Erbstücken fernhalten!", sourceObjective = "Tötet den Orca Schwarzflosse, um an Gilblingels Karte zu kommen.", progress = "Ihr habt Gilblingels Familienschatz entdeckt!", completion = "Dieser Gegenstand war in den Augen der hiesigen Gilblinbevölkerung von unschätzbarem Wert und wurde sogar von König Gurboggel selbst heiß begehrt!", sourceObjectiveStatus = "unverified-source-field" }
quests[25504] = { id = 25504, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein kleiner Gefallen?", description = "Hallo. Schön, Euch kennenzulernen. Ich bin Fizzel Kupferbolz. Willkommen auf meinem Turbodampfer.\n\nWie auch Euch ist mir die Unterstützung von Tausend Nadeln wichtig, und ich bin davon überzeugt, dass der Turbodampfer der ganzen Region neue Hoffnung bringen kann.\n\nVielleicht könnt Ihr uns hier ein wenig helfen? Ich werde sicherstellen, dass Ihr mit allem versorgt werdet, was dafür benötigt ist.\n\nIhr könnt direkt anfangen, indem Ihr diese Bauteilliste zu Jinky Pfuschelfix in ihrem Laden bringt.", sourceObjective = "Bringt die Bauteilliste zu Jinky Pfuschelfix auf Fizzels & Pozziks Turbodampfer in Tausend Nadeln.", progress = "Ist das jetzt endlich die Bauteilliste? Darauf warte ich schon den ganzen Tag!", completion = "<Jinky wirft einen Blick auf die Liste und spuckt aus!>\n\nIch habe nicht mal die Hälfte von dem Kram hier!", sourceObjectiveStatus = "unverified-source-field" }
quests[25505] = { id = 25505, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein kleiner Gefallen?", description = "Ja hallo, {name}. Ich bin Pozzik, der weltbekannte Raketenwagenfahrer. Willkommen auf meinem Turbodampfer.\n\nWie auch Euch ist mir die Unterstützung von Tausend Nadeln wichtig, und ich bin davon überzeugt, dass der Turbodampfer der ganzen Region neue Hoffnung bringen kann.\n\nVielleicht könnt Ihr uns hier ein wenig helfen? Ich werde sicherstellen, dass Ihr mit allem versorgt werdet, was dafür benötigt ist.\n\nIhr könnt direkt anfangen, indem Ihr diese Bauteilliste zu Razzeric in seinem Laden bringt.", sourceObjective = "Bringt die Bauteilliste zu Razzeric auf Fizzels & Pozziks Turbodampfer in Tausend Nadeln.", progress = "Ist das meine Bauteilliste von Pozzik?", completion = "Heya, Kumpel, kann ich einen Blick auf die Liste werfen?\n\n<Razzeric spuckt fast aus!>\n\nWas denkt sich Pozzik eigentlich? Er weiß doch, dass ich noch nicht mal die Hälfte von dem Zeug hier habe!", sourceObjectiveStatus = "unverified-source-field" }
quests[25506] = { id = 25506, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abgeseilt", description = "Unsere Zeit hier nähert sich dem Ende.\n\nIch muss über die Schlucht reisen und herausfinden, was die Naga hier tun und warum.\n\nWenn Ihr mir folgen möchtet, solltet Ihr erst Eure Suche nach einem geeigneten Reittier abschließen.\n\nSucht nördlich von hier nach einem jungen Kugelfisch. Sobald Ihr einen gefangen habt, bringt ihn zum Graben im Westen. Ich werde dort alles vorbereiten, was Ihr braucht.", sourceObjective = "Findet einen jungen Kugelfisch auf Nagers Friedhof und bringt ihn zum Abgrund in der Nähe der Pferche.", sourceObjectiveStatus = "unverified-source-field" }
quests[25507] = { id = 25507, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Panzerknacker", description = "Diese frischen und stinkenden Innereien sind ein unwiderstehliches Festmahl für Nemesis, den verderbten Schildkrötengott, den der Schattenhammer erschaffen hat. Nemesis muss vernichtet werden, aber noch brauchen wir ihn.\n\nOder besser gesagt ein Stück seines steinigen Panzers. Damit können wir ein magisches Ritual durchführen, um den wahren Ahn zu befreien.\n\nGeht in die Flammenschneise und legt diesen Köder in der Nähe von Nemesis aus. Das wird ihn ablenken. Springt auf seinen Rücken und besorgt Euch ein Stück seines Panzers... Und dann rennt, wenn Ihr die Begegnung überleben wollt.", sourceObjective = "Benutzt die Kernhundinnereien in der Nähe von Nemesis, um ihn abzulenken. Sammelt ein Panzerfragment von Nemesis auf.", progress = "Nemesis besteht aus reinem, kochenden Zorn in einem steinernen Panzer aus Hass.\n\nSeine Zeit wird kommen.", completion = "<Der Erzdruide nimmt mit einer überraschenden Ehrfurcht den Panzer von Euch entgegen.>\n\nNemesis ist ein Instrument des Bösen, aber er wurde aus einem Panzerfragment des wahren Ahnen erschaffen.\n\nDiese Verbindung werden wir uns zu Nutze machen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25509] = { id = 25509, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Körperliches Training: Zwangsarbeit", description = "Das Training, das nötig ist, um zu uns zu gehören, ist nicht gerade angenehm. Warum sollte es das auch sein?\n\nDer Pfad zum Diener der Alten Götter ist lang, schmerzhaft und die reinste Seelenqual. Betrachtet dies als Euren ersten Schritt.\n\nNehmt diese Hacke und baut die Leitsteinvorkommen in der Schlucht ab.\n\nNein, wir brauchen nichts von dem Erz. Dies dient ausschließlich Eurem Vorteil.", sourceObjective = "Baut 5 Flüsterleitsteine ab.", completion = "Sehr gut. Zumindest seid Ihr fähig genug herauszufinden, was man mit dem spitzen Ende einer Hacke anstellt.", sourceObjectiveStatus = "unverified-source-field" }
quests[25510] = { id = 25510, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tortolla spricht", description = "<Der Erzdruide füllt das Panzerfragment mit Wasser, welches sofort zu kochen beginnt. Er fügt ein Bündel Kräuter hinzu und flüstert ein Gebet vor der Statue Malornes.>\n\n{name}, Tortolla, der Schildkrötenahn, kennt kein Alter. Er ist seit der Zeit der Titanen Teil dieser Welt. Er spricht eine Sprache, die älter ist als alles, was wir kennen.\n\nTrinkt dies und begebt Euch an einen Ort der inneren Ruhe. Ihr werdet in der Lage sein, Tortollas Sprache zu verstehen. Geht gleich zu ihm in den Aschensee. Erlangt das Vertrauen des Ahnen. Das Schicksal des Hyjal hängt davon ab.", sourceObjective = "Geht zu Tortolla, dem Schildkrötenahnen, im Aschensee auf dem Hyjal.", completion = "{race}.\n\nDiese Sprache. Ist nicht Eure.\n\nWas wollt Ihr... Peiniger?", sourceObjectiveStatus = "unverified-source-field" }
quests[25513] = { id = 25513, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Donnerkuppel: Erbitterter Zweikampf", description = "Wir haben eine Sonderanfrage erhalten! Ich habe hier eine Notiz von einer Kelsey Stahlfunken, die den Käfig betreten und etwas aus der Welt schaffen möchte.\n\nSie hat Euch als Wunschpartner angegeben, {name}. Ein Fan Eurer alten Erfolge? Oder vielleicht kennt Ihr Euch von woanders?\n\nIch würde an Eurer Stelle nicht absagen. Das klingt nach einem wunderbaren Finale...", sourceObjective = "Besiegt Megs Schredderschreck.", completion = "Fantastisch. Ich werde Euch selbst vielleicht einmal zu einem Duell herausfordern.", sourceObjectiveStatus = "unverified-source-field" }
quests[25514] = { id = 25514, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Bande brechen", description = "Aus den Tiefen…\nEin Reich der Dunkelheit und des Feuers.\nGreift nach mir in meinem Schlaf.\n\nIch bin gefesselt, {race}.\n\nSchatten lauern in den Feuerruten neben mir.\n\nTötet sie.\n\nAuf dass ich wieder frei sei.", sourceObjective = "Deaktiviert die beiden Ruten der Unterwerfung, die Tortolla binden.", progress = "Sie sind nicht von dieser Welt.\n\nSie kennen weder Erbarmen noch Furcht.", completion = "<Tortolla zittert und schüttelt den Schmutz von seinem riesigen Rücken.>\n\nIhr…\nSeid nicht wie die anderen.\n\nIch bin wieder frei.\n\nDie anderen…\nWerden bezahlen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25515] = { id = 25515, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In den Tiefen", description = "<Jinky krempelt die Ärmel hoch und streicht sich die Haare aus dem Gesicht, während sie Euch genau beobachtet.>\n\nNun gut, wenn Fizzel will, dass Ihr Euer eigenes Boot bekommt, dann müssen wir zuerst die Teile dafür besorgen. Und jetzt ratet mal, wer sie besorgen wird!\n\n<Jinky lächelt, zeigt nach unten und holt daraufhin einen Ersatztaucherhelm und Flossen hervor.>\n\nGenau, <Bruder/Schwester>. Ihr werdet Euch in die Tiefen wagen und alle Raketenwagenteile bergen, die Ihr in den Rennbahnruinen finden könnt.", sourceObjective = "Sammelt 10 Raketenwagenteile.", progress = "Eure Arbeitszeit werde ich erst festhalten, wenn Ihr mir alle Teile gebracht habt, die auf der Bauteilliste stehen.", completion = "Fürs Erste werden wir uns damit zufriedengeben müssen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25516] = { id = 25516, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In den Tiefen", description = "Nun gut, wenn Pozzik möchte, dass Ihr Euer eigenes Boot bekommt, dann müssen wir zuerst die Teile dafür besorgen. Und jetzt ratet mal, wer sie besorgen wird!\n\n<Razzeric lächelt und zeigt nach unten; daraufhin holt er einen Ersatztaucherhelm und Flossen hervor.>\n\nJa, Ihr habt leider recht. Ihr werdet Euch in die Tiefen wagen und alle Raketenwagenteile bergen, die Ihr in den Rennbahnruinen finden könnt.", sourceObjective = "Sammelt 10 Raketenwagenteile.", progress = "Wir können anfangen, sobald wir alle Teile von der Liste haben.", completion = "Das ist schon mal ein guter Anfang!", sourceObjectiveStatus = "unverified-source-field" }
quests[25517] = { id = 25517, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schenkenschlägerei!", description = "Diese stinkenden Goblinnichtsnutze werden trotz ihres hellgrünen Alters jetzt etwas erleben!\n\nGeht zur Turbodampferschenke, bestellt eine Flasche Grog, und haut einem der Goblins damit auf den Kopf!\n\nMacht ihnen klar, dass wir ihre Frechheiten nicht länger dulden werden, {name}!", sourceObjective = "Provoziert eine Schlägerei in der Schenke!", completion = "So ist es richtig! Ihr seid ein wahrer Segen für die Allianz!\n\nIhr solltet wissen, dass Ihr das in der Schenke jederzeit wieder machen könnt, wenn Ihr wollt. Ich kann Euch dazu nur ermuntern!", sourceObjectiveStatus = "unverified-source-field" }
quests[25518] = { id = 25518, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schenkenschlägerei!", description = "Diese winzigen, hässlichen und nichtexplodierenden Gnome werden jetzt etwas erleben!\n\nGeht zur Turbodampferschenke, bestellt eine Flasche Grog, und haut einem der Gnome die Flasche über den Kopf!\n\nMacht ihnen klar, dass wir ihre arrogante Art nicht länger dulden werden, {name}!", sourceObjective = "Provoziert eine Schlägerei in der Schenke!", completion = "Ja! Ihr seid sehr nützlich für die Horde!\n\nIhr solltet wissen, dass Ihr das in der Bar jederzeit wieder machen könnt, wenn Ihr wollt. Ich kann Euch dazu nur ermuntern!", sourceObjectiveStatus = "unverified-source-field" }
